// SEG-007-T178 correction: A7/SP is excluded from the finite-An Tier-1 proof.
// Even a directly-foldable `LEA <abs>,A7` must NOT produce a finite A7 set, so
// `JMP (A7)` stays fail-closed.
void general_startup_an_indirect_jmp_through_a7_stays_unresolved() {
  using namespace segarecomp;
  const std::vector<std::uint8_t> image{
      0x4FU, 0xF9U, 0x00U, 0x00U, 0x0BU, 0x0CU,  // 0x0B00: LEA (0x00000B0C).L,A7
      0x4EU, 0xD7U,                              // 0x0B06: JMP (A7)
      0x00U, 0x00U,                              // 0x0B08: not a target
      0x00U, 0x00U,                              // 0x0B0A: not a target
      0x4EU, 0x70U,                              // 0x0B0C: would-be target (RESET)
  };
  const auto result = analyze_m68k_frontend(an_indirect_fixture::make_program(image, 0x00000B00U));
  const auto unresolved = [&] {
    if (const auto *rejected = std::get_if<FrontendRejected>(&result))
      return rejected->category == DirectFlowDiagnostic::reached_unresolved_direct_edge &&
             rejected->source_address && rejected->source_address->value == 0x00000B06U;
    if (const auto *partial = std::get_if<FrontendPartialProgram>(&result))
      return partial->accepted_prefix.indirect_target_ea_sets.empty() && partial->frontiers.size() == 1U &&
             partial->frontiers.front().class_ == GenesisFrontierClass::unresolved_indirect_target &&
             partial->frontiers.front().diagnostic.source_address &&
             partial->frontiers.front().diagnostic.source_address->value == 0x00000B06U;
    return false;
  }();
  expect(unresolved, "LEA <abs>,A7 does not produce a finite A7 set; JMP (A7) stays fail-closed with no target-EA set");
}

// SEG-007-T178 correction: a stack-mutating instruction between the LEA and the
// transfer (here PEA, which implicitly does A7 -= 4) must not leave a stale
