void general_startup_an_indirect_jmp_one_inadmissible_candidate_fails_the_whole_proof_closed() {
  using namespace segarecomp;
  // Path B (taken BNE) proves A0 = 0x0B10 (mapped); path A adds 0x1000 giving
  // 0x1B10, outside every mapping claim. One inadmissible candidate fails the
  // whole all-or-nothing proof closed.
  const std::vector<std::uint8_t> image{
      0x41U, 0xF9U, 0x00U, 0x00U, 0x0BU, 0x10U,  // 0x0B00: LEA (0x00000B10).L,A0
      0x66U, 0x04U,                              // 0x0B06: BNE.S -> 0x0B0C
      0xD0U, 0xFCU, 0x10U, 0x00U,                // 0x0B08: ADDA.W #0x1000,A0  -> 0x1B10 (unmapped)
      0x4EU, 0xD0U,                              // 0x0B0C: JMP (A0)
      0x4EU, 0x70U,                              // 0x0B0E: RESET
  };
  const auto result = analyze_m68k_frontend(an_indirect_fixture::make_program(image, 0x00000B00U));
  const auto unresolved = [&] {
    if (const auto *rejected = std::get_if<FrontendRejected>(&result))
      return rejected->category == DirectFlowDiagnostic::reached_unresolved_direct_edge &&
             rejected->source_address && rejected->source_address->value == 0x00000B0CU;
    if (const auto *partial = std::get_if<FrontendPartialProgram>(&result))
      return partial->accepted_prefix.indirect_target_ea_sets.empty() && partial->frontiers.size() == 1U &&
             partial->frontiers.front().class_ == GenesisFrontierClass::unresolved_indirect_target &&
             partial->frontiers.front().diagnostic.source_address &&
             partial->frontiers.front().diagnostic.source_address->value == 0x00000B0CU;
    return false;
  }();
  expect(unresolved, "one inadmissible (unmapped) An candidate fails the whole An-indirect proof closed");
}

void general_startup_route_without_a_provable_an_indirect_transfer_emits_no_indirect_lowering() {
  using namespace segarecomp;
  // A JSR (A0) whose A0 is never provably finite must not gain any spurious
  // indirect-target array or membership guard; the emission stays a clean,
  // deterministic fail-closed frontier.
  const std::vector<std::uint8_t> image{
      0x30U, 0x51U,  // 0x0B00: MOVEA.W (A1),A0  (A0 unknown)
      0x4EU, 0x90U,  // 0x0B02: JSR (A0)
      0x4EU, 0x70U,  // 0x0B04: RESET
  };
  const auto result = analyze_m68k_frontend(an_indirect_fixture::make_program(image, 0x00000B00U));
  const auto *partial = std::get_if<FrontendPartialProgram>(&result);
  if (partial == nullptr) {
    expect(std::get_if<FrontendRejected>(&result) != nullptr, "an unprovable An-indirect JSR fails closed");
    return;
  }
  const auto first = expand_entry_rows(emit_m68k_general_startup_bridge_c(*partial, std::string(64U, 'a')));
  const auto second = expand_entry_rows(emit_m68k_general_startup_bridge_c(*partial, std::string(64U, 'a')));
  expect(first == second, "the unprovable-An-indirect emission is deterministic");
  expect(first.find("m68k_indirect_target") == std::string::npos,
         "no indirect-target array or membership guard is emitted for an unprovable An-indirect transfer");
}

void general_startup_resolves_an_an_indirect_jsr_through_its_proven_candidate_with_stack_lowering() {
  using namespace segarecomp;
  const std::vector<std::uint8_t> image{
      0x41U, 0xF9U, 0x00U, 0x00U, 0x0BU, 0x0CU,  // 0x0B00: LEA (0x00000B0C).L,A0
      0x4EU, 0x90U,                              // 0x0B06: JSR (A0)
      0x4EU, 0x70U,                              // 0x0B08: RESET (shared continuation frontier)
      0x00U, 0x00U,                              // 0x0B0A: not a target
      0x4EU, 0x75U,                              // 0x0B0C: candidate callee -> RTS
  };
  const auto result = analyze_m68k_frontend(an_indirect_fixture::make_program(image, 0x00000B00U));
  const auto *partial = std::get_if<FrontendPartialProgram>(&result);
  expect(partial != nullptr, "the An-indirect JSR fixture reaches a partial program");
  if (partial == nullptr) return;
  const auto &prefix = partial->accepted_prefix;
  expect(prefix.indirect_target_ea_sets.size() == 1U &&
             prefix.indirect_target_ea_sets.front().candidates.size() == 1U &&
             prefix.indirect_target_ea_sets.front().candidates[0].value == 0x00000B0CU &&
             prefix.indirect_target_ea_sets.front().control_ea.mode == M68kEaMode::address_indirect,
         "the An-indirect JSR retains one candidate-specific target-EA-set fact");
  expect(std::count_if(prefix.static_edges.begin(), prefix.static_edges.end(), [](const M68kStaticEdge &edge) {
           return edge.kind == M68kStaticEdgeKind::indirect_call;
         }) == 1U &&
             prefix.static_frames.size() == 1U &&
             prefix.static_frames.front().call.caller.source.address.value == 0x00000B06U &&
             prefix.static_frames.front().call.continuation.value == 0x00000B08U &&
             prefix.static_frames.front().call.callee.value == 0x00000B0CU,
         "one indirect_call edge and one candidate-specific frame with the common continuation");
  const auto first = expand_entry_rows(emit_m68k_general_startup_bridge_c(*partial, std::string(64U, 'a')));
  const auto second = expand_entry_rows(emit_m68k_general_startup_bridge_c(*partial, std::string(64U, 'a')));
  expect(first == second && !first.starts_with("/* translation rejected:"),
         "the An-indirect JSR emission is deterministic and accepted");
  expect(first.find("static const uint32_t m68k_indirect_targets_00000B06[] = {UINT32_C(0x00000B0C)};") !=
             std::string::npos,
         "the emitted JSR candidate array carries exactly the proven target");
  expect(first.find("const uint32_t m68k_indirect_ea = runtime->a[0];") != std::string::npos,
         "the JSR runtime EA is the architectural An value itself");
  expect(first.find("GENESIS_STOP_UNRESOLVED_INDIRECT_TARGET, GENESIS_DIAG_REACHED_UNRESOLVED_DIRECT_EDGE") !=
             std::string::npos,
         "a non-member runtime EA stops with the existing unresolved-indirect-target identity, before the PC/A7 change");
  expect(first.find("genesis_route_access(runtime,") != std::string::npos &&
             first.find("runtime->pc = m68k_indirect_ea;") != std::string::npos,
         "on membership the existing call-stack write and PC assignment are performed");
}

// SEG-007-T178 / ADR-0009 producer extension: a finite An code-address set
// survives a bounded JSR/BSR continuation iff the bounded callee register-write
// footprint proof shows the callee never writes that An (A7 is never
// preserved). These four fixtures cover: clean-callee survival, direct-callee
// clobber, nested-callee clobber propagation, and survival composing with a
// later conditional ADDA producer.
void general_startup_an_indirect_jmp_survives_a_clean_callee_continuation() {
  using namespace segarecomp;
  const std::vector<std::uint8_t> image{
      0x41U, 0xF9U, 0x00U, 0x00U, 0x0BU, 0x1CU,  // 0x0B00: LEA (0x00000B1C).L,A0
      0x61U, 0x00U, 0x00U, 0x08U,                // 0x0B06: BSR.W 0x0B10 (clean callee: D0/D1 only)
      0x4EU, 0xD0U,                              // 0x0B0A: JMP (A0)  -- A0 must survive the call
      0x00U, 0x00U,                              // 0x0B0C
      0x00U, 0x00U,                              // 0x0B0E
      0x70U, 0x00U,                              // 0x0B10: callee: MOVEQ #0,D0
      0x72U, 0x01U,                              // 0x0B12: MOVEQ #1,D1
      0x4EU, 0x75U,                              // 0x0B14: RTS
      0x00U, 0x00U,                              // 0x0B16
      0x00U, 0x00U,                              // 0x0B18
      0x00U, 0x00U,                              // 0x0B1A
      0x4EU, 0x70U,                              // 0x0B1C: JMP target -> shared CPU frontier (RESET)
  };
  const auto result = analyze_m68k_frontend(an_indirect_fixture::make_program(image, 0x00000B00U));
  const auto *partial = std::get_if<FrontendPartialProgram>(&result);
  expect(partial != nullptr && partial->frontiers.size() == 1U &&
             partial->frontiers.front().class_ == GenesisFrontierClass::unsupported_cpu_form,
         "the clean-callee An-indirect JMP resolves through its single proven target to the shared frontier");
  if (partial == nullptr) return;
  const auto &prefix = partial->accepted_prefix;
  expect(prefix.indirect_target_ea_sets.size() == 1U &&
             prefix.indirect_target_ea_sets.front().source_instruction.source.address.value == 0x00000B0AU &&
             prefix.indirect_target_ea_sets.front().candidates.size() == 1U &&
             prefix.indirect_target_ea_sets.front().candidates[0].value == 0x00000B1CU,
         "A0 survives the clean BSR continuation and JMP (A0) resolves to exactly the one proven target");
}

