// SEG-007-T246: proves the whole build-time chain for the existing-authority
// RTS integration, the new BCHG/BCLR/BSET plain-`(An)` carve-out, and the
// foldable-target JMP carve-out, on the independent `immutable_rom_aot_rts_
// fixture` (distinct from `experiment_aligned_aot_fixture` above, so its own
// real ordinary call/continuation genuinely populates ADR-0011's
// whole-program `runtime_return_target_set`).
void immutable_rom_aot_return_from_subroutine_and_bit_clear_are_admitted_and_dispatch() {
  using namespace segarecomp;
  using namespace immutable_rom_aot_rts_fixture;
  auto program = program_with();
  expect(apply_genesis_immutable_rom_aot(program), "the fixture's single mapping enumerates cleanly");
  const auto result = analyze_m68k_frontend(program);
  const auto *partial = std::get_if<FrontendPartialProgram>(&result);
  expect(partial != nullptr, "the fixture reaches a genuine partial program (never a complete "
                             "FrontendAnalysis, which the legacy C3 emitter would reject once "
                             "static_frames is non-empty)");
  if (partial == nullptr) return;
  expect(!partial->accepted_prefix.static_frames.empty(),
         "the ordinary direct call genuinely populates static_frames -- this is the real "
         "existing authority, not a fabricated one");
  const auto &roots = partial->accepted_prefix.immutable_rom_aot_entries;
  expect(std::any_of(roots.begin(), roots.end(),
                      [&](const auto &root) { return root.decoded.provenance.source.address.value == rts_isolated; }),
         "the isolated, ownerless RTS becomes a validated AOT root now that the whole-program "
         "return-target authority is available for this program");
  expect(std::any_of(roots.begin(), roots.end(),
                      [&](const auto &root) { return root.decoded.provenance.source.address.value == bclr_indirect; }),
         "BCLR #3,(A5) becomes a validated AOT root now that its plain (An) destination form is "
         "admitted (seventh iteration, same bounded family)");
  expect(std::any_of(roots.begin(), roots.end(),
                      [&](const auto &root) { return root.decoded.provenance.source.address.value == jmp_foldable; }),
         "JMP -10(PC) becomes a validated AOT root now that its foldable target form is admitted "
         "(eighth iteration, same bounded family)");
  expect(std::any_of(roots.begin(), roots.end(),
                      [&](const auto &root) {
                        return root.decoded.provenance.source.address.value == jsr_foldable_isolated;
                      }),
         "the isolated JSR becomes a validated AOT root now that its foldable target form is "
         "admitted (ninth iteration, same bounded family)");
  expect(std::any_of(partial->accepted_prefix.static_blocks.begin(), partial->accepted_prefix.static_blocks.end(),
                      [&](const auto &block) { return block.id.entry.value == callee; }),
         "the ordinary call's callee is a genuine, ordinarily-discovered CFG block");
  const auto emitted = expand_entry_rows(emit_m68k_general_startup_runtime_c(*partial));
  expect(!emitted.starts_with("/* translation rejected:"), "the admitted forms' AOT bodies emit");
  std::ostringstream rts_hex;
  rts_hex << std::uppercase << std::hex << std::setw(8) << std::setfill('0') << rts_isolated;
  std::ostringstream bclr_hex;
  bclr_hex << std::uppercase << std::hex << std::setw(8) << std::setfill('0') << bclr_indirect;
  std::ostringstream continuation_hex;
  continuation_hex << std::uppercase << std::hex << std::setw(8) << std::setfill('0') << call_continuation;
  expect(emitted.find("genesis_aot_" + rts_hex.str()) != std::string::npos,
         "the isolated RTS receives a genuine, dispatchable, PC-keyed AOT body");
  expect(emitted.find("genesis_aot_" + bclr_hex.str()) != std::string::npos,
         "the admitted BCLR form receives a genuine, dispatchable, PC-keyed AOT body");
  std::ostringstream jmp_hex;
  jmp_hex << std::uppercase << std::hex << std::setw(8) << std::setfill('0') << jmp_foldable;
  expect(emitted.find("genesis_aot_" + jmp_hex.str()) != std::string::npos,
         "the admitted foldable-target JMP form receives a genuine, dispatchable, PC-keyed AOT "
         "body");
  const auto jmp_body = aot_function_effective_body(emitted, jmp_hex.str());
  expect(jmp_body.find("pc = UINT32_C(0x" + rts_hex.str() + ");") != std::string::npos &&
             jmp_body.find("genesis_route_access") == std::string::npos,
         "the admitted JMP body assigns the folded constant target directly -- no memory access, "
         "no register mutation, no runtime authority of any kind");
  std::ostringstream jsr_hex;
  jsr_hex << std::uppercase << std::hex << std::setw(8) << std::setfill('0') << jsr_foldable_isolated;
  expect(emitted.find("genesis_aot_" + jsr_hex.str()) != std::string::npos,
         "the admitted isolated JSR form receives a genuine, dispatchable, PC-keyed AOT body");
  std::ostringstream jsr_continuation_hex;
  jsr_continuation_hex << std::uppercase << std::hex << std::setw(8) << std::setfill('0')
                        << jsr_foldable_isolated_continuation;
  const auto jsr_body = aot_function_effective_body(emitted, jsr_hex.str());
  expect(jsr_body.find("UINT32_C(0x" + jsr_continuation_hex.str() + ")") != std::string::npos,
         "the admitted isolated JSR body pushes exactly its OWN provenance-derived continuation "
         "(this candidate's own address+length), never an external/whole-program fact");
  expect(jsr_body.find("genesis_route_access") != std::string::npos,
         "the admitted isolated JSR body routes its stack push through the shared runtime memory "
         "gate, exactly like its ordinary CFG-rooted form");
  std::ostringstream callee_hex;
  callee_hex << std::uppercase << std::hex << std::setw(8) << std::setfill('0') << callee;
  expect(emitted.find("genesis_block_" + callee_hex.str()) != std::string::npos &&
             emitted.find("genesis_aot_" + callee_hex.str()) == std::string::npos,
         "the callee's own independently-decodable RTS candidate is also AOT-admissible now, but "
         "final emission never duplicates it: the ordinary CFG block wins and no independent AOT "
         "body is ever emitted for an address already owned by a represented block");
  // The isolated AOT RTS body's own membership check must reference the
  // real call's continuation address -- proving it validates against the
  // SAME shared whole-program authority the ordinary call's own generated
  // RTS/return machinery uses, never a fabricated or RTS-local set.
  expect(emitted.find("UINT32_C(0x" + continuation_hex.str() + ")") != std::string::npos,
         "the isolated AOT RTS body's membership check includes the real proven call continuation");
  // SEG-007-T246 correction: an admitted AOT-JSR candidate's own genuine
  // continuation must ALSO be a member of the shared whole-program
  // authority, or every otherwise-correct return through it would
  // incorrectly fail closed. This proves the union actually happened, not
  // just that the AOT JSR body itself pushes the right value.
  expect(emitted.find("UINT32_C(0x" + jsr_continuation_hex.str() + ")") != std::string::npos,
         "the admitted isolated JSR's own continuation is unioned into the same shared "
         "whole-program return-target authority every RTS validates against");
  // SEG-007-T246 correction (T208's own exact non-fabrication condition,
  // never weakened): the union above must be gated on the continuation
  // itself being a genuine, represented, dispatchable identity -- never
  // merely on the source having call semantics. Prove both directions.
  expect(std::any_of(roots.begin(), roots.end(),
                      [&](const auto &root) {
                        return root.decoded.provenance.source.address.value == jsr_continuation_body;
                      }),
         "JSR_FOLDABLE_ISOLATED's own continuation address is itself a genuine, independently "
         "admissible AOT identity (an RTS) -- the POSITIVE case: a represented continuation");
  expect(std::any_of(roots.begin(), roots.end(),
                      [&](const auto &root) {
                        return root.decoded.provenance.source.address.value ==
                               jsr_foldable_unrepresented_continuation_site;
                      }),
         "the second isolated JSR remains validly admitted/dispatchable per its own semantic "
         "contract even though its OWN continuation is deliberately unrepresented -- T244 never "
         "required CFG/continuation reachability for call admission itself");
  std::ostringstream unrepresented_continuation_hex;
  unrepresented_continuation_hex << std::uppercase << std::hex << std::setw(8) << std::setfill('0')
                                  << jsr_foldable_unrepresented_continuation;
  // Scoped to the isolated RTS's own membership-check body: the second
  // isolated JSR's body itself still legitimately pushes its own
  // continuation as a local value (that half of its semantic contract is
  // unaffected -- T244 never required a represented continuation for the
  // CALL's own admission/dispatch), so only the RTS's own return-target
  // membership list may never contain it.
  const auto rts_body = aot_function_effective_body(emitted, rts_hex.str());
  expect(!rts_body.empty() &&
             rts_body.find("UINT32_C(0x" + unrepresented_continuation_hex.str() + ")") == std::string::npos,
         "the NEGATIVE case, mirroring SEG-007-T208's own `_excluded_when_not_independently_"
         "retained` invariant: the second isolated JSR's own continuation has no generated "
         "executable identity of its own, so the isolated RTS's own return-target membership "
         "check must NOT be fabricated to include it merely because the source instruction has "
         "call semantics");
  expect(rts_body.find("UINT32_C(0x" + jsr_continuation_hex.str() + ")") != std::string::npos,
         "the isolated RTS's own return-target membership check DOES include the represented "
         "continuation (the POSITIVE case), proving the gate discriminates correctly rather than "
         "excluding everything");
}

// SEG-007-T249: proves the whole build-time chain for the general (non-
// quick) ADD/SUB/AND/OR/EOR read-modify-write memory-destination admission
// and compare's own broader memory-operand admission, on the independent
// `general_arithmetic_memory_operand_fixture`.
void general_arithmetic_memory_operand_admissions_are_admitted_and_dispatch() {
  using namespace segarecomp;
  using namespace general_arithmetic_memory_operand_fixture;
  auto program = program_with();
  expect(apply_genesis_immutable_rom_aot_range(program, base, enumeration_end),
         "the fixture's own bounded range enumerates cleanly");
  const auto result = analyze_m68k_frontend(program);
  const auto *partial = std::get_if<FrontendPartialProgram>(&result);
  expect(partial != nullptr, "the fixture reaches a genuine partial program");
  if (partial == nullptr) return;
  const auto &roots = partial->accepted_prefix.immutable_rom_aot_entries;
  expect(std::any_of(roots.begin(), roots.end(),
                      [&](const auto &root) { return root.decoded.provenance.source.address.value == add_disp16_dest; }),
         "ADD.B D1,(0,A5) becomes a validated AOT root now that its plain Dn-source/d16(An)-"
         "destination read-modify-write form is admitted (ninth iteration, same bounded family)");
  expect(std::any_of(roots.begin(), roots.end(),
                      [&](const auto &root) { return root.decoded.provenance.source.address.value == cmp_disp16_source; }),
         "CMP.B (0,A6),D2 becomes a validated AOT root now that its non-mutating d16(An) source "
         "form is admitted (compare's own broader admission)");
  expect(std::any_of(roots.begin(), roots.end(),
                      [&](const auto &root) { return root.decoded.provenance.source.address.value == cmp_index8_source; }),
         "CMP.B (4,A6,D0.W),D3 becomes a validated AOT root now that its brief-format indexed "
         "source form is admitted (compare's own broader admission, sibling addressing-mode "
         "class)");
  expect(std::any_of(roots.begin(), roots.end(),
                      [&](const auto &root) { return root.decoded.provenance.source.address.value == clr_disp16_dest; }),
         "CLR.W (0,A4) becomes a validated AOT root now that its own dedicated d16(An) "
         "destination carve-out is admitted (this task's own corrected same-seam continuation)");
  expect(std::any_of(roots.begin(), roots.end(),
                      [&](const auto &root) { return root.decoded.provenance.source.address.value == move_disp16_to_disp16; }),
         "MOVE.B (0,A0),(0,A5) becomes a validated AOT root now that its d16(An)-source/"
         "d16(An)-destination form is admitted (this task's own second corrected same-seam "
         "continuation)");
  const auto emitted = expand_entry_rows(emit_m68k_general_startup_runtime_c(*partial));
  expect(!emitted.starts_with("/* translation rejected:"), "the admitted forms' AOT bodies emit");
  std::ostringstream add_hex, cmp_disp16_hex, cmp_index8_hex, clr_hex, move_hex;
  add_hex << std::uppercase << std::hex << std::setw(8) << std::setfill('0') << add_disp16_dest;
  cmp_disp16_hex << std::uppercase << std::hex << std::setw(8) << std::setfill('0') << cmp_disp16_source;
  cmp_index8_hex << std::uppercase << std::hex << std::setw(8) << std::setfill('0') << cmp_index8_source;
  clr_hex << std::uppercase << std::hex << std::setw(8) << std::setfill('0') << clr_disp16_dest;
  move_hex << std::uppercase << std::hex << std::setw(8) << std::setfill('0') << move_disp16_to_disp16;
  expect(emitted.find("genesis_aot_" + add_hex.str()) != std::string::npos,
         "ADD_DISP16_DEST receives a genuine, dispatchable, PC-keyed AOT body");
  expect(emitted.find("genesis_aot_" + cmp_disp16_hex.str()) != std::string::npos,
         "CMP_DISP16_SOURCE receives a genuine, dispatchable, PC-keyed AOT body");
  expect(emitted.find("genesis_aot_" + cmp_index8_hex.str()) != std::string::npos,
         "CMP_INDEX8_SOURCE receives a genuine, dispatchable, PC-keyed AOT body");
  expect(emitted.find("genesis_aot_" + clr_hex.str()) != std::string::npos,
         "CLR_DISP16_DEST receives a genuine, dispatchable, PC-keyed AOT body");
  expect(emitted.find("genesis_aot_" + move_hex.str()) != std::string::npos,
         "MOVE_DISP16_TO_DISP16 receives a genuine, dispatchable, PC-keyed AOT body");
  expect(emitted.find("genesis_route_access(runtime,") != std::string::npos,
         "the admitted forms' reads and writes route through the shared runtime memory gate");
}

