    stop->provenance.mapping_claims[0].target_end = UINT32_C(0x00000C0C);
    stop->provenance.mapping_claims[0].image_begin = UINT64_C(0);
    stop->provenance.mapping_claims[0].image_end = UINT64_C(12);
