void general_startup_retains_the_exact_same_ea_read_request_at_a_device_frontier() {
  const std::vector<std::uint8_t> image{
      0x60U, 0x02U, 0x00U, 0x00U,                    // 0xE00: BRA.s 0xE04
      0x4AU, 0xB9U, 0x00U, 0xA1U, 0x00U, 0x00U,      // 0xE04: TST.L rejected controller EA
  };
  segarecomp::FrontendProgram program{};
  program.profile = segarecomp::M68kFrontendProfile::general_startup;
  program.image = {"synthetic/SEG-007-T029/c1-same-ea-device-read", image, image.size()};
  program.mapping_claims = {{"rom", {{}, 0xE00U}, {{}, 0xE0AU}, {0U}, {10U}}};
  program.startup_ingress = segarecomp::M68kStartupIngress{{{}, 0xE00U}, 0x00FF0100U};

  const auto result = segarecomp::analyze_m68k_frontend(program);
  const auto *partial = std::get_if<segarecomp::FrontendPartialProgram>(&result);
  expect(partial != nullptr &&
             partial->frontiers.front().class_ == segarecomp::GenesisFrontierClass::unsupported_device_access &&
             partial->frontiers.front().access &&
             partial->frontiers.front().access->address.value == 0x00A10000U &&
             partial->frontiers.front().access->width == segarecomp::M68kMemoryAccessWidth::long_word &&
              partial->frontiers.front().access->direction == segarecomp::M68kMemoryAccessDirection::read &&
              partial->frontiers.front().access->source_provenance &&
              partial->frontiers.front().access->source_provenance->source.address.value == 0xE04U &&
              partial->frontiers.front().diagnostic.provenance &&
              partial->frontiers.front().access->source_provenance->source.cpu_variant == partial->frontiers.front().diagnostic.provenance->source.cpu_variant &&
              partial->frontiers.front().access->source_provenance->source.address.space == partial->frontiers.front().diagnostic.provenance->source.address.space &&
              partial->frontiers.front().access->source_provenance->source.address.value == partial->frontiers.front().diagnostic.provenance->source.address.value &&
              partial->frontiers.front().access->source_provenance->source.image_offset.value == partial->frontiers.front().diagnostic.provenance->source.image_offset.value &&
              partial->frontiers.front().access->source_provenance->bytes == partial->frontiers.front().diagnostic.provenance->bytes &&
              partial->frontiers.front().access->source_provenance->length.value == partial->frontiers.front().diagnostic.provenance->length.value &&
              // SEG-007-T032: an eligible, promoted device frontier is
              // unaffected by the new rejected-only projection field.
              !partial->frontiers.front().diagnostic.controller_io_access_shape &&
              // SEG-007-T040: the rejected TST itself is the frontier
              // instruction, excluded from the accepted prefix -- it is
              // never retained as a static memory fact (that would require
              // it to have first been *accepted* into prefix.decoded, which
              // never happens for an unsupported/non-policy-matching
              // controller-I/O shape). This is unchanged by SEG-007-T040's
              // new retain_fact controller_io success branch, which is only
              // ever reached for an already-accepted instruction.
              partial->accepted_prefix.static_memory_facts.empty(),
          "a device failure retains the resolver's exact source-read request in a partial program, and an "
          "unsupported/non-policy-matching controller-I/O shape still leaves no static memory fact behind");
}

// SEG-007-T040 (C2): a TST.L absolute-long read whose address the already-
// implemented CTRL1/CTRL2 selector (SEG-007-T020/T021) admits is routed to
// success during discovery's own walk (m68k_resolve_static_general_operand
// returns no diagnostic), so it is accepted into the prefix rather than ever
// becoming a frontier itself. The BRA that follows it branches directly to
// the address of a separate, later RESET -- an unsupported CPU form -- so that
// address becomes the actual frontier (matching
// general_startup_retains_the_exact_same_ea_read_request_at_a_device_frontier's
// own "edge target equals frontier address" retention rule), keeping the
// [TST, BRA] block a retained *completed* block of the accepted prefix
// instead of being pruned. This proves retain_fact's new controller_io
// branch (the C1 contract's own gap) actually populates
// static_memory_facts for a routed success, closing the gap C4 lowering
// depends on.
void general_startup_retains_a_controller_io_static_memory_fact_for_a_routed_read() {
  const std::vector<std::uint8_t> image{
      0x4AU, 0xB9U, 0x00U, 0xA1U, 0x00U, 0x08U,  // 0xB00: TST.L $00A10008 (CTRL1/CTRL2 selector: routed success)
      0x60U, 0x02U,                              // 0xB06: BRA.s 0xB0A
      0x00U, 0x00U,                              // 0xB08: padding, skipped
      0x4EU, 0x70U,                              // 0xB0A: RESET -- unsupported CPU form, the actual frontier
  };
  segarecomp::FrontendProgram program{};
  program.profile = segarecomp::M68kFrontendProfile::general_startup;
  program.image = {"synthetic/SEG-007-T040/c2-controller-io-routed-read", image, image.size()};
  program.mapping_claims = {{"synthetic-c4-controller-io", {{}, 0xB00U}, {{}, 0xB0CU}, {0U}, {12U}}};
  program.startup_ingress = segarecomp::M68kStartupIngress{{{}, 0xB00U}, 0x00FF0100U};

  const auto result = segarecomp::analyze_m68k_frontend(program);
  const auto *partial = std::get_if<segarecomp::FrontendPartialProgram>(&result);
  expect(partial != nullptr &&
             partial->frontiers.front().class_ == segarecomp::GenesisFrontierClass::unsupported_cpu_form &&
             partial->accepted_prefix.static_blocks.size() == 1U &&
             partial->accepted_prefix.decoded.size() == 2U,
         "a CTRL1/CTRL2-admitted TST.L read does not itself become the frontier; the later RESET does, and the "
         "[TST, BRA] block remains a retained completed block of the accepted prefix");
  if (partial == nullptr) return;

  const auto &facts = partial->accepted_prefix.static_memory_facts;
  expect(facts.size() == 1U, "exactly one static memory fact is retained for the routed TST.L read");
  if (facts.size() != 1U) return;
  const auto &fact = facts.front();
  expect(fact.role == segarecomp::M68kStaticMemoryFactRole::source_read &&
             fact.address.space == segarecomp::TargetAddressSpace::m68k_program &&
             fact.address.value == UINT32_C(0x00A10008) &&
             fact.width == segarecomp::M68kMemoryAccessWidth::long_word &&
             fact.direction == segarecomp::M68kMemoryAccessDirection::read &&
             fact.region == segarecomp::M68kAbsoluteOperandRegion::controller_io &&
             fact.operation.source.address.value == 0xB00U,
         "the retained fact is a controller_io-region source_read of the exact routed CTRL1/CTRL2 address, "
         "width, and direction, attributed to the TST.L instruction's own provenance");
}

// SEG-007-T090: the VDP-window analogue of
// general_startup_retains_a_controller_io_static_memory_fact_for_a_routed_read
// -- a TST.W ($00C00004).L WORD read of the VDP control/status port is
// retained as a `vdp`-region source_read fact, and every non-matching
// neighbour shape at the same seam stays an unmapped_data_access frontier.
void general_startup_retains_a_vdp_static_memory_fact_for_a_routed_word_read() {
  using W = segarecomp::M68kMemoryAccessWidth;
  using D = segarecomp::M68kMemoryAccessDirection;
  const auto request = [](std::uint32_t address, W width, D direction) {
    return segarecomp::M68kMemoryAccessRequest{
        {segarecomp::TargetAddressSpace::m68k_program, address}, width, direction, std::nullopt};
  };

  // The one routed READ shape: WORD READ anywhere fully inside [0x00C00000, 0x00C00020).
  for (const auto address : {UINT32_C(0x00C00000), UINT32_C(0x00C00004), UINT32_C(0x00C0001E)}) {
    expect(std::holds_alternative<segarecomp::M68kVdpRoutedRead>(
               segarecomp::m68k_route_genesis_device_access(request(address, W::word, D::read))),
           "a WORD read fully inside the VDP window routes to M68kVdpRoutedRead");
  }

  // SEG-007-T113: the routed WRITE shapes -- WORD and LONG stores anywhere
  // fully inside the window route to M68kVdpRoutedWrite.
  for (const auto address : {UINT32_C(0x00C00000), UINT32_C(0x00C00004), UINT32_C(0x00C0001C)}) {
    expect(std::holds_alternative<segarecomp::M68kVdpRoutedWrite>(
               segarecomp::m68k_route_genesis_device_access(request(address, W::word, D::write))),
           "a WORD store fully inside the VDP window routes to M68kVdpRoutedWrite");
  }
  for (const auto address : {UINT32_C(0x00C00000), UINT32_C(0x00C00004), UINT32_C(0x00C0001C)}) {
    expect(std::holds_alternative<segarecomp::M68kVdpRoutedWrite>(
               segarecomp::m68k_route_genesis_device_access(request(address, W::long_word, D::write))),
           "a LONG store fully inside the VDP window routes to M68kVdpRoutedWrite");
  }

  // Every fail-closed neighbour stays exactly unmapped_data_access.
  const auto is_unmapped = [](const segarecomp::M68kGenesisDeviceRoutingResult &routed) {
    const auto *diagnostic = std::get_if<segarecomp::DirectFlowDiagnostic>(&routed);
    return diagnostic != nullptr && *diagnostic == segarecomp::DirectFlowDiagnostic::unmapped_data_access;
  };
  expect(is_unmapped(segarecomp::m68k_route_genesis_device_access(request(0x00C00004U, W::byte, D::read))) &&
             is_unmapped(segarecomp::m68k_route_genesis_device_access(request(0x00C00004U, W::long_word, D::read))) &&
             is_unmapped(segarecomp::m68k_route_genesis_device_access(request(0x00C00004U, W::byte, D::write))) &&
             is_unmapped(segarecomp::m68k_route_genesis_device_access(request(0x00C00020U, W::word, D::read))) &&
             is_unmapped(segarecomp::m68k_route_genesis_device_access(request(0x00C00020U, W::word, D::write))) &&
             is_unmapped(segarecomp::m68k_route_genesis_device_access(request(0x00C0001FU, W::word, D::read))) &&
             is_unmapped(segarecomp::m68k_route_genesis_device_access(request(0x00C0001FU, W::word, D::write))) &&
             is_unmapped(segarecomp::m68k_route_genesis_device_access(request(0x00B00000U, W::word, D::read))) &&
             is_unmapped(segarecomp::m68k_route_genesis_device_access(request(0x00B00000U, W::word, D::write))),
         "byte width (either direction), a read of long width, the just-outside address, a "
         "top-edge-straddling word, and a non-VDP unmapped hardware address all remain unmapped_data_access");

  // The resolver reduces exactly the routed shape to region == vdp with no bytes/value.
  const std::array<std::uint8_t, 0> empty{};
  const std::span<const std::uint8_t> image{empty};
  const auto resolved = segarecomp::m68k_resolve_absolute_test_operand(
      image, 0x00C00004U, W::word, D::read, std::nullopt);
  const auto *operand = std::get_if<segarecomp::M68kAbsoluteTestOperand>(&resolved);
  expect(operand != nullptr && operand->region == segarecomp::M68kAbsoluteOperandRegion::vdp &&
             operand->value == 0U && operand->bytes == std::array<std::uint8_t, 4>{},
         "m68k_resolve_absolute_test_operand yields a value-free vdp-region operand for the WORD-read shape");
  // SEG-007-T113: the WORD and LONG store shapes reduce to the same
  // value-free vdp-region operand -- the runtime device gate owns the write.
  for (const auto width : {W::word, W::long_word}) {
    const auto resolved_write = segarecomp::m68k_resolve_absolute_test_operand(
        image, 0x00C00004U, width, D::write, std::nullopt);
    const auto *write_operand = std::get_if<segarecomp::M68kAbsoluteTestOperand>(&resolved_write);
    expect(write_operand != nullptr && write_operand->region == segarecomp::M68kAbsoluteOperandRegion::vdp &&
               write_operand->value == 0U && write_operand->bytes == std::array<std::uint8_t, 4>{},
           "m68k_resolve_absolute_test_operand yields a value-free vdp-region operand for the WORD/LONG store shape");
  }
  expect(std::get<segarecomp::DirectFlowDiagnostic>(segarecomp::m68k_resolve_absolute_test_operand(
             image, 0x00C00004U, W::byte, D::read, std::nullopt)) ==
                 segarecomp::DirectFlowDiagnostic::unmapped_data_access &&
             std::get<segarecomp::DirectFlowDiagnostic>(segarecomp::m68k_resolve_absolute_test_operand(
                 image, 0x00C00004U, W::long_word, D::read, std::nullopt)) ==
                 segarecomp::DirectFlowDiagnostic::unmapped_data_access &&
             std::get<segarecomp::DirectFlowDiagnostic>(segarecomp::m68k_resolve_absolute_test_operand(
                 image, 0x00C00004U, W::byte, D::write, std::nullopt)) ==
                 segarecomp::DirectFlowDiagnostic::unmapped_data_access &&
             std::get<segarecomp::DirectFlowDiagnostic>(segarecomp::m68k_resolve_absolute_test_operand(
                 image, 0x00C00005U, W::word, D::read, std::nullopt)) ==
                 segarecomp::DirectFlowDiagnostic::odd_effective_address &&
             std::get<segarecomp::DirectFlowDiagnostic>(segarecomp::m68k_resolve_absolute_test_operand(
                 image, 0x00C00005U, W::word, D::write, std::nullopt)) ==
                 segarecomp::DirectFlowDiagnostic::odd_effective_address,
         "byte VDP-window accesses and a long read stay unmapped_data_access; an odd-address word "
         "read or store stays odd_effective_address");

  // Discovery retains the fact end to end for a TST.W ($00C00004).L block.
  const std::vector<std::uint8_t> block{
      0x4AU, 0x79U, 0x00U, 0xC0U, 0x00U, 0x04U,  // 0xB00: TST.W $00C00004 (VDP control/status port)
      0x60U, 0x02U,                              // 0xB06: BRA.s 0xB0A
      0x00U, 0x00U,                              // 0xB08: padding, skipped
      0x4EU, 0x70U,                              // 0xB0A: RESET -- the actual CPU frontier
  };
  segarecomp::FrontendProgram program{};
  program.profile = segarecomp::M68kFrontendProfile::general_startup;
  program.image = {"synthetic/SEG-007-T090/c2-vdp-routed-word-read", block, block.size()};
  program.mapping_claims = {{"synthetic-c4-vdp", {{}, 0xB00U}, {{}, 0xB0CU}, {0U}, {12U}}};
  program.startup_ingress = segarecomp::M68kStartupIngress{{{}, 0xB00U}, 0x00FF0100U};
  const auto result = segarecomp::analyze_m68k_frontend(program);
  const auto *partial = std::get_if<segarecomp::FrontendPartialProgram>(&result);
  expect(partial != nullptr && partial->accepted_prefix.static_memory_facts.size() == 1U,
         "a VDP-window-admitted TST.W read retains exactly one static memory fact and does not itself become the frontier");
  if (partial == nullptr || partial->accepted_prefix.static_memory_facts.size() != 1U) return;
  const auto &fact = partial->accepted_prefix.static_memory_facts.front();
  expect(fact.role == segarecomp::M68kStaticMemoryFactRole::source_read &&
             fact.address.value == UINT32_C(0x00C00004) &&
             fact.width == segarecomp::M68kMemoryAccessWidth::word &&
             fact.direction == segarecomp::M68kMemoryAccessDirection::read &&
             fact.region == segarecomp::M68kAbsoluteOperandRegion::vdp,
         "the retained fact is a vdp-region WORD source_read of the exact VDP control-port address");
}

// SEG-007-T113: discovery retains a `vdp`-region destination_write fact for a
// direct absolute-operand LONG store into the VDP control-port window and
// does not make that store the frontier -- the write-direction mirror of the
// read fixture above.
void general_startup_retains_a_vdp_static_memory_fact_for_a_routed_long_store() {
  // 23 FC <imm32> 00 C0 00 04 : MOVE.L #imm,($00C00004).L, then RESET frontier.
  const std::vector<std::uint8_t> block{
      0x23U, 0xFCU, 0x9FU, 0x00U, 0x00U, 0x00U, 0x00U, 0xC0U, 0x00U, 0x04U,
      0x4EU, 0x70U,  // 0xB0A: RESET
  };
  segarecomp::FrontendProgram program{};
  program.profile = segarecomp::M68kFrontendProfile::general_startup;
  program.image = {"synthetic/SEG-007-T113/vdp-routed-long-store", block, block.size()};
  program.mapping_claims = {{"synthetic-vdp-store", {{}, 0xB00U}, {{}, 0xB0CU}, {0U}, {12U}}};
  program.startup_ingress = segarecomp::M68kStartupIngress{{{}, 0xB00U}, 0x00FF0100U};
  const auto result = segarecomp::analyze_m68k_frontend(program);
  const auto *partial = std::get_if<segarecomp::FrontendPartialProgram>(&result);
  expect(partial != nullptr && partial->accepted_prefix.static_memory_facts.size() == 1U &&
             partial->accepted_prefix.static_blocks.size() == 1U,
         "a VDP-window-admitted MOVE.L store retains exactly one static memory fact and one block");
  if (partial == nullptr || partial->accepted_prefix.static_memory_facts.size() != 1U) return;
  const auto &fact = partial->accepted_prefix.static_memory_facts.front();
  expect(fact.role == segarecomp::M68kStaticMemoryFactRole::destination_write &&
             fact.address.value == UINT32_C(0x00C00004) &&
             fact.width == segarecomp::M68kMemoryAccessWidth::long_word &&
             fact.direction == segarecomp::M68kMemoryAccessDirection::write &&
             fact.region == segarecomp::M68kAbsoluteOperandRegion::vdp,
         "the retained fact is a vdp-region LONG destination_write of the exact VDP control-port address");
}

// SEG-007-T115: the Z80-bus-arbitration / Z80-program-RAM / PSG analogue of
// the VDP routing fixtures above. Every (address, width, direction) shape the
// runtime device owners already support routes to the generalized
// M68kDeviceRoutedAccess marker; every fail-closed neighbour stays exactly
// unmapped_data_access before any state; and discovery retains a value-free
// `routed_device` fact end to end for a MOVE store into the BUSREQ register.
void general_startup_routes_z80_and_psg_absolute_operands() {
  using W = segarecomp::M68kMemoryAccessWidth;
  using D = segarecomp::M68kMemoryAccessDirection;
  using segarecomp::M68kDeviceRoutedAccess;
  const auto request = [](std::uint32_t address, W width, D direction) {
    return segarecomp::M68kMemoryAccessRequest{
        {segarecomp::TargetAddressSpace::m68k_program, address}, width, direction, std::nullopt};
  };
  const auto routes = [&](std::uint32_t address, W width, D direction) {
    const auto routed = segarecomp::m68k_route_genesis_device_access(request(address, width, direction));
    const auto *marker = std::get_if<M68kDeviceRoutedAccess>(&routed);
    return marker != nullptr && marker->direction == direction;
  };
  const auto is_unmapped = [&](std::uint32_t address, W width, D direction) {
    const auto routed = segarecomp::m68k_route_genesis_device_access(request(address, width, direction));
    const auto *diagnostic = std::get_if<segarecomp::DirectFlowDiagnostic>(&routed);
    return diagnostic != nullptr && *diagnostic == segarecomp::DirectFlowDiagnostic::unmapped_data_access;
  };

  // BUSREQ ($A11100): WORD/BYTE, both directions. RESET ($A11200): WORD/BYTE
  // write only.
  for (const auto width : {W::word, W::byte})
    for (const auto direction : {D::read, D::write})
      expect(routes(0x00A11100U, width, direction),
             "a WORD/BYTE read or write of the Z80 BUSREQ register routes to M68kDeviceRoutedAccess");
  for (const auto width : {W::word, W::byte})
    expect(routes(0x00A11200U, width, D::write),
           "a WORD/BYTE write of the Z80 RESET register routes to M68kDeviceRoutedAccess");

  // Flat Z80 program-RAM window ($A00000 .. $A01FFF): BYTE, both directions.
  for (const auto address : {UINT32_C(0x00A00000), UINT32_C(0x00A00ABC), UINT32_C(0x00A01FFF)})
    for (const auto direction : {D::read, D::write})
      expect(routes(address, W::byte, direction),
             "a BYTE read or write anywhere inside the flat Z80 program-RAM window routes");

  // Co-located PSG audio port ($C00011): BYTE write only.
  expect(routes(0x00C00011U, W::byte, D::write),
         "a BYTE write of the co-located PSG audio port routes to M68kDeviceRoutedAccess");

  // Fail-closed neighbours -- every one stays exactly unmapped_data_access.
  expect(is_unmapped(0x00A11100U, W::long_word, D::write) &&
             is_unmapped(0x00A11100U, W::long_word, D::read) &&
             is_unmapped(0x00A11200U, W::word, D::read) &&    // RESET is write-only
             is_unmapped(0x00A11200U, W::byte, D::read) &&
             is_unmapped(0x00A11080U, W::word, D::write) &&   // in-region, not a register
             is_unmapped(0x00A112FEU, W::word, D::write) &&   // in-region, not a register
             is_unmapped(0x00A11300U, W::word, D::write) &&   // just past the region end
             is_unmapped(0x00A00000U, W::word, D::write) &&   // Z80 RAM is BYTE-only
             is_unmapped(0x00A00000U, W::long_word, D::read) &&
             is_unmapped(0x00A02000U, W::byte, D::write) &&   // the excluded Z80-RAM mirror base
             is_unmapped(0x009FFFFFU, W::byte, D::read) &&     // one byte below the window
             is_unmapped(0x00C00011U, W::byte, D::read) &&    // PSG port is write-only
             is_unmapped(0x00C00013U, W::byte, D::write) &&   // the excluded PSG mirror
             is_unmapped(0x00C00010U, W::byte, D::write),      // the even PSG neighbour
         "LONG Z80-bus access, a RESET read, non-register in-region addresses, the region top edge, "
         "WORD/LONG Z80-RAM access, the Z80-RAM mirror, a PSG read, and the PSG mirror/neighbour all "
         "stay unmapped_data_access");

  // The resolver reduces exactly the routed shapes to a value-free
  // routed_device operand.
  const std::array<std::uint8_t, 0> empty{};
  const std::span<const std::uint8_t> image{empty};
  for (const auto &[address, width, direction] :
       {std::tuple{UINT32_C(0x00A11100), W::word, D::write}, std::tuple{UINT32_C(0x00A11100), W::word, D::read},
        std::tuple{UINT32_C(0x00A11200), W::byte, D::write}, std::tuple{UINT32_C(0x00A00000), W::byte, D::write},
        std::tuple{UINT32_C(0x00A00ABC), W::byte, D::read}, std::tuple{UINT32_C(0x00C00011), W::byte, D::write}}) {
    const auto resolved = segarecomp::m68k_resolve_absolute_test_operand(image, address, width, direction, std::nullopt);
    const auto *operand = std::get_if<segarecomp::M68kAbsoluteTestOperand>(&resolved);
    expect(operand != nullptr && operand->region == segarecomp::M68kAbsoluteOperandRegion::routed_device &&
               operand->value == 0U && operand->bytes == std::array<std::uint8_t, 4>{},
           "m68k_resolve_absolute_test_operand yields a value-free routed_device operand for a supported shape");
  }
  // ... and a rejected shape stays a fail-closed diagnostic through the resolver.
  expect(std::get<segarecomp::DirectFlowDiagnostic>(segarecomp::m68k_resolve_absolute_test_operand(
             image, 0x00A11100U, W::long_word, D::write, std::nullopt)) ==
                 segarecomp::DirectFlowDiagnostic::unmapped_data_access &&
             std::get<segarecomp::DirectFlowDiagnostic>(segarecomp::m68k_resolve_absolute_test_operand(
                 image, 0x00A11200U, W::word, D::read, std::nullopt)) ==
                 segarecomp::DirectFlowDiagnostic::unmapped_data_access &&
             std::get<segarecomp::DirectFlowDiagnostic>(segarecomp::m68k_resolve_absolute_test_operand(
                 image, 0x00C00011U, W::word, D::write, std::nullopt)) ==
                 segarecomp::DirectFlowDiagnostic::odd_effective_address,
         "a LONG Z80-bus store, a RESET read, and an odd-address PSG word write stay fail-closed via the resolver");

  // Discovery retains a value-free routed_device destination_write fact for a
  // MOVE.W #$0100,($A11100).L store, and does not make that store the frontier.
  {
    const std::vector<std::uint8_t> block{
        0x33U, 0xFCU, 0x01U, 0x00U, 0x00U, 0xA1U, 0x11U, 0x00U,  // 0xB00: MOVE.W #$0100,($00A11100).L
        0x4EU, 0x70U,                                            // 0xB08: RESET -- the CPU frontier
    };
    segarecomp::FrontendProgram program{};
    program.profile = segarecomp::M68kFrontendProfile::general_startup;
    program.image = {"synthetic/SEG-007-T115/z80-bus-routed-store", block, block.size()};
    program.mapping_claims = {{"synthetic-z80-bus-store", {{}, 0xB00U}, {{}, 0xB0AU}, {0U}, {10U}}};
    program.startup_ingress = segarecomp::M68kStartupIngress{{{}, 0xB00U}, 0x00FF0100U};
    const auto result = segarecomp::analyze_m68k_frontend(program);
    const auto *partial = std::get_if<segarecomp::FrontendPartialProgram>(&result);
    expect(partial != nullptr && partial->accepted_prefix.static_memory_facts.size() == 1U &&
               partial->accepted_prefix.static_blocks.size() == 1U,
           "a Z80-bus-window-admitted MOVE.W store retains exactly one static memory fact and one block");
    if (partial != nullptr && partial->accepted_prefix.static_memory_facts.size() == 1U) {
      const auto &fact = partial->accepted_prefix.static_memory_facts.front();
      expect(fact.role == segarecomp::M68kStaticMemoryFactRole::destination_write &&
                 fact.address.value == UINT32_C(0x00A11100) &&
                 fact.width == segarecomp::M68kMemoryAccessWidth::word &&
                 fact.direction == segarecomp::M68kMemoryAccessDirection::write &&
                 fact.region == segarecomp::M68kAbsoluteOperandRegion::routed_device,
             "the retained fact is a routed_device WORD destination_write of the exact BUSREQ register address");
      expect(!expand_entry_rows(segarecomp::emit_m68k_general_startup_runtime_c(*partial)).starts_with("/* translation rejected"),
             "the retained routed_device store lowers to generated C without rejection");
    }
  }
}

// SEG-007-T171: the YM2612 FM-synthesis register-window analogue of the
// Z80/PSG routing fixtures above. Only the one runtime-confirmed shape (a
// BYTE READ of the PART-I address/status port, $A04000) routes to the
// generalized M68kDeviceRoutedAccess marker; every other in-window
// port/direction/width, and every neighbour outside the window, stays
// exactly unmapped_data_access; discovery retains a value-free routed_device
// fact end to end for a TST.B of that one port.
void general_startup_routes_ym2612_status_port_read() {
  using W = segarecomp::M68kMemoryAccessWidth;
  using D = segarecomp::M68kMemoryAccessDirection;
  using segarecomp::M68kDeviceRoutedAccess;
  const auto request = [](std::uint32_t address, W width, D direction) {
    return segarecomp::M68kMemoryAccessRequest{
        {segarecomp::TargetAddressSpace::m68k_program, address}, width, direction, std::nullopt};
  };
  const auto routes = [&](std::uint32_t address, W width, D direction) {
    const auto routed = segarecomp::m68k_route_genesis_device_access(request(address, width, direction));
    const auto *marker = std::get_if<M68kDeviceRoutedAccess>(&routed);
    return marker != nullptr && marker->direction == direction;
  };
  const auto is_unmapped = [&](std::uint32_t address, W width, D direction) {
    const auto routed = segarecomp::m68k_route_genesis_device_access(request(address, width, direction));
    const auto *diagnostic = std::get_if<segarecomp::DirectFlowDiagnostic>(&routed);
    return diagnostic != nullptr && *diagnostic == segarecomp::DirectFlowDiagnostic::unmapped_data_access;
  };

  // The PART-I address/status port ($A04000): BYTE read (status) and BYTE
  // write (register-select latch, second frontier pass) both route. The
  // PART-I data port ($A04001): BYTE write (register-data write, third
  // frontier pass) routes. The PART-II address port ($A04002): BYTE write
  // (register-select latch, fourth frontier pass) routes. The PART-II data
  // port ($A04003): BYTE write (register-data write, fifth frontier pass)
  // routes.
  expect(routes(0x00A04000U, W::byte, D::read),
         "a BYTE read of the YM2612 PART-I status port routes to M68kDeviceRoutedAccess");
  expect(routes(0x00A04000U, W::byte, D::write),
         "a BYTE write of the YM2612 PART-I address port routes to M68kDeviceRoutedAccess");
  expect(routes(0x00A04001U, W::byte, D::write),
         "a BYTE write of the YM2612 PART-I data port routes to M68kDeviceRoutedAccess");
  expect(routes(0x00A04002U, W::byte, D::write),
         "a BYTE write of the YM2612 PART-II address port routes to M68kDeviceRoutedAccess");
  expect(routes(0x00A04003U, W::byte, D::write),
         "a BYTE write of the YM2612 PART-II data port routes to M68kDeviceRoutedAccess");

  // Fail-closed neighbours -- every one stays exactly unmapped_data_access.
  expect(is_unmapped(0x00A04000U, W::word, D::read) &&    // wrong width
             is_unmapped(0x00A04000U, W::long_word, D::read) &&
             is_unmapped(0x00A04000U, W::word, D::write) &&
             is_unmapped(0x00A04001U, W::byte, D::read) &&    // data port is write-only under this policy
             is_unmapped(0x00A04001U, W::word, D::write) &&   // wrong width
             is_unmapped(0x00A04002U, W::byte, D::read) &&    // PART-II status port: not runtime-confirmed
             is_unmapped(0x00A04002U, W::word, D::write) &&   // wrong width
             is_unmapped(0x00A04003U, W::byte, D::read) &&    // data port is write-only under this policy
             is_unmapped(0x00A04003U, W::word, D::write) &&   // wrong width
             is_unmapped(0x00A03FFFU, W::byte, D::read) &&    // one byte below the window
             is_unmapped(0x00A04004U, W::byte, D::read),      // one byte past the window
         "wrong width, unreached in-window port, and out-of-window neighbour all stay "
         "unmapped_data_access");

  // The resolver reduces the routed shape to a value-free routed_device
  // operand, and a rejected neighbour stays a fail-closed diagnostic.
  const std::array<std::uint8_t, 0> empty{};
  const std::span<const std::uint8_t> image{empty};
  {
    const auto resolved =
        segarecomp::m68k_resolve_absolute_test_operand(image, 0x00A04000U, W::byte, D::read, std::nullopt);
    const auto *operand = std::get_if<segarecomp::M68kAbsoluteTestOperand>(&resolved);
    expect(operand != nullptr && operand->region == segarecomp::M68kAbsoluteOperandRegion::routed_device &&
               operand->value == 0U && operand->bytes == std::array<std::uint8_t, 4>{},
           "m68k_resolve_absolute_test_operand yields a value-free routed_device operand for the YM2612 status read");
  }
  expect(std::get<segarecomp::DirectFlowDiagnostic>(segarecomp::m68k_resolve_absolute_test_operand(
             image, 0x00A04002U, W::byte, D::read, std::nullopt)) ==
             segarecomp::DirectFlowDiagnostic::unmapped_data_access,
         "an unconfirmed YM2612 port (PART-II status) stays fail-closed via the resolver");

  // Discovery retains a value-free routed_device destination_read fact for a
  // TST.B ($A04000).L, and does not make that read the frontier.
  {
    const std::vector<std::uint8_t> block{
        0x4AU, 0x39U, 0x00U, 0xA0U, 0x40U, 0x00U,  // 0xB00: TST.B ($00A04000).L
        0x4EU, 0x70U,                              // 0xB06: RESET -- the CPU frontier
    };
    segarecomp::FrontendProgram program{};
    program.profile = segarecomp::M68kFrontendProfile::general_startup;
    program.image = {"synthetic/SEG-007-T171/ym2612-routed-read", block, block.size()};
    program.mapping_claims = {{"synthetic-ym2612-status-read", {{}, 0xB00U}, {{}, 0xB08U}, {0U}, {8U}}};
    program.startup_ingress = segarecomp::M68kStartupIngress{{{}, 0xB00U}, 0x00FF0100U};
    const auto result = segarecomp::analyze_m68k_frontend(program);
    const auto *partial = std::get_if<segarecomp::FrontendPartialProgram>(&result);
    expect(partial != nullptr && partial->accepted_prefix.static_memory_facts.size() == 1U &&
               partial->accepted_prefix.static_blocks.size() == 1U,
           "a YM2612-window-admitted TST.B read retains exactly one static memory fact and one block");
    if (partial != nullptr && partial->accepted_prefix.static_memory_facts.size() == 1U) {
      const auto &fact = partial->accepted_prefix.static_memory_facts.front();
      expect(fact.role == segarecomp::M68kStaticMemoryFactRole::source_read &&
                 fact.address.value == UINT32_C(0x00A04000) &&
                 fact.width == segarecomp::M68kMemoryAccessWidth::byte &&
                 fact.direction == segarecomp::M68kMemoryAccessDirection::read &&
                 fact.region == segarecomp::M68kAbsoluteOperandRegion::routed_device,
             "the retained fact is a routed_device BYTE source_read of the exact YM2612 status port address");
      expect(!expand_entry_rows(segarecomp::emit_m68k_general_startup_runtime_c(*partial)).starts_with("/* translation rejected"),
             "the retained routed_device read lowers to generated C without rejection");
    }
  }

  // Discovery retains a value-free routed_device destination_write fact for a
  // MOVE.B D0,($A04000).L (the register-select latch write shape actually
  // reached by the authorized production route's own second frontier pass),
  // and does not make that write the frontier.
  {
    const std::vector<std::uint8_t> block{
        0x13U, 0xC0U, 0x00U, 0xA0U, 0x40U, 0x00U,  // 0xB00: MOVE.B D0,($00A04000).L
        0x4EU, 0x70U,                              // 0xB06: RESET -- the CPU frontier
    };
    segarecomp::FrontendProgram program{};
    program.profile = segarecomp::M68kFrontendProfile::general_startup;
    program.image = {"synthetic/SEG-007-T171/ym2612-routed-write", block, block.size()};
    program.mapping_claims = {{"synthetic-ym2612-select-write", {{}, 0xB00U}, {{}, 0xB08U}, {0U}, {8U}}};
    program.startup_ingress = segarecomp::M68kStartupIngress{{{}, 0xB00U}, 0x00FF0100U};
    const auto result = segarecomp::analyze_m68k_frontend(program);
    const auto *partial = std::get_if<segarecomp::FrontendPartialProgram>(&result);
    expect(partial != nullptr && partial->accepted_prefix.static_memory_facts.size() == 1U &&
               partial->accepted_prefix.static_blocks.size() == 1U,
           "a YM2612-window-admitted MOVE.B write retains exactly one static memory fact and one block");
    if (partial != nullptr && partial->accepted_prefix.static_memory_facts.size() == 1U) {
      const auto &fact = partial->accepted_prefix.static_memory_facts.front();
      expect(fact.role == segarecomp::M68kStaticMemoryFactRole::destination_write &&
                 fact.address.value == UINT32_C(0x00A04000) &&
                 fact.width == segarecomp::M68kMemoryAccessWidth::byte &&
                 fact.direction == segarecomp::M68kMemoryAccessDirection::write &&
                 fact.region == segarecomp::M68kAbsoluteOperandRegion::routed_device,
             "the retained fact is a routed_device BYTE destination_write of the exact YM2612 address port address");
      expect(!expand_entry_rows(segarecomp::emit_m68k_general_startup_runtime_c(*partial)).starts_with("/* translation rejected"),
             "the retained routed_device write lowers to generated C without rejection");
    }
  }

  // Discovery retains a value-free routed_device destination_write fact for a
  // MOVE.B D1,($A04001).L (the register-data write shape actually reached by
  // the authorized production route's own third frontier pass), and does not
  // make that write the frontier.
  {
    const std::vector<std::uint8_t> block{
        0x13U, 0xC1U, 0x00U, 0xA0U, 0x40U, 0x01U,  // 0xB00: MOVE.B D1,($00A04001).L
        0x4EU, 0x70U,                              // 0xB06: RESET -- the CPU frontier
    };
    segarecomp::FrontendProgram program{};
    program.profile = segarecomp::M68kFrontendProfile::general_startup;
    program.image = {"synthetic/SEG-007-T171/ym2612-routed-data-write", block, block.size()};
    program.mapping_claims = {{"synthetic-ym2612-data-write", {{}, 0xB00U}, {{}, 0xB08U}, {0U}, {8U}}};
    program.startup_ingress = segarecomp::M68kStartupIngress{{{}, 0xB00U}, 0x00FF0100U};
    const auto result = segarecomp::analyze_m68k_frontend(program);
    const auto *partial = std::get_if<segarecomp::FrontendPartialProgram>(&result);
    expect(partial != nullptr && partial->accepted_prefix.static_memory_facts.size() == 1U &&
               partial->accepted_prefix.static_blocks.size() == 1U,
           "a YM2612-window-admitted data-port MOVE.B write retains exactly one static memory fact and one block");
    if (partial != nullptr && partial->accepted_prefix.static_memory_facts.size() == 1U) {
      const auto &fact = partial->accepted_prefix.static_memory_facts.front();
      expect(fact.role == segarecomp::M68kStaticMemoryFactRole::destination_write &&
                 fact.address.value == UINT32_C(0x00A04001) &&
                 fact.width == segarecomp::M68kMemoryAccessWidth::byte &&
                 fact.direction == segarecomp::M68kMemoryAccessDirection::write &&
                 fact.region == segarecomp::M68kAbsoluteOperandRegion::routed_device,
             "the retained fact is a routed_device BYTE destination_write of the exact YM2612 data port address");
      expect(!expand_entry_rows(segarecomp::emit_m68k_general_startup_runtime_c(*partial)).starts_with("/* translation rejected"),
             "the retained routed_device data-port write lowers to generated C without rejection");
    }
  }

  // Discovery retains a value-free routed_device destination_write fact for a
  // MOVE.B D0,($A04002).L (the PART-II register-select write shape actually
  // reached by the authorized production route's own fourth frontier pass),
  // and does not make that write the frontier.
  {
    const std::vector<std::uint8_t> block{
        0x13U, 0xC0U, 0x00U, 0xA0U, 0x40U, 0x02U,  // 0xB00: MOVE.B D0,($00A04002).L
        0x4EU, 0x70U,                              // 0xB06: RESET -- the CPU frontier
    };
    segarecomp::FrontendProgram program{};
    program.profile = segarecomp::M68kFrontendProfile::general_startup;
    program.image = {"synthetic/SEG-007-T171/ym2612-routed-part2-select-write", block, block.size()};
    program.mapping_claims = {{"synthetic-ym2612-part2-select-write", {{}, 0xB00U}, {{}, 0xB08U}, {0U}, {8U}}};
    program.startup_ingress = segarecomp::M68kStartupIngress{{{}, 0xB00U}, 0x00FF0100U};
    const auto result = segarecomp::analyze_m68k_frontend(program);
    const auto *partial = std::get_if<segarecomp::FrontendPartialProgram>(&result);
    expect(partial != nullptr && partial->accepted_prefix.static_memory_facts.size() == 1U &&
               partial->accepted_prefix.static_blocks.size() == 1U,
           "a YM2612-window-admitted PART-II select-port MOVE.B write retains exactly one static "
           "memory fact and one block");
    if (partial != nullptr && partial->accepted_prefix.static_memory_facts.size() == 1U) {
      const auto &fact = partial->accepted_prefix.static_memory_facts.front();
      expect(fact.role == segarecomp::M68kStaticMemoryFactRole::destination_write &&
                 fact.address.value == UINT32_C(0x00A04002) &&
                 fact.width == segarecomp::M68kMemoryAccessWidth::byte &&
                 fact.direction == segarecomp::M68kMemoryAccessDirection::write &&
                 fact.region == segarecomp::M68kAbsoluteOperandRegion::routed_device,
             "the retained fact is a routed_device BYTE destination_write of the exact YM2612 "
             "PART-II address port address");
      expect(!expand_entry_rows(segarecomp::emit_m68k_general_startup_runtime_c(*partial)).starts_with("/* translation rejected"),
             "the retained routed_device PART-II select-port write lowers to generated C without rejection");
    }
  }

  // Discovery retains a value-free routed_device destination_write fact for a
  // MOVE.B D1,($A04003).L (the PART-II register-data write shape actually
  // reached by the authorized production route's own fifth frontier pass),
  // and does not make that write the frontier.
  {
    const std::vector<std::uint8_t> block{
        0x13U, 0xC1U, 0x00U, 0xA0U, 0x40U, 0x03U,  // 0xB00: MOVE.B D1,($00A04003).L
        0x4EU, 0x70U,                              // 0xB06: RESET -- the CPU frontier
    };
    segarecomp::FrontendProgram program{};
    program.profile = segarecomp::M68kFrontendProfile::general_startup;
    program.image = {"synthetic/SEG-007-T171/ym2612-routed-part2-data-write", block, block.size()};
    program.mapping_claims = {{"synthetic-ym2612-part2-data-write", {{}, 0xB00U}, {{}, 0xB08U}, {0U}, {8U}}};
    program.startup_ingress = segarecomp::M68kStartupIngress{{{}, 0xB00U}, 0x00FF0100U};
    const auto result = segarecomp::analyze_m68k_frontend(program);
    const auto *partial = std::get_if<segarecomp::FrontendPartialProgram>(&result);
    expect(partial != nullptr && partial->accepted_prefix.static_memory_facts.size() == 1U &&
               partial->accepted_prefix.static_blocks.size() == 1U,
           "a YM2612-window-admitted PART-II data-port MOVE.B write retains exactly one static "
           "memory fact and one block");
    if (partial != nullptr && partial->accepted_prefix.static_memory_facts.size() == 1U) {
      const auto &fact = partial->accepted_prefix.static_memory_facts.front();
      expect(fact.role == segarecomp::M68kStaticMemoryFactRole::destination_write &&
                 fact.address.value == UINT32_C(0x00A04003) &&
                 fact.width == segarecomp::M68kMemoryAccessWidth::byte &&
                 fact.direction == segarecomp::M68kMemoryAccessDirection::write &&
                 fact.region == segarecomp::M68kAbsoluteOperandRegion::routed_device,
             "the retained fact is a routed_device BYTE destination_write of the exact YM2612 "
             "PART-II data port address");
      expect(!expand_entry_rows(segarecomp::emit_m68k_general_startup_runtime_c(*partial)).starts_with("/* translation rejected"),
             "the retained routed_device PART-II data-port write lowers to generated C without rejection");
    }
  }
}

// SEG-007-T166: the controller-I/O DATA1/DATA2 three-button-pad BYTE-READ
// selector family. Unlike the fixed-constant selectors above, this is a
// state-dependent access the static resolver defers to the runtime, exactly
// like the VDP status-register read and the SEG-007-T121 GPIO BYTE-write
// family above -- it reduces to the value-free M68kDeviceRoutedAccess
// marker, never to a folded m68k_controller_io_access constant.
void general_startup_routes_data1_data2_byte_reads_to_the_runtime() {
  using W = segarecomp::M68kMemoryAccessWidth;
  using D = segarecomp::M68kMemoryAccessDirection;
  using segarecomp::M68kDeviceRoutedAccess;
  const auto request = [](std::uint32_t address, W width, D direction) {
    return segarecomp::M68kMemoryAccessRequest{
        {segarecomp::TargetAddressSpace::m68k_program, address}, width, direction, std::nullopt};
  };
  const auto routes = [&](std::uint32_t address, W width, D direction) {
    const auto routed = segarecomp::m68k_route_genesis_device_access(request(address, width, direction));
    const auto *marker = std::get_if<M68kDeviceRoutedAccess>(&routed);
    return marker != nullptr && marker->direction == direction;
  };
  // "Not this new family" -- every one of these neighbours still reaches
  // whatever pre-existing fail-closed outcome it already had (either the
  // generic unmapped_data_access diagnostic outside the region, or the
  // unchanged fixed-selector table's own M68kControllerIoFailure inside the
  // region); none of them is newly routed to M68kDeviceRoutedAccess by this
  // task's DATA1/DATA2 BYTE-read addition.
  const auto not_routed = [&](std::uint32_t address, W width, D direction) {
    const auto routed = segarecomp::m68k_route_genesis_device_access(request(address, width, direction));
    return std::get_if<M68kDeviceRoutedAccess>(&routed) == nullptr;
  };

  // DATA1 ($A10003) and DATA2 ($A10005) BYTE reads both route.
  expect(routes(0x00A10003U, W::byte, D::read) && routes(0x00A10005U, W::byte, D::read),
         "a BYTE read of DATA1 or DATA2 routes to M68kDeviceRoutedAccess");

  // Fail-closed neighbours -- every one stays unrouted, reaching the
  // unchanged fixed-selector fallback table (which itself continues to
  // reject them exactly as before this task).
  expect(not_routed(0x00A10007U, W::byte, D::read) &&   // DATA3: deliberately out of scope
             not_routed(0x00A10003U, W::word, D::read) &&  // WORD read at DATA1
             not_routed(0x00A10003U, W::long_word, D::read) && // LONG read at DATA1
             not_routed(0x00A10005U, W::word, D::read) &&  // WORD read at DATA2
             not_routed(0x00A10009U, W::byte, D::read) &&  // CTRL1 read (write-only GPIO family)
             not_routed(0x00A10001U, W::byte, D::write) &&  // Version register write (unrelated, read-only)
             not_routed(0x00A10021U, W::byte, D::read),    // just past the controller-I/O region end
         "DATA3, non-BYTE DATA1/DATA2 reads, and every neighbouring controller-I/O shape stay unrouted");

  // The DATA1 write shape is still separately routed by the SEG-007-T121
  // write family above (this task does not change it).
  expect(routes(0x00A10003U, W::byte, D::write),
         "a BYTE write of DATA1 still routes via the unchanged SEG-007-T121 GPIO write family");

  // The resolver reduces the routed DATA1/DATA2 read shapes to the same
  // value-free routed_device operand as every other deferred-to-runtime
  // shape.
  const std::array<std::uint8_t, 0> empty{};
  const std::span<const std::uint8_t> image{empty};
  for (const auto address : {UINT32_C(0x00A10003), UINT32_C(0x00A10005)}) {
    const auto resolved =
        segarecomp::m68k_resolve_absolute_test_operand(image, address, W::byte, D::read, std::nullopt);
    const auto *operand = std::get_if<segarecomp::M68kAbsoluteTestOperand>(&resolved);
    expect(operand != nullptr && operand->region == segarecomp::M68kAbsoluteOperandRegion::routed_device &&
               operand->value == 0U,
           "m68k_resolve_absolute_test_operand yields a value-free routed_device operand for a DATA1/DATA2 BYTE read");
  }
}

// SEG-007-T040 (C3): the narrowest edge case C2's own two-instruction
// [TST, BRA] fixture does not cover -- a controller-I/O-routed TST.L read
// that is the very first (and only) instruction of the retained prefix,
// immediately, directly followed by the unsupported/frontier RESET with no
// intervening BRA. Before this checkpoint's block-construction fix, this
// exact shape fell through to the "instruction not found" branch of
// build_analysis's block-completion loop (the frontier RESET never decodes,
// so it is never present in decoded_by_address) and was discarded as though
// merely truncated, leaving static_blocks empty and failing
// runtime_frontier_eligible's `!prefix.static_blocks.empty()` precondition
// -- a plain FrontendRejected, not a promoted FrontendPartialProgram. This
// test proves, by independent construction, that the fix (a general,
// non-instruction-specific extension of the existing
// `block_entries.contains(next_pc)` block-merge case to also match a
// straight-line advance directly into the already-tracked frontier address)
// closes that gap for exactly this minimal shape.
void general_startup_promotes_a_minimal_single_instruction_block_at_a_controller_io_routed_read() {
  const std::vector<std::uint8_t> image{
      0x4AU, 0xB9U, 0x00U, 0xA1U, 0x00U, 0x08U,  // 0xB00: TST.L $00A10008 (CTRL1/CTRL2 selector: routed success)
      0x4EU, 0x70U,                              // 0xB06: RESET -- unsupported CPU form, immediately following
  };
  segarecomp::FrontendProgram program{};
  program.profile = segarecomp::M68kFrontendProfile::general_startup;
  program.image = {"synthetic/SEG-007-T040/c3-minimal-single-instruction-block", image, image.size()};
  program.mapping_claims = {{"synthetic-c3-minimal", {{}, 0xB00U}, {{}, 0xB08U}, {0U}, {8U}}};
  program.startup_ingress = segarecomp::M68kStartupIngress{{{}, 0xB00U}, 0x00FF0100U};

  const auto result = segarecomp::analyze_m68k_frontend(program);
  const auto *partial = std::get_if<segarecomp::FrontendPartialProgram>(&result);
  expect(partial != nullptr &&
             partial->frontiers.front().class_ == segarecomp::GenesisFrontierClass::unsupported_cpu_form &&
             partial->accepted_prefix.static_blocks.size() == 1U &&
             partial->accepted_prefix.static_blocks.front().instructions.size() == 1U &&
             partial->accepted_prefix.decoded.size() == 1U &&
             partial->accepted_prefix.decoded.front().kind == segarecomp::M68kInstructionKind::tst,
         "a CTRL1/CTRL2-routed TST.L that is the program's very first and only retained instruction is "
         "promoted into a one-block, one-instruction accepted prefix even with no BRA separating it from "
         "the immediately following unsupported RESET frontier");
  if (partial == nullptr) return;

  const auto &diagnostic = partial->frontiers.front().diagnostic;
  expect((diagnostic.category == segarecomp::DirectFlowDiagnostic::valid_but_unsupported_instruction ||
              diagnostic.category == segarecomp::DirectFlowDiagnostic::unsupported_instruction_form) &&
             diagnostic.source_address && diagnostic.source_address->value == 0xB06U &&
             diagnostic.provenance && diagnostic.provenance->bytes == std::array<std::uint8_t, 2>{0x4EU, 0x70U},
         "the frontier correctly identifies the immediately following RESET as the unsupported instruction");

  const auto &facts = partial->accepted_prefix.static_memory_facts;
  expect(facts.size() == 1U, "exactly one static memory fact is retained for the routed TST.L read");
  if (facts.size() != 1U) return;
  const auto &fact = facts.front();
  expect(fact.role == segarecomp::M68kStaticMemoryFactRole::source_read &&
             fact.address.space == segarecomp::TargetAddressSpace::m68k_program &&
             fact.address.value == UINT32_C(0x00A10008) &&
             fact.width == segarecomp::M68kMemoryAccessWidth::long_word &&
             fact.direction == segarecomp::M68kMemoryAccessDirection::read &&
             fact.region == segarecomp::M68kAbsoluteOperandRegion::controller_io &&
             fact.operation.source.address.value == 0xB00U,
         "the retained fact is a controller_io-region source_read of the exact routed CTRL1/CTRL2 address, "
         "width, and direction, attributed to the TST.L instruction's own (sole, block-first) provenance");
}

// SEG-007-T032: an ineligible (never promoted) general_startup controller-I/O
// rejection through the actual production discover_m68k_general_startup /
// format_m68k_frontend_result path. Ineligibility is forced by an overlong
// (>64 character) mapping-claim name -- an existing, orthogonal
// runtime_frontier_eligible gate (see
// general_startup_rejects_an_unrepresentable_mapping_name_at_a_cpu_frontier
// above) -- so every fixture below reaches the exact `return *failure;`
// discard site SEG-007-T031 identified, exactly as the real Sonic ROM's own
// recorded outcome does (`result: "rejected"`, never `"partial"`).
segarecomp::FrontendRejected general_startup_ineligible_controller_io_rejection(
    std::uint32_t begin, const std::vector<std::uint8_t> &device_instruction, const char *label) {
  std::vector<std::uint8_t> image{0x60U, 0x02U, 0x00U, 0x00U};
  image.insert(image.end(), device_instruction.begin(), device_instruction.end());
  segarecomp::FrontendProgram program{};
  program.profile = segarecomp::M68kFrontendProfile::general_startup;
  program.image = {std::string("synthetic/SEG-007-T032/") + label, image, image.size()};
  program.mapping_claims = {{std::string(65U, 'x'), {{}, begin},
                             {{}, begin + static_cast<std::uint32_t>(image.size())}, {0U},
                             {static_cast<std::uint64_t>(image.size())}}};
  program.startup_ingress = segarecomp::M68kStartupIngress{{{}, begin}, 0x00FF0100U};
  const auto result = segarecomp::analyze_m68k_frontend(program);
  const auto *rejected = std::get_if<segarecomp::FrontendRejected>(&result);
  expect(rejected != nullptr, "an overlong mapping name makes the device rejection ineligible for promotion");
  return rejected != nullptr ? *rejected : segarecomp::FrontendRejected{};
}

void general_startup_preserves_rejected_controller_io_access_shape() {
  using segarecomp::ControllerIoAccessShapeMismatch;
  using W = segarecomp::M68kMemoryAccessWidth;
  using D = segarecomp::M68kMemoryAccessDirection;

  const auto expect_populated = [&](std::uint32_t begin, const std::vector<std::uint8_t> &device_instruction,
                                    const char *label, W expected_width, D expected_direction,
                                    std::vector<ControllerIoAccessShapeMismatch> expected_mismatches,
                                    const char *message) {
    const auto rejected = general_startup_ineligible_controller_io_rejection(begin, device_instruction, label);
    expect(rejected.category == segarecomp::DirectFlowDiagnostic::unsupported_device_region_controller_io &&
               rejected.controller_io_access_shape.has_value() &&
               rejected.controller_io_access_shape->width == expected_width &&
               rejected.controller_io_access_shape->direction == expected_direction &&
               rejected.controller_io_access_shape->mismatches == expected_mismatches,
           message);
    return rejected;
  };

  // {direction} alone: an exact-selector LONG write (MOVE.L D0,$00A10008.L),
  // reached through the write branch of the shared static-operand resolver.
  expect_populated(0x00003000U, {0x23U, 0xC0U, 0x00U, 0xA1U, 0x00U, 0x08U}, "c1-direction-alone", W::long_word,
                   D::write, {ControllerIoAccessShapeMismatch::direction},
                   "an exact-selector LONG write reports direction alone through discovery");

  // {partial_or_crossing_shape} alone: an aligned LONG read whose interval
  // overlaps but does not equal the selector interval (TST.L $00A10006).
  expect_populated(0x00003100U, {0x4AU, 0xB9U, 0x00U, 0xA1U, 0x00U, 0x06U}, "c1-partial-crossing-alone",
                   W::long_word, D::read, {ControllerIoAccessShapeMismatch::partial_or_crossing_shape},
                   "an overlapping LONG read reports partial_or_crossing_shape alone through discovery");

  // {different_controller_io_register_shape} alone: an aligned LONG read
  // inside the recognized controller-I/O region whose interval is disjoint
  // from the selector (TST.L $00A10000, the DATA register shape).
  expect_populated(0x00003200U, {0x4AU, 0xB9U, 0x00U, 0xA1U, 0x00U, 0x00U}, "c1-different-register-alone",
                   W::long_word, D::read, {ControllerIoAccessShapeMismatch::different_controller_io_register_shape},
                   "a disjoint in-region LONG read reports different_controller_io_register_shape alone through discovery");

  // width with its unavoidable interval mismatch: a WORD read at the exact
  // selector start (TST.W $00A10008).
  expect_populated(0x00003300U, {0x4AU, 0x79U, 0x00U, 0xA1U, 0x00U, 0x08U}, "c1-width-with-interval", W::word,
                   D::read,
                   {ControllerIoAccessShapeMismatch::width, ControllerIoAccessShapeMismatch::partial_or_crossing_shape},
                   "a WORD read at the selector start reports width with its unavoidable interval mismatch through discovery");

  // A three-value set: a WORD write at the exact selector start
  // (MOVE.W D0,$00A10008.L), combining width, direction, and
  // partial_or_crossing_shape in the fixed declared order.
  expect_populated(0x00003400U, {0x33U, 0xC0U, 0x00U, 0xA1U, 0x00U, 0x08U}, "c1-three-value-set", W::word, D::write,
                   {ControllerIoAccessShapeMismatch::width, ControllerIoAccessShapeMismatch::direction,
                    ControllerIoAccessShapeMismatch::partial_or_crossing_shape},
                   "a WORD write at the selector start reports width, direction, and partial_or_crossing_shape through discovery");

  // JSON serialization: the populated three-value case names its keys
  // exactly "frontier_access_shape"/"width"/"direction"/"mismatches", in the
  // fixed declared mismatch order, and nothing else changes.
  {
    const auto rejected = general_startup_ineligible_controller_io_rejection(
        0x00003400U, {0x33U, 0xC0U, 0x00U, 0xA1U, 0x00U, 0x08U}, "c1-three-value-set-json");
    const segarecomp::FrontendResult wrapped = rejected;
    const auto json = segarecomp::format_m68k_frontend_result(wrapped);
    expect(json.find("\"frontier_access_shape\":{\"width\":\"word\",\"direction\":\"write\",\"mismatches\":"
                     "[\"width\",\"direction\",\"partial_or_crossing_shape\"]}") != std::string::npos,
           "the serialized frontier_access_shape uses the documented key names and fixed mismatch order");
    expect(json == segarecomp::format_m68k_frontend_result(wrapped),
           "two independent invocations of the same scoped-case input produce byte-identical JSON");
  }

  // The exact T021 selector itself, reached through full production
  // discovery: a closed two-instruction block (TST.L $00A10008 then a BRA.s
  // back to that same block's own entry) resolves and completes
  // successfully, producing a plain accepted FrontendAnalysis -- not a
  // FrontendRejected at all -- so this task's field (which exists only on
  // FrontendRejected) cannot appear anywhere in the result. This is a
  // direct proof that reaching the exact selector never becomes any kind of
  // rejection or frontier under this task's change.
  {
    const std::vector<std::uint8_t> image{
        0x60U, 0x02U, 0x00U, 0x00U,                    // 0x00: BRA.s -> +4
        0x4AU, 0xB9U, 0x00U, 0xA1U, 0x00U, 0x08U,      // 0x04: TST.L $00A10008 (exact selector, succeeds)
        0x60U, 0xF8U,                                   // 0x0A: BRA.s -> +4 (self-loop, closes the graph)
    };
    const std::uint32_t begin = 0x00003500U;
    segarecomp::FrontendProgram program{};
    program.profile = segarecomp::M68kFrontendProfile::general_startup;
    program.image = {"synthetic/SEG-007-T032/c1-selector-unchanged", image, image.size()};
    program.mapping_claims = {{"rom", {{}, begin}, {{}, begin + static_cast<std::uint32_t>(image.size())}, {0U},
                               {static_cast<std::uint64_t>(image.size())}}};
    program.startup_ingress = segarecomp::M68kStartupIngress{{{}, begin}, 0x00FF0100U};
    const auto result = segarecomp::analyze_m68k_frontend(program);
    const auto *accepted = std::get_if<segarecomp::FrontendAnalysis>(&result);
    expect(accepted != nullptr && accepted->decoded.size() == 3U,
           "the exact T021 selector still resolves successfully through discovery with no mismatch set and no behavior change");
  }

  // Absence, proved byte-for-byte against a genuine pre-change baseline: each
  // expected literal below was captured by building and running these exact
  // fixtures against origin/main @ 5413ef8 (this task's own unmodified branch
  // point, before controller_io_access_shape/frontier_access_shape existed),
  // in a disposable, uncommitted worktree/harness -- never by re-running this
  // task's own current implementation and calling that a baseline. Any
  // deviation beyond the deliberately scoped populated rejection is a
  // regression. The substring-absence checks are retained as complementary,
  // change-resilient checks alongside the exact comparison.

  // Absence: category matches but frontier_access was never computed for it
  // (a hand-built rejected value, exercising the formatter's own gate
  // directly -- production discovery never reaches this exact combination,
  // since frontier_access is always computed whenever this category fires).
  {
    segarecomp::FrontendRejected unpopulated{};
    unpopulated.profile = segarecomp::M68kFrontendProfile::general_startup;
    unpopulated.category = segarecomp::DirectFlowDiagnostic::unsupported_device_region_controller_io;
    const segarecomp::FrontendResult wrapped = unpopulated;
    const auto json = segarecomp::format_m68k_frontend_result(wrapped);
    const std::string expected_pre_change_json =
        "{\"result\":\"rejected\",\"category\":\"unsupported_device_region_controller_io\","
        "\"image_source_id\":null,\"source_address\":null,\"image_offset\":null,"
        "\"available_bytes\":null,\"requested_length\":null,\"instruction_length\":null,"
        "\"provenance\":null,\"mapping_claims\":null,\"accesses\":[]}";
    expect(!unpopulated.controller_io_access_shape && json.find("frontier_access_shape") == std::string::npos,
           "an otherwise-matching category with no computed frontier_access emits no new key");
    expect(json == expected_pre_change_json,
           "an otherwise-matching category with no computed frontier_access is byte-for-byte unchanged"
           " from the pre-change baseline");
  }

  // Absence: a different rejection category under general_startup.
  {
    const std::vector<std::uint8_t> image{0x4EU, 0x70U};
    segarecomp::FrontendProgram program{};
    program.profile = segarecomp::M68kFrontendProfile::general_startup;
    program.image = {"synthetic/SEG-007-T032/c1-other-category", image, image.size()};
    program.mapping_claims = {{"rom", {{}, 0x00003600U}, {{}, 0x00003602U}, {0U}, {2U}}};
    program.startup_ingress = segarecomp::M68kStartupIngress{{{}, 0x00003600U}, 0x00FF0100U};
    const auto result = segarecomp::analyze_m68k_frontend(program);
    const auto *rejected = std::get_if<segarecomp::FrontendRejected>(&result);
    const segarecomp::FrontendResult wrapped = result;
    const auto json = segarecomp::format_m68k_frontend_result(wrapped);
    const std::string expected_pre_change_json =
        "{\"result\":\"rejected\",\"category\":\"valid_but_unsupported_instruction\","
        "\"image_source_id\":\"synthetic/SEG-007-T032/c1-other-category\","
        "\"source_address\":\"0x00003600\",\"image_offset\":0,\"available_bytes\":null,"
        "\"requested_length\":null,\"instruction_length\":2,\"provenance\":{\"source_address\":"
        "\"0x00003600\",\"image_offset\":0,\"raw_bytes\":\"4E70\",\"length\":2},\"mapping_claims\":"
        "[{\"name\":\"rom\",\"target_begin\":\"0x00003600\",\"target_end\":\"0x00003602\","
        "\"image_begin\":0,\"image_end\":2}],\"accesses\":[{\"ordinal\":0,\"kind\":0,\"address\":"
        "\"0x00003600\",\"bytes\":\"4E70\",\"length\":2,\"region\":\"raw_cartridge_rom\"}]}";
    expect(rejected != nullptr &&
               rejected->category == segarecomp::DirectFlowDiagnostic::valid_but_unsupported_instruction &&
               !rejected->controller_io_access_shape && json.find("frontier_access_shape") == std::string::npos,
           "a different rejection category under general_startup emits no new key");
    expect(json == expected_pre_change_json,
           "a different rejection category under general_startup is byte-for-byte unchanged"
           " from the pre-change baseline");
  }

  // Absence: the genesis_rom_startup profile can reach the exact same
  // category through its own free-function resolver call, which never
  // computes frontier_access at all -- the new field must still never appear.
  {
    const std::uint32_t begin = 0x00003700U;
    const std::vector<std::uint8_t> image{0x23U, 0xC0U, 0x00U, 0xA1U, 0x00U, 0x00U}; // MOVE.L D0,$00A10000.L
    segarecomp::FrontendProgram program{};
    program.profile = segarecomp::M68kFrontendProfile::genesis_rom_startup;
    program.image = {"synthetic/SEG-007-T032/c1-genesis-rom-startup", image, image.size()};
    program.mapping_claims = {{"rom", {{}, begin}, {{}, begin + static_cast<std::uint32_t>(image.size())}, {0U},
                               {static_cast<std::uint64_t>(image.size())}}};
    program.startup_ingress = segarecomp::M68kStartupIngress{{{}, begin}, 0x00FF0100U};
    const auto result = segarecomp::analyze_m68k_frontend(program);
    const auto *rejected = std::get_if<segarecomp::FrontendRejected>(&result);
    const segarecomp::FrontendResult wrapped = result;
    const auto json = segarecomp::format_m68k_frontend_result(wrapped);
    const std::string expected_pre_change_json =
        "{\"result\":\"rejected\",\"category\":\"unsupported_device_region_controller_io\","
        "\"image_source_id\":\"synthetic/SEG-007-T032/c1-genesis-rom-startup\",\"source_address\":"
        "\"0x00003700\",\"image_offset\":0,\"available_bytes\":null,\"requested_length\":null,"
        "\"instruction_length\":6,\"provenance\":{\"source_address\":\"0x00003700\",\"image_offset\":0,"
        "\"raw_bytes\":\"23C0\",\"length\":6},\"mapping_claims\":[{\"name\":\"rom\",\"target_begin\":"
        "\"0x00003700\",\"target_end\":\"0x00003706\",\"image_begin\":0,\"image_end\":6}],\"accesses\":"
        "[{\"ordinal\":0,\"kind\":0,\"address\":\"0x00003700\",\"bytes\":\"23C000A10000\",\"length\":6,"
        "\"region\":\"raw_cartridge_rom\"}]}";
    expect(rejected != nullptr &&
               rejected->category == segarecomp::DirectFlowDiagnostic::unsupported_device_region_controller_io &&
               rejected->profile == segarecomp::M68kFrontendProfile::genesis_rom_startup &&
               !rejected->controller_io_access_shape && json.find("frontier_access_shape") == std::string::npos,
           "the same category under genesis_rom_startup emits no new key");
    expect(json == expected_pre_change_json,
           "the same category under genesis_rom_startup is byte-for-byte unchanged from the pre-change baseline");
  }

  // Absence: the direct_flow profile.
  {
    segarecomp::FrontendProgram program{{}, {"synthetic/SEG-007-T032/c1-direct-flow", {0x4AU, 0xFCU}, 2U},
                                        {{"mapped", {{}, 0x100U}, {{}, 0x102U}, {0U}, {2U}}}, {{{}, 0x100U}}};
    const auto result = segarecomp::analyze_m68k_frontend(program);
    const auto *rejected = std::get_if<segarecomp::FrontendRejected>(&result);
    const segarecomp::FrontendResult wrapped = result;
    const auto json = segarecomp::format_m68k_frontend_result(wrapped);
    const std::string expected_pre_change_json =
        "{\"result\":\"rejected\",\"category\":\"illegal_instruction\",\"image_source_id\":"
        "\"synthetic/SEG-007-T032/c1-direct-flow\"}";
    expect(rejected != nullptr && rejected->profile == segarecomp::M68kFrontendProfile::direct_flow &&
               !rejected->controller_io_access_shape && json.find("frontier_access_shape") == std::string::npos,
           "the direct_flow profile emits no new key");
    expect(json == expected_pre_change_json,
           "the direct_flow profile is byte-for-byte unchanged from the pre-change baseline");
  }

  // A neighboring unsupported access (a different device-region rejection)
  // still fails closed with its existing category and no new field.
  {
    const std::vector<std::uint8_t> image{0x60U, 0x02U, 0x00U, 0x00U,             // BRA.s -> +4
                                          0x20U, 0x39U, 0x00U, 0x20U, 0x00U, 0x00U}; // MOVE.L $00200000,D0
    const std::uint32_t begin = 0x00003800U;
    segarecomp::FrontendProgram program{};
    program.profile = segarecomp::M68kFrontendProfile::general_startup;
    program.image = {"synthetic/SEG-007-T032/c1-neighboring-unmapped", image, image.size()};
    program.mapping_claims = {{"rom", {{}, begin}, {{}, begin + static_cast<std::uint32_t>(image.size())}, {0U},
                               {static_cast<std::uint64_t>(image.size())}}};
    program.startup_ingress = segarecomp::M68kStartupIngress{{{}, begin}, 0x00FF0100U};
    const auto result = segarecomp::analyze_m68k_frontend(program);
    const auto *partial = std::get_if<segarecomp::FrontendPartialProgram>(&result);
    expect(partial != nullptr &&
               partial->frontiers.front().class_ == segarecomp::GenesisFrontierClass::unsupported_memory_region &&
               partial->frontiers.front().diagnostic.category == segarecomp::DirectFlowDiagnostic::unmapped_data_access &&
               !partial->frontiers.front().diagnostic.controller_io_access_shape,
           "a neighboring unmapped-memory access still fails closed with no new field");
  }
}

// SEG-007-T035: an ineligible (never promoted) general_startup controller-I/O
// rejection through the actual production discover_m68k_general_startup /
// format_m68k_frontend_result path, reusing
// general_startup_ineligible_controller_io_rejection exactly as
// general_startup_preserves_rejected_controller_io_access_shape does above.
void general_startup_preserves_rejected_controller_io_target_register_class() {
  using segarecomp::ControllerIoAccessShapeMismatch;
  using segarecomp::ControllerIoTargetRegisterClass;

  // Populated: RxDATA1, WORD read at $00A10010 (the WORD-form interval
  // [0x00A10010, 0x00A10012) immediately preceding RxDATA1's own public odd
  // address 0x00A10011 -- TST.W $00A10010.L).
  {
    const auto rejected = general_startup_ineligible_controller_io_rejection(
        0x00003900U, {0x4AU, 0x79U, 0x00U, 0xA1U, 0x00U, 0x10U}, "c2-rx-data1-word");
    // A WORD access is itself already a `width` mismatch (the T032 shape's
    // own width value is `request.width != long_word`), independently of
    // and in addition to `different_controller_io_register_shape` -- see the
    // fixed declared mismatch order in ControllerIoAccessShapeMismatch's own
    // doc comment.
    expect(rejected.category == segarecomp::DirectFlowDiagnostic::unsupported_device_region_controller_io &&
               rejected.controller_io_access_shape.has_value() &&
               rejected.controller_io_access_shape->mismatches ==
                   std::vector<ControllerIoAccessShapeMismatch>{
                       ControllerIoAccessShapeMismatch::width,
                       ControllerIoAccessShapeMismatch::different_controller_io_register_shape} &&
               rejected.controller_io_access_shape->target_register_class.has_value() &&
               *rejected.controller_io_access_shape->target_register_class == ControllerIoTargetRegisterClass::rx_data,
           "a WORD read exactly at RxDATA1's WORD-form interval reports target_register_class rx_data through"
           " discovery");

    // JSON serialization: the populated case names the new key exactly
    // "target_register_class", after the mismatches array closes and before
    // the frontier_access_shape object closes, and is deterministic across
    // two independent invocations.
    const segarecomp::FrontendResult wrapped = rejected;
    const auto json = segarecomp::format_m68k_frontend_result(wrapped);
    expect(json.find("\"frontier_access_shape\":{\"width\":\"word\",\"direction\":\"read\",\"mismatches\":"
                     "[\"width\",\"different_controller_io_register_shape\"],\"target_register_class\":\"rx_data\"}") !=
               std::string::npos,
           "the serialized frontier_access_shape carries target_register_class with the documented key name/value,"
           " nested after mismatches closes and before the object closes");
    expect(json == segarecomp::format_m68k_frontend_result(wrapped),
           "two independent invocations of the same populated target_register_class input produce byte-identical"
           " JSON");
  }

  // Absence: a width-only-shaped mismatch set (no
  // different_controller_io_register_shape) never populates
  // target_register_class -- reusing the exact partial_or_crossing_shape-alone
  // fixture from general_startup_preserves_rejected_controller_io_access_shape
  // above (TST.L $00A10006).
  {
    const auto rejected = general_startup_ineligible_controller_io_rejection(
        0x00003A00U, {0x4AU, 0xB9U, 0x00U, 0xA1U, 0x00U, 0x06U}, "c2-partial-crossing-absence");
    expect(rejected.controller_io_access_shape.has_value() &&
               rejected.controller_io_access_shape->mismatches ==
                   std::vector<ControllerIoAccessShapeMismatch>{
                       ControllerIoAccessShapeMismatch::partial_or_crossing_shape} &&
               !rejected.controller_io_access_shape->target_register_class,
           "a partial_or_crossing_shape-only mismatch set leaves target_register_class absent");
    const segarecomp::FrontendResult wrapped = rejected;
    const auto json = segarecomp::format_m68k_frontend_result(wrapped);
    expect(json.find("target_register_class") == std::string::npos,
           "a partial_or_crossing_shape-only mismatch set emits no target_register_class key at all");
  }

  // Absence: the exact T020/T021 selector itself resolves successfully
  // (accepted, not rejected at all), so no frontier_access_shape -- and thus
  // no target_register_class -- can appear anywhere in the result.
  {
    const std::vector<std::uint8_t> image{
        0x60U, 0x02U, 0x00U, 0x00U,               // 0x00: BRA.s -> +4
        0x4AU, 0xB9U, 0x00U, 0xA1U, 0x00U, 0x08U, // 0x04: TST.L $00A10008 (exact selector, succeeds)
        0x60U, 0xF8U,                             // 0x0A: BRA.s -> +4 (self-loop, closes the graph)
    };
    const std::uint32_t begin = 0x00003B00U;
    segarecomp::FrontendProgram program{};
    program.profile = segarecomp::M68kFrontendProfile::general_startup;
    program.image = {"synthetic/SEG-007-T035/c2-selector-unchanged", image, image.size()};
    program.mapping_claims = {{"rom", {{}, begin}, {{}, begin + static_cast<std::uint32_t>(image.size())}, {0U},
                               {static_cast<std::uint64_t>(image.size())}}};
    program.startup_ingress = segarecomp::M68kStartupIngress{{{}, begin}, 0x00FF0100U};
    const auto result = segarecomp::analyze_m68k_frontend(program);
    const auto *accepted = std::get_if<segarecomp::FrontendAnalysis>(&result);
    const segarecomp::FrontendResult wrapped = result;
    const auto json = segarecomp::format_m68k_frontend_result(wrapped);
    expect(accepted != nullptr && json.find("target_register_class") == std::string::npos,
           "the exact T020/T021 selector still resolves successfully with no target_register_class anywhere in the"
           " result");
  }

  // Absence, verified byte-for-byte against SEG-007-T032's own pre-existing
  // baseline (unaffected by this task, since this fixture never sets
  // different_controller_io_register_shape at all -- it is a wholly
  // different rejection category): a different rejection category under
  // general_startup.
  {
    const std::vector<std::uint8_t> image{0x4EU, 0x70U};
    segarecomp::FrontendProgram program{};
    program.profile = segarecomp::M68kFrontendProfile::general_startup;
    program.image = {"synthetic/SEG-007-T032/c1-other-category", image, image.size()};
    program.mapping_claims = {{"rom", {{}, 0x00003600U}, {{}, 0x00003602U}, {0U}, {2U}}};
    program.startup_ingress = segarecomp::M68kStartupIngress{{{}, 0x00003600U}, 0x00FF0100U};
    const auto result = segarecomp::analyze_m68k_frontend(program);
    const auto *rejected = std::get_if<segarecomp::FrontendRejected>(&result);
    const segarecomp::FrontendResult wrapped = result;
    const auto json = segarecomp::format_m68k_frontend_result(wrapped);
    const std::string expected_pre_change_json =
        "{\"result\":\"rejected\",\"category\":\"valid_but_unsupported_instruction\","
        "\"image_source_id\":\"synthetic/SEG-007-T032/c1-other-category\","
        "\"source_address\":\"0x00003600\",\"image_offset\":0,\"available_bytes\":null,"
        "\"requested_length\":null,\"instruction_length\":2,\"provenance\":{\"source_address\":"
        "\"0x00003600\",\"image_offset\":0,\"raw_bytes\":\"4E70\",\"length\":2},\"mapping_claims\":"
        "[{\"name\":\"rom\",\"target_begin\":\"0x00003600\",\"target_end\":\"0x00003602\","
        "\"image_begin\":0,\"image_end\":2}],\"accesses\":[{\"ordinal\":0,\"kind\":0,\"address\":"
        "\"0x00003600\",\"bytes\":\"4E70\",\"length\":2,\"region\":\"raw_cartridge_rom\"}]}";
    expect(rejected != nullptr &&
               rejected->category == segarecomp::DirectFlowDiagnostic::valid_but_unsupported_instruction &&
               !rejected->controller_io_access_shape && json.find("target_register_class") == std::string::npos,
           "a different rejection category under general_startup emits no target_register_class key");
    expect(json == expected_pre_change_json,
           "a different rejection category under general_startup is byte-for-byte unchanged from"
           " SEG-007-T032's own pre-existing baseline, unaffected by this task's addition");
  }

  // Absence: the genesis_rom_startup profile.
  {
    const std::uint32_t begin = 0x00003700U;
    const std::vector<std::uint8_t> image{0x23U, 0xC0U, 0x00U, 0xA1U, 0x00U, 0x00U}; // MOVE.L D0,$00A10000.L
    segarecomp::FrontendProgram program{};
    program.profile = segarecomp::M68kFrontendProfile::genesis_rom_startup;
    program.image = {"synthetic/SEG-007-T032/c1-genesis-rom-startup", image, image.size()};
    program.mapping_claims = {{"rom", {{}, begin}, {{}, begin + static_cast<std::uint32_t>(image.size())}, {0U},
                               {static_cast<std::uint64_t>(image.size())}}};
    program.startup_ingress = segarecomp::M68kStartupIngress{{{}, begin}, 0x00FF0100U};
    const auto result = segarecomp::analyze_m68k_frontend(program);
    const auto *rejected = std::get_if<segarecomp::FrontendRejected>(&result);
    const segarecomp::FrontendResult wrapped = result;
    const auto json = segarecomp::format_m68k_frontend_result(wrapped);
    expect(rejected != nullptr &&
               rejected->category == segarecomp::DirectFlowDiagnostic::unsupported_device_region_controller_io &&
               rejected->profile == segarecomp::M68kFrontendProfile::genesis_rom_startup &&
               !rejected->controller_io_access_shape && json.find("target_register_class") == std::string::npos,
           "the same category under genesis_rom_startup emits no target_register_class key");
  }

  // Absence: the direct_flow profile.
  {
    segarecomp::FrontendProgram program{{}, {"synthetic/SEG-007-T032/c1-direct-flow", {0x4AU, 0xFCU}, 2U},
                                        {{"mapped", {{}, 0x100U}, {{}, 0x102U}, {0U}, {2U}}}, {{{}, 0x100U}}};
    const auto result = segarecomp::analyze_m68k_frontend(program);
    const auto *rejected = std::get_if<segarecomp::FrontendRejected>(&result);
    const segarecomp::FrontendResult wrapped = result;
    const auto json = segarecomp::format_m68k_frontend_result(wrapped);
    expect(rejected != nullptr && rejected->profile == segarecomp::M68kFrontendProfile::direct_flow &&
               !rejected->controller_io_access_shape && json.find("target_register_class") == std::string::npos,
           "the direct_flow profile emits no target_register_class key");
  }
}

void general_startup_retains_memory_and_unresolved_frontiers_with_exact_provenance() {
  const std::vector<std::uint8_t> memory_image{0x60U, 0x02U, 0x00U, 0x00U, 0x20U, 0x39U, 0x00U, 0x20U, 0x00U, 0x00U};
  segarecomp::FrontendProgram memory{};
  memory.profile = segarecomp::M68kFrontendProfile::general_startup;
  memory.image = {"synthetic/SEG-007-T029/c1-unmapped", memory_image, memory_image.size()};
  memory.mapping_claims = {{"rom", {{}, 0xE20U}, {{}, 0xE2AU}, {0U}, {10U}}};
  memory.startup_ingress = segarecomp::M68kStartupIngress{{{}, 0xE20U}, 0x00FF0100U};
  const auto memory_result = segarecomp::analyze_m68k_frontend(memory);
  const auto *memory_partial = std::get_if<segarecomp::FrontendPartialProgram>(&memory_result);
  expect(memory_partial != nullptr && memory_partial->frontiers.front().class_ == segarecomp::GenesisFrontierClass::unsupported_memory_region &&
             memory_partial->frontiers.front().access && memory_partial->frontiers.front().access->address.value == 0x00200000U &&
             memory_partial->frontiers.front().access->width == segarecomp::M68kMemoryAccessWidth::long_word &&
             memory_partial->frontiers.front().access->direction == segarecomp::M68kMemoryAccessDirection::read &&
             memory_partial->frontiers.front().access->source_provenance && memory_partial->frontiers.front().diagnostic.provenance &&
             memory_partial->frontiers.front().access->source_provenance->source.cpu_variant == memory_partial->frontiers.front().diagnostic.provenance->source.cpu_variant &&
             memory_partial->frontiers.front().access->source_provenance->source.address.space == memory_partial->frontiers.front().diagnostic.provenance->source.address.space &&
             memory_partial->frontiers.front().access->source_provenance->source.address.value == memory_partial->frontiers.front().diagnostic.provenance->source.address.value &&
             memory_partial->frontiers.front().access->source_provenance->source.image_offset.value == memory_partial->frontiers.front().diagnostic.provenance->source.image_offset.value &&
             memory_partial->frontiers.front().access->source_provenance->bytes == memory_partial->frontiers.front().diagnostic.provenance->bytes,
         "unmapped data becomes an unsupported-memory frontier with the exact read request and provenance");

  const std::vector<std::uint8_t> unresolved_image{0x60U, 0x02U, 0x00U, 0x00U, 0x4EU, 0xD0U};
  segarecomp::FrontendProgram unresolved{};
  unresolved.profile = segarecomp::M68kFrontendProfile::general_startup;
  unresolved.image = {"synthetic/SEG-007-T029/c1-unresolved", unresolved_image, unresolved_image.size()};
  unresolved.mapping_claims = {{"rom", {{}, 0xE40U}, {{}, 0xE46U}, {0U}, {6U}}};
  unresolved.startup_ingress = segarecomp::M68kStartupIngress{{{}, 0xE40U}, 0x00FF0100U};
  const auto unresolved_result = segarecomp::analyze_m68k_frontend(unresolved);
  const auto *unresolved_partial = std::get_if<segarecomp::FrontendPartialProgram>(&unresolved_result);
  expect(unresolved_partial != nullptr &&
             unresolved_partial->frontiers.front().class_ == segarecomp::GenesisFrontierClass::unresolved_indirect_target &&
             !unresolved_partial->frontiers.front().access && unresolved_partial->frontiers.front().diagnostic.provenance &&
             unresolved_partial->frontiers.front().diagnostic.provenance->source.address.value == 0xE44U &&
             unresolved_partial->frontiers.front().diagnostic.provenance->source.cpu_variant == segarecomp::CpuVariant::mc68000 &&
             unresolved_partial->frontiers.front().diagnostic.provenance->source.image_offset.value == 4U &&
             unresolved_partial->frontiers.front().diagnostic.provenance->bytes == std::array<std::uint8_t, 2>{0x4EU, 0xD0U} &&
             unresolved_partial->frontiers.front().diagnostic.provenance->length.value == 2U &&
             !unresolved_partial->frontiers.front().diagnostic.mapping_claims &&
             unresolved_partial->frontiers.front().diagnostic.direct.mapping_claims.empty() &&
             unresolved_partial->frontiers.front().diagnostic.accesses.empty(),
         "an unresolved direct edge retains instruction provenance without mapping, access, or invented request facts");
}

void general_startup_rejects_a_memory_frontier_with_noncanonical_target_identity() {
  // TST.L (xxx).W decodes its operand as sign-extended 0xFFFFFFFE while the
  // shared Genesis resolver canonicalizes the request to 0x00FFFFFE.  The
  // retained diagnostic target must never disagree with that request.
  const std::vector<std::uint8_t> image{0x60U, 0x02U, 0x4AU, 0xB8U, 0xFFU, 0xFEU};
  segarecomp::FrontendProgram program{};
  program.profile = segarecomp::M68kFrontendProfile::general_startup;
  program.image = {"synthetic/SEG-007-T029/c1-absolute-word-target", image, image.size()};
  program.mapping_claims = {{"rom", {{}, 0xE5EU}, {{}, 0xE64U}, {0U}, {6U}}};
  program.startup_ingress = segarecomp::M68kStartupIngress{{{}, 0xE60U}, 0x00FF0100U};

  const auto result = segarecomp::analyze_m68k_frontend(program);
  const auto *rejected = std::get_if<segarecomp::FrontendRejected>(&result);
  expect(rejected != nullptr, "a noncanonical absolute-word target cannot become a retained memory frontier");
  if (rejected != nullptr) {
    expect(rejected->category == segarecomp::DirectFlowDiagnostic::unmapped_data_access,
           "the absolute-word request retains its unmapped-data category");
    expect(rejected->direct.has_target && rejected->direct.target.value == UINT32_C(0xFFFFFFFE),
           "the rejected diagnostic retains the sign-extended decoded target");
  }
}

void general_startup_promotes_a_branch_block_whose_unexplored_sibling_closes_safely() {
  // The BNE has a fallthrough frontier at 0xF02 and a second, valid target at
  // 0xF04. Discovery visits the fallthrough first. Before SEG-007-T062, the
  // taken sibling (0xF04) was registered as a block entry (both of a Bcc's
  // targets are registered before either is walked) but never actually
  // explored, purely because the fallthrough sibling failed first and the
  // discovery walk short-circuited without ever attempting the other arm --
  // build_analysis's own completed-blocks-only reconstruction cannot tell
  // "genuinely undecodable" apart from "simply not yet explored", so it
  // conservatively discarded the whole BNE block (this fixture's own startup
  // entry), producing a plain rejection instead of a promoted partial
  // program, even though 0xF04 (a plain BRA.s -2 self-loop) would have
  // closed perfectly cleanly on its own. SEG-007-T062 makes a best-effort
  // attempt to explore a dual-target branch's *other* arm whenever the
  // first-explored arm fails (see the walk() comments at its own three call
  // sites); this never changes which address is diagnosed as the frontier or
  // the overall discovery outcome, but it does let 0xF04's own block close
  // and become retainable, so the BNE block above it is retainable too:
  // every reachable runtime PC is now accounted for, either by a retained
  // block or by the one diagnosed frontier boundary.
  const std::vector<std::uint8_t> image{0x66U, 0x02U, 0x4EU, 0x70U, 0x60U, 0xFEU};
  segarecomp::FrontendProgram program{};
  program.profile = segarecomp::M68kFrontendProfile::general_startup;
  program.image = {"synthetic/SEG-007-T029/c1-branch-unretained-target", image, image.size()};
  program.mapping_claims = {{"rom", {{}, 0xF00U}, {{}, 0xF06U}, {0U}, {6U}}};
  program.startup_ingress = segarecomp::M68kStartupIngress{{{}, 0xF00U}, 0x00FF0100U};

  const auto result = segarecomp::analyze_m68k_frontend(program);
  const auto *partial = std::get_if<segarecomp::FrontendPartialProgram>(&result);
  expect(partial != nullptr &&
             partial->frontiers.front().class_ == segarecomp::GenesisFrontierClass::unsupported_cpu_form &&
             partial->frontiers.front().diagnostic.category ==
                 segarecomp::DirectFlowDiagnostic::valid_but_unsupported_instruction &&
             partial->frontiers.front().diagnostic.source_address &&
             partial->frontiers.front().diagnostic.source_address->value == 0xF02U,
         "the diagnosed frontier is still the fallthrough RESET at 0xF02, unchanged by exploring the other arm");
  if (partial == nullptr) return;
  const auto &prefix = partial->accepted_prefix;
  const auto has_block = [&](std::uint32_t entry) {
    return std::any_of(prefix.static_blocks.begin(), prefix.static_blocks.end(),
                        [&](const auto &block) { return block.id.entry.value == entry; });
  };
  expect(prefix.static_blocks.size() == 2U && has_block(0xF00U) && has_block(0xF04U),
         "both the BNE block and its safely-closing taken sibling are retained in the promoted prefix");
}

void general_startup_promotes_nested_conditional_pruning_when_every_sibling_closes_safely() {
  // The outer BNE first discovers its safe fallthrough loop, then reaches a
  // nested BNE whose fallthrough is the CPU frontier. Before SEG-007-T062,
  // the nested BNE's own unexplored taken sibling (0xF28) cascaded pruning
  // all the way back to the outer/startup entry (0xF20), so even the outer
  // BNE's own otherwise-safe fallthrough loop (0xF22) could not survive as
  // an ingress-anchored partial prefix. SEG-007-T062's best-effort sibling
  // exploration (see the walk() comments at its own three call sites) lets
  // the nested BNE's own taken target (0xF28, BRA.s -2) close cleanly too,
  // so nothing needs to cascade: every block (outer BNE, outer fallthrough
  // loop, nested BNE, nested taken loop) is retained, and the single
  // diagnosed frontier is unchanged.
  const std::vector<std::uint8_t> image{
      0x66U, 0x02U,  // 0xF20: BNE.s 0xF24 (nested conditional)
      0x60U, 0xFEU,  // 0xF22: BRA.s 0xF22 (safe outer fallthrough)
      0x66U, 0x02U,  // 0xF24: BNE.s 0xF28 (safe nested taken target)
      0x4EU, 0x70U,  // 0xF26: RESET (nested fallthrough CPU frontier)
      0x60U, 0xFEU,  // 0xF28: BRA.s 0xF28 (safe nested taken target)
  };
  segarecomp::FrontendProgram program{};
  program.profile = segarecomp::M68kFrontendProfile::general_startup;
  program.image = {"synthetic/SEG-007-T029/c1-nested-orphan", image, image.size()};
  program.mapping_claims = {{"rom", {{}, 0xF20U}, {{}, 0xF2AU}, {0U}, {image.size()}}};
  program.startup_ingress = segarecomp::M68kStartupIngress{{{}, 0xF20U}, 0x00FF0100U};

  const auto result = segarecomp::analyze_m68k_frontend(program);
  const auto *partial = std::get_if<segarecomp::FrontendPartialProgram>(&result);
  expect(partial != nullptr &&
             partial->frontiers.front().class_ == segarecomp::GenesisFrontierClass::unsupported_cpu_form &&
             partial->frontiers.front().diagnostic.category ==
                 segarecomp::DirectFlowDiagnostic::valid_but_unsupported_instruction &&
             partial->frontiers.front().diagnostic.source_address &&
             partial->frontiers.front().diagnostic.source_address->value == 0xF26U,
         "the diagnosed frontier is still the nested fallthrough RESET at 0xF26, unchanged by exploring the other "
         "arms");
  if (partial == nullptr) return;
  const auto &prefix = partial->accepted_prefix;
  const auto has_block = [&](std::uint32_t entry) {
    return std::any_of(prefix.static_blocks.begin(), prefix.static_blocks.end(),
                        [&](const auto &block) { return block.id.entry.value == entry; });
  };
  expect(prefix.static_blocks.size() == 4U && has_block(0xF20U) && has_block(0xF22U) && has_block(0xF24U) &&
             has_block(0xF28U),
         "the outer entry, both safe self-loops, and the nested conditional are all retained in the promoted "
         "prefix");
}

void general_startup_promotes_two_branches_to_two_distinct_precise_frontier_classes() {
  // SEG-007-T064 Checkpoint 4: the startup entry's own BNE has a fallthrough
  // arm reaching an unsupported CPU form (RESET) and a taken arm reaching a
  // genuinely different, independently eligible class (an unmapped MOVE.L
  // absolute-long read, unsupported_memory_region) -- both retained as
  // separate exits from the one promoted FrontendPartialProgram, proving
  // multi-exit retention for two distinct precise classes.
  const std::vector<std::uint8_t> image{
      0x66U, 0x04U,                              // 0xF00: BNE.s 0xF06
      0x4EU, 0x70U,                              // 0xF02: RESET (fallthrough CPU frontier)
      0x00U, 0x00U,                              // 0xF04: unreached filler
      0x20U, 0x39U, 0x00U, 0x20U, 0x00U, 0x00U,  // 0xF06: MOVE.L (0x00200000).L,D0 (taken memory frontier)
  };
  segarecomp::FrontendProgram program{};
  program.profile = segarecomp::M68kFrontendProfile::general_startup;
  program.image = {"synthetic/SEG-007-T064/c4-two-precise-exits", image, image.size()};
  program.mapping_claims = {{"rom", {{}, 0xF00U},
                             {{}, static_cast<std::uint32_t>(0xF00U + image.size())}, {0U}, {image.size()}}};
  program.startup_ingress = segarecomp::M68kStartupIngress{{{}, 0xF00U}, 0x00FF0100U};

  const auto result = segarecomp::analyze_m68k_frontend(program);
  const auto *partial = std::get_if<segarecomp::FrontendPartialProgram>(&result);
  expect(partial != nullptr && partial->frontiers.size() == 2U,
         "two distinct precise-class exits are both retained (frontiers.size() == 2)");
  if (partial == nullptr || partial->frontiers.size() != 2U) return;
  const auto &first = partial->frontiers[0];
  const auto &second = partial->frontiers[1];
  expect(first.diagnostic.provenance && first.diagnostic.provenance->source.address.value == 0xF02U &&
             first.class_ == segarecomp::GenesisFrontierClass::unsupported_cpu_form,
         "the sorted-first exit is the lower-address fallthrough CPU frontier at 0xF02");
  expect(second.diagnostic.provenance && second.diagnostic.provenance->source.address.value == 0xF06U &&
             second.class_ == segarecomp::GenesisFrontierClass::unsupported_memory_region && second.access &&
             second.access->address.value == 0x00200000U,
         "the sorted-second exit is the higher-address taken memory frontier at 0xF06");
  expect(partial->accepted_prefix.static_blocks.size() == 1U &&
             partial->accepted_prefix.static_blocks.front().id.entry.value == 0xF00U,
         "the startup entry block itself survives: both its outgoing edges are now represented exits "
         "(SEG-007-T062's own defect class)");

  const auto source_text = expand_entry_rows(segarecomp::emit_m68k_general_startup_runtime_c(*partial));
  expect(source_text.find("static GenesisControlTransfer genesis_frontier_stop_00000F02(GenesisRuntime *runtime)") !=
             std::string::npos,
         "the low-address exit gets its own uniquely named stop function");
  expect(source_text.find("static GenesisControlTransfer genesis_frontier_stop_00000F06(GenesisRuntime *runtime)") !=
             std::string::npos,
         "the high-address exit gets its own uniquely named stop function");
  expect(source_text.find(
             "if (runtime->pc == UINT32_C(0x00000F02)) return genesis_frontier_stop_00000F02(runtime);") !=
             std::string::npos,
         "the block's own tail compares against the fallthrough exit's address");
  expect(source_text.find(
             "if (runtime->pc == UINT32_C(0x00000F06)) return genesis_frontier_stop_00000F06(runtime);") !=
             std::string::npos,
         "the block's own tail compares against the taken exit's address");
  expect(source_text.find("genesis_internal_dispatch_inconsistency_stop(runtime);") != std::string::npos,
         "an unrecognized PC still falls through to the internal dispatch inconsistency stop, unchanged");

  // Determinism: repeated generation from a freshly reanalyzed identical host
  // program is byte-for-byte identical, both in frontiers' own order and the
  // emitted function/comparison-line order.
  const auto second_result = segarecomp::analyze_m68k_frontend(program);
  const auto *second_partial = std::get_if<segarecomp::FrontendPartialProgram>(&second_result);
  expect(second_partial != nullptr && expand_entry_rows(segarecomp::emit_m68k_general_startup_runtime_c(*second_partial)) == source_text,
         "repeated generation of the same fixture is byte-for-byte deterministic");
}

void general_startup_promotes_one_precise_exit_and_one_known_but_unemitted_target_exit() {
  // SEG-007-T064 Checkpoint 4: the taken sibling reaches an ILLEGAL
  // instruction (a fully decoded, fully provenanced, but not-independently-
  // eligible-for-any-precise-class condition -- illegal_instruction is not
  // one of the four precise classes classify_frontier maps), so it is
  // retained as known_but_unemitted_target rather than dropped: the first
  // place in the whole test suite this class is asserted as actually
  // produced end to end, including its literal
  // GENESIS_STOP_KNOWN_BUT_UNEMITTED_TARGET/GENESIS_DIAG_KNOWN_BUT_
  // UNEMITTED_TARGET pair in the emitted C.
  const std::vector<std::uint8_t> image{
      0x66U, 0x04U,  // 0xF00: BNE.s 0xF06
      0x4EU, 0x70U,  // 0xF02: RESET (fallthrough precise CPU frontier)
      0x00U, 0x00U,  // 0xF04: unreached filler
      // SEG-021-T019: ILLEGAL is now the decoded vector-4 exception, so the non-precise exit is a legal TST.B
      // (d8,A6,Xn) whose index word carries the MC68020 full-format bit (an unsupported extension form).
      0x4AU, 0x36U, 0x01U, 0x04U,  // 0xF06: (taken known_but_unemitted_target exit)
  };
  segarecomp::FrontendProgram program{};
  program.profile = segarecomp::M68kFrontendProfile::general_startup;
  program.image = {"synthetic/SEG-007-T064/c4-known-but-unemitted", image, image.size()};
  program.mapping_claims = {{"rom", {{}, 0xF00U},
                             {{}, static_cast<std::uint32_t>(0xF00U + image.size())}, {0U}, {image.size()}}};
  program.startup_ingress = segarecomp::M68kStartupIngress{{{}, 0xF00U}, 0x00FF0100U};

  const auto result = segarecomp::analyze_m68k_frontend(program);
  const auto *partial = std::get_if<segarecomp::FrontendPartialProgram>(&result);
  expect(partial != nullptr && partial->frontiers.size() == 2U,
         "one precise exit and one known_but_unemitted_target exit are both retained");
  if (partial == nullptr || partial->frontiers.size() != 2U) return;
  const auto &precise = partial->frontiers[0];
  const auto &opaque = partial->frontiers[1];
  expect(precise.diagnostic.provenance && precise.diagnostic.provenance->source.address.value == 0xF02U &&
             precise.class_ == segarecomp::GenesisFrontierClass::unsupported_cpu_form,
         "the lower-address exit is the precise CPU-form frontier at 0xF02");
  expect(opaque.diagnostic.provenance && opaque.diagnostic.provenance->source.address.value == 0xF06U &&
             opaque.class_ == segarecomp::GenesisFrontierClass::known_but_unemitted_target &&
             opaque.diagnostic.category == segarecomp::DirectFlowDiagnostic::unsupported_instruction_form && !opaque.access,
         "the higher-address exit is retained as known_but_unemitted_target, its own real (host-side-only) "
         "unsupported_instruction_form category preserved, with no access request");

  const auto source_text = expand_entry_rows(segarecomp::emit_m68k_general_startup_runtime_c(*partial));
  expect(source_text.find("GENESIS_STOP_KNOWN_BUT_UNEMITTED_TARGET") != std::string::npos &&
             source_text.find("GENESIS_DIAG_KNOWN_BUT_UNEMITTED_TARGET") != std::string::npos,
         "the opaque exit's own stop function uses the literal known-but-unemitted stop/diagnostic pair");
  expect(source_text.find("static GenesisControlTransfer genesis_frontier_stop_00000F06(GenesisRuntime *runtime)") !=
             std::string::npos,
         "the opaque exit gets its own uniquely named stop function");
}

void general_startup_reports_opcode_line_for_an_unsupported_cpu_form_exit() {
  // SEG-007-T064 Checkpoint 7 (C1/C3, ADR 0004): a single unsupported_cpu_form
  // exit (a RESET, opcode word 0x4E70, top-4-bit opcode line 0b0100 ==
  // "miscellaneous" -- the standard, publicly documented MC68000 opcode-line
  // grouping for the System Control Group) reports the correct derived
  // opcode_line name. Checkpoint 8 additionally restores this exact raw
  // provenance (source_address/raw_bytes/length) to the same shape
  // format_m68k_frontend_result_legacy's own `rejected` branch has always
  // carried unconditionally for a plain FrontendRejected -- this is no
  // longer a "never appears" case; the exact expected raw values are
  // asserted below.
  const std::vector<std::uint8_t> image{
      0x60U, 0x02U, 0x00U, 0x00U,  // 0x00: BRA.s -> +4
      0x4EU, 0x70U,                // 0x04: RESET (unsupported_cpu_form frontier, word 0x4E70)
  };
  const std::uint32_t begin = 0x00003A00U;
  segarecomp::FrontendProgram program{};
  program.profile = segarecomp::M68kFrontendProfile::general_startup;
  program.image = {"synthetic/SEG-007-T064/c7-opcode-line", image, image.size()};
  program.mapping_claims = {{"rom", {{}, begin}, {{}, begin + static_cast<std::uint32_t>(image.size())}, {0U},
                             {static_cast<std::uint64_t>(image.size())}}};
  program.startup_ingress = segarecomp::M68kStartupIngress{{{}, begin}, 0x00FF0100U};

  const auto result = segarecomp::analyze_m68k_frontend(program);
  const auto *partial = std::get_if<segarecomp::FrontendPartialProgram>(&result);
  expect(partial != nullptr && partial->frontiers.size() == 1U &&
             partial->frontiers.front().class_ == segarecomp::GenesisFrontierClass::unsupported_cpu_form,
         "the single retained exit is the RESET's own unsupported_cpu_form frontier");
  if (partial == nullptr) return;
  const auto json = segarecomp::format_m68k_frontend_result(result);
  expect(json.find("\"opcode_line\":\"miscellaneous\"") != std::string::npos,
         "the sanitized report carries the correct derived opcode_line name for the RESET's own opcode word");
  expect(json.find("\"region_class\"") == std::string::npos,
         "an unsupported_cpu_form exit never carries a region_class key");
  expect(json.find("\"source_address\":\"0x00003A04\"") != std::string::npos,
         "Checkpoint 8: the exact source address is now present, matching the pre-existing rejected-branch shape");
  expect(json.find("\"raw_bytes\":\"4E70\"") != std::string::npos,
         "Checkpoint 8: the exact raw opcode bytes are now present, matching the pre-existing rejected-branch shape");
}

