// SEG-007-T115: the Z80-bus-arbitration counterpart of the VDP store fixture
// above. A direct absolute-operand MOVE.W store into the BUSREQ register
// ($00A11100) is routed through the runtime device gate (genesis_route_access,
// GENESIS_ACCESS_WRITE) -- no compile-time literal, no static Z80/bus model.
// The baked immediate $0100 sets the documented D8 BUSREQ REQUEST bit, so the
// routed store latches devices.z80_bus.{bus_requested,bus_granted}; execution
// then reaches the established RESET frontier.
int emit_general_startup_runtime_c4_z80_bus_store_source() {
  using namespace segarecomp;
  FrontendProgram program{};
  program.profile = M68kFrontendProfile::general_startup;
  // 33 FC 01 00 00 A1 11 00 : MOVE.W #$0100,($00A11100).L ; then RESET.
  program.image = {"synthetic-c4-z80-bus-store",
                    {0x33U, 0xFCU, 0x01U, 0x00U, 0x00U, 0xA1U, 0x11U, 0x00U, 0x4EU, 0x70U}, 10U};
  program.mapping_claims = {{"synthetic-c4-z80-bus-store", {{}, 0xB00U}, {{}, 0xB0AU}, {0U}, {10U}}};
  program.startup_ingress = M68kStartupIngress{{{}, 0xB00U}, 0x00FF0100U};
  const auto result = analyze_m68k_frontend(program);
  const auto *partial = std::get_if<FrontendPartialProgram>(&result);
  if (partial == nullptr) return 1;
  if (partial->accepted_prefix.static_blocks.size() != 1U ||
      partial->accepted_prefix.static_blocks.front().instructions.size() != 1U ||
      partial->accepted_prefix.static_memory_facts.size() != 1U)
    return 1;
  const auto &fact = partial->accepted_prefix.static_memory_facts.front();
  if (fact.role != M68kStaticMemoryFactRole::destination_write ||
      fact.address.value != UINT32_C(0x00A11100) ||
      fact.direction != M68kMemoryAccessDirection::write ||
      fact.region != M68kAbsoluteOperandRegion::routed_device ||
      fact.width != M68kMemoryAccessWidth::word)
    return 1;
  std::cout << emit_m68k_general_startup_runtime_c(*partial);
  return 0;
}

