// SEG-007-T090: the minimal one-instruction-block VDP-window fixture (no BRA
// between the routed TST.W and the frontier RESET), mirroring
// emit_general_startup_runtime_c4_controller_io_minimal_source, so a single
// genesis_bridge_dispatch call runs the routed VDP WORD read and then stops
// at the established RESET frontier.
int emit_general_startup_runtime_c4_vdp_minimal_source() {
  using namespace segarecomp;
  FrontendProgram program{};
  program.profile = M68kFrontendProfile::general_startup;
  program.image = {"synthetic-c4-vdp-minimal",
                    {0x4AU, 0x79U, 0x00U, 0xC0U, 0x00U, 0x04U, 0x4EU, 0x70U}, 8U};
  program.mapping_claims = {{"synthetic-c4-vdp-minimal", {{}, 0xB00U}, {{}, 0xB08U}, {0U}, {8U}}};
  program.startup_ingress = M68kStartupIngress{{{}, 0xB00U}, 0x00FF0100U};
  const auto result = analyze_m68k_frontend(program);
  const auto *partial = std::get_if<FrontendPartialProgram>(&result);
  if (partial == nullptr) return 1;
  if (partial->accepted_prefix.static_blocks.size() != 1U ||
      partial->accepted_prefix.static_blocks.front().instructions.size() != 1U ||
      partial->accepted_prefix.static_memory_facts.size() != 1U ||
      partial->accepted_prefix.static_memory_facts.front().region != M68kAbsoluteOperandRegion::vdp)
    return 1;
  std::cout << emit_m68k_general_startup_runtime_c(*partial);
  return 0;
}

// SEG-007-T113: the write-direction counterpart of the VDP read fixtures
// above. A direct absolute-operand store into the VDP control-port window
// ($00C00004) is routed through the runtime device gate
// (genesis_route_access, GENESIS_ACCESS_WRITE) exactly like the read arm.
// Three variants:
//   "long" -- MOVE.L #imm32,($00C00004).L (10 bytes; exercises the raised
//             route-provenance raw-instruction-bytes capacity end to end),
//   "word" -- MOVE.W #imm16,($00C00004).L (8 bytes),
//   "byte" -- MOVE.B #imm8,($00C00004).L (8 bytes; a fail-closed neighbour:
//             a BYTE VDP-window store is never routed and stays the frontier,
//             so no accepted prefix / no emitted routed store).
int emit_general_startup_runtime_c4_vdp_store_source(std::string_view variant = "long") {
  using namespace segarecomp;
  FrontendProgram program{};
  program.profile = M68kFrontendProfile::general_startup;
  std::vector<std::uint8_t> image;
  std::uint32_t image_end = 0xB00U;
  if (variant == "long") {
    // 23 FC <imm32> 00 C0 00 04 : MOVE.L #0x9F000000,($00C00004).L
    // (a deliberately invalid VDP register-set high word so the routed LONG
    // store fails closed at run time, exercising genesis_attach_route_provenance
    // for the full 10-byte instruction).
    image = {0x23U, 0xFCU, 0x9FU, 0x00U, 0x00U, 0x00U, 0x00U, 0xC0U, 0x00U, 0x04U,
             0x4EU, 0x70U};  // 0xB0A: RESET -- the CPU frontier
    image_end = 0xB0CU;
  } else if (variant == "word") {
    // 33 FC <imm16> 00 C0 00 04 : MOVE.W #0x8004,($00C00004).L
    image = {0x33U, 0xFCU, 0x80U, 0x04U, 0x00U, 0xC0U, 0x00U, 0x04U,
             0x4EU, 0x70U};  // 0xB08: RESET
    image_end = 0xB0AU;
  } else {
    // 13 FC <imm8 as low byte of the ext word> 00 C0 00 04 : MOVE.B #imm,($00C00004).L
    image = {0x13U, 0xFCU, 0x00U, 0x04U, 0x00U, 0xC0U, 0x00U, 0x04U,
             0x4EU, 0x70U};
    image_end = 0xB0AU;
  }
  program.image = {"synthetic-c4-vdp-store", image, image.size()};
  program.mapping_claims = {{"synthetic-c4-vdp-store", {{}, 0xB00U}, {{}, image_end}, {0U},
                            {static_cast<std::uint64_t>(image_end - 0xB00U)}}};
  program.startup_ingress = M68kStartupIngress{{{}, 0xB00U}, 0x00FF0100U};
  const auto result = analyze_m68k_frontend(program);
  const auto *partial = std::get_if<FrontendPartialProgram>(&result);
  if (variant == "byte") {
    // The BYTE store is never routed: it stays an unmapped_data_access
    // frontier, so no `vdp` destination_write fact is ever retained. Emit
    // whatever the analysis yields (a frontier stop or a rejection); the
    // Python driver asserts it carries no routed VDP write.
    if (partial != nullptr)
      for (const auto &fact : partial->accepted_prefix.static_memory_facts)
        if (fact.region == M68kAbsoluteOperandRegion::vdp) return 1;
    if (partial != nullptr) std::cout << emit_m68k_general_startup_runtime_c(*partial);
    else std::cout << "/* byte VDP-window store is a frontier, not a routable prefix */\n";
    return 0;
  }
  if (partial == nullptr) return 1;
  if (partial->accepted_prefix.static_blocks.size() != 1U ||
      partial->accepted_prefix.static_blocks.front().instructions.size() != 1U ||
      partial->accepted_prefix.static_memory_facts.size() != 1U)
    return 1;
  const auto &fact = partial->accepted_prefix.static_memory_facts.front();
  if (fact.role != M68kStaticMemoryFactRole::destination_write ||
      fact.address.value != UINT32_C(0x00C00004) ||
      fact.direction != M68kMemoryAccessDirection::write ||
      fact.region != M68kAbsoluteOperandRegion::vdp ||
      fact.width != (variant == "long" ? M68kMemoryAccessWidth::long_word : M68kMemoryAccessWidth::word))
    return 1;
  std::cout << emit_m68k_general_startup_runtime_c(*partial);
  return 0;
}

// SEG-007-T064 Checkpoint 4: the multi-exit compile-and-run fixture. A BNE
// at the entry has a fallthrough RESET (unsupported_cpu_form) and a taken
// MOVE.L (0x00200000).L,D0 (unsupported_memory_region) -- two independently
// retained, precisely classified exits from one shared block, proving
