  auto program = make_program();
  std::vector<std::uint8_t> bytes(program.image.bytes.begin(), program.image.bytes.end());
  for (std::uint32_t o = 0x10U; o < 0x16U; o += 2U) { bytes[o] = 0x4EU; bytes[o + 1U] = 0x71U; }  // LEA -> NOP;NOP;NOP
  program.image = {"synthetic/SEG-007-T188/indexed-indirect-chain-unproven", bytes, bytes.size()};
  const auto result = analyze_m68k_frontend(program);
