// SEG-007-T189 / ADR-0030 (round 3): the REAL Sonic reconvergence topology,
// reproduced generically. `t189_callee_entry_fixture` matches the
// direct-call-into-ambiguous-callee-entry sub-shape the diagnostic round
// found: the finite caller's `LEA`-proven A3 fact does NOT reach the shared
// `JMP (A3)` site via any caller-side post-return reconvergence at all --
// its own continuation after the `BSR` is an unreachable stop. The shared
// `JMP (A3)` site is instead reached deterministically from INSIDE the body
// of the callee the `BSR` calls directly (through one ordinary internal
// branch, standing in for the real ROM's small inner decode loop). A second
// authoritative caller reaches the SAME shared callee with A3 genuinely
// unknown, established by a memory-load producer (`MOVEA.L (mem).L,A3`) --
// the exact producer CLASS the falsification-gate evidence identified for
// the real caller B (a form ADR-0009's `m68k_apply_finite_value_transfer`
// has never recognized and never will, per this task's Non-goals).
namespace t189_callee_entry_fixture {
using namespace segarecomp;
constexpr std::uint32_t base = 0x00007500U;
constexpr std::uint32_t finite_caller = base + 0x00U;   // LEA final_target,A3 ; BSR shared_callee ; RESET
constexpr std::uint32_t unknown_caller = base + 0x10U;  // MOVEA.L (mem_slot).L,A3 ; BSR shared_callee ; RESET
constexpr std::uint32_t shared_callee = base + 0x20U;   // BRA.S skip ; NOP (dead) ; skip: JMP (A3)
constexpr std::uint32_t finite_target = base + 0x30U;
constexpr std::uint32_t mem_slot = base + 0x40U;        // raw data word, never executed
constexpr std::uint32_t reset = base + 0x50U;

GenesisCodeEntryCandidateHint candidate(std::uint32_t address) {
  return GenesisCodeEntryCandidateHint{address, "test-fixture", "0", "2026-09-08T00:00:00Z", false};
}

void emit_lea_a3(std::vector<std::uint8_t> &b, std::uint32_t abs_address) {
  b.insert(b.end(), {0x47U, 0xF9U, static_cast<std::uint8_t>((abs_address >> 24) & 0xFFU),
                      static_cast<std::uint8_t>((abs_address >> 16) & 0xFFU),
                      static_cast<std::uint8_t>((abs_address >> 8) & 0xFFU),
                      static_cast<std::uint8_t>(abs_address & 0xFFU)});
}

void emit_movea_a3(std::vector<std::uint8_t> &b, std::uint32_t abs_address) {
  // MOVEA.L (abs.L),A3 = 0x2679, followed by the 4-byte absolute source
  // address -- a genuine memory-load An producer, the exact class
  // ADR-0009's finite-register transfer function has never recognized (see
  // `m68k_apply_finite_value_transfer`); it always falls through to "any
  // other write produces unknown".
  b.insert(b.end(), {0x26U, 0x79U, static_cast<std::uint8_t>((abs_address >> 24) & 0xFFU),
                      static_cast<std::uint8_t>((abs_address >> 16) & 0xFFU),
                      static_cast<std::uint8_t>((abs_address >> 8) & 0xFFU),
                      static_cast<std::uint8_t>(abs_address & 0xFFU)});
}

void emit_bsr(std::vector<std::uint8_t> &b, std::uint32_t bsr_address, std::uint32_t target) {
  const auto disp = static_cast<std::uint16_t>(target - (bsr_address + 2U));
  b.insert(b.end(), {0x61U, 0x00U, static_cast<std::uint8_t>((disp >> 8) & 0xFFU),
                      static_cast<std::uint8_t>(disp & 0xFFU)});
}

std::vector<std::uint8_t> make_image() {
  std::vector<std::uint8_t> b;
  auto pad_to = [&](std::size_t off) { while (b.size() < off) { b.push_back(0x4EU); b.push_back(0x71U); } };
  // finite_caller: A3 is proven finite by LEA, then the direct call goes
  // STRAIGHT INTO the shared callee's own entry. This caller's own
  // continuation (the RESET immediately after the BSR) is an unreachable
  // stop -- it never reaches `shared_callee` by any post-return path, so
  // the pre-round-3 continuation-only mechanism cannot resolve this site.
  emit_lea_a3(b, finite_target);                                    // 0x00 LEA final_target,A3
  emit_bsr(b, static_cast<std::uint32_t>(base + b.size()), shared_callee);  // 0x06 BSR.W shared_callee
  b.insert(b.end(), {0x4EU, 0x70U});                                // 0x0A RESET (unreachable continuation)
  pad_to(0x10U);
  // unknown_caller: A3 is loaded from a fixed memory operand immediately
  // before the call -- the exact producer class (memory load) ADR-0009 has
  // never recognized -- then reaches the SAME shared callee directly.
  emit_movea_a3(b, mem_slot);                                       // 0x10 MOVEA.L (mem_slot).L,A3
  emit_bsr(b, static_cast<std::uint32_t>(base + b.size()), shared_callee);  // 0x16 BSR.W shared_callee
  b.insert(b.end(), {0x4EU, 0x70U});                                // 0x1A RESET (unreachable continuation)
  pad_to(0x20U);
  // shared_callee: ordinary internal control flow (one branch, standing in
  // for the real ROM's small inner decode loop) before the shared
  // computed-control site -- reached from BOTH callers' direct-call entry,
  // never via either caller's own post-return continuation.
  b.insert(b.end(), {0x60U, 0x02U});                                // 0x20 BRA.S 0x00007524 (skip)
  b.insert(b.end(), {0x4EU, 0x71U});                                // 0x22 NOP (dead: BRA.S is unconditional)
  b.insert(b.end(), {0x4EU, 0xD3U});                                // 0x24 skip: JMP (A3)
  pad_to(0x30U);
  // finite_target: an offline candidate's own entry must decode as a
  // SUPPORTED instruction (see the identical note in `t189_fixture`).
  b.insert(b.end(), {0x4EU, 0x71U, 0x4EU, 0x70U});
  pad_to(0x40U);
  // mem_slot: raw data, never executed/decoded; its actual value is
  // irrelevant -- ADR-0009 never recognizes a memory-load An producer
  // regardless of the loaded value.
  b.insert(b.end(), {0x00U, 0x00U, 0x00U, 0x00U});
  pad_to(0x50U);
  // reset (unrelated primary ingress): NOP then RESET, so the primary entry
  // itself contributes a non-empty accepted prefix before its own frontier.
  b.insert(b.end(), {0x4EU, 0x71U, 0x4EU, 0x70U});
  return b;
}

FrontendProgram make_program() {
  FrontendProgram program{};
  program.profile = M68kFrontendProfile::general_startup;
  static const std::vector<std::uint8_t> image = make_image();
  program.image = {"synthetic/SEG-007-T189/callee-entry-reconvergence", image, image.size()};
  program.mapping_claims = {
      {"rom", {{}, base}, {{}, static_cast<std::uint32_t>(base + image.size())}, {0U}, {image.size()}}};
  program.startup_ingress = M68kStartupIngress{{{}, reset}, 0x00FF0100U};
  program.external_code_entry_candidates = {candidate(finite_caller), candidate(unknown_caller),
                                            candidate(shared_callee), candidate(finite_target)};
  return program;
}
}  // namespace t189_callee_entry_fixture

// Positive: the callee-entry-seeded context resolves the shared site to
// exactly the finite caller's own proven target, despite the co-located
// genuinely-unknown caller's own memory-load-sourced A3 reaching the SAME
// callee entry -- and despite NEITHER caller reaching the site via any
// post-return reconvergence (proving this is genuinely the dual-seed-point
// correction at work, not the pre-existing continuation-seeded mechanism).
void t189_callee_entry_seeded_context_resolves_direct_call_into_ambiguous_callee() {
  using namespace segarecomp;
  using namespace t189_callee_entry_fixture;
  const auto result = analyze_m68k_frontend(make_program());
  const auto *partial = std::get_if<FrontendPartialProgram>(&result);
  expect(partial != nullptr, "the callee-entry-reconvergence fixture reaches a represented partial prefix");
  if (partial == nullptr) return;
  const auto &prefix = partial->accepted_prefix;
  const auto *fact = t189_fixture::fact_at(prefix, shared_callee + 0x04U);
  expect(fact != nullptr && fact->candidates.size() == 1U && fact->candidates.front().value == finite_target,
         "the callee-entry-seeded finite context's independently-validated target set is retained at the shared "
         "site reached directly from the callee's own entry, despite the co-located genuinely-unknown "
         "memory-load caller context reaching the identical callee entry");
  expect(std::any_of(prefix.static_edges.begin(), prefix.static_edges.end(), [](const M68kStaticEdge &edge) {
           return edge.kind == M68kStaticEdgeKind::indirect_branch &&
                  edge.source_instruction.source.address.value == shared_callee + 0x04U &&
                  edge.target.value == finite_target;
         }),
         "the retained target feeds the existing indirect_branch edge ownership path unchanged");
  const auto shared_block_count =
      std::count_if(prefix.static_blocks.begin(), prefix.static_blocks.end(),
                    [](const M68kStaticBlock &block) { return block.id.entry.value == shared_callee; });
  expect(shared_block_count == 1U,
         "exactly one emitted block exists for the shared callee's entry address -- the context dimension is "
         "fully consumed (unioned away) before any block/edge/emission decision, so no context-duplicated "
         "emitted block is ever produced");
}

// Negative: when the finite caller's own LEA producer is removed (replaced
// with NOPs of the same length), NEITHER caller supplies a supported finite
// An producer, so the shared site stays unknown exactly as before this
// round -- proving the callee-entry seed point never fabricates a finite
// proof from two genuine unknowns, and that the genuinely-unknown caller's
// own memory-load path never itself contributes a target.
void t189_callee_entry_both_contexts_unknown_stays_unknown() {
  using namespace segarecomp;
  using namespace t189_callee_entry_fixture;
  auto program = make_program();
  std::vector<std::uint8_t> bytes(program.image.bytes.begin(), program.image.bytes.end());
  // Replace the LEA at finite_caller with three NOPs (same length), leaving
  // A3 untouched on both reaching paths.
  bytes[0x00U] = 0x4EU; bytes[0x01U] = 0x71U;
  bytes[0x02U] = 0x4EU; bytes[0x03U] = 0x71U;
  bytes[0x04U] = 0x4EU; bytes[0x05U] = 0x71U;
  program.image = {"synthetic/SEG-007-T189/callee-entry-both-unknown", bytes, bytes.size()};
  const auto result = analyze_m68k_frontend(program);
  const auto *partial = std::get_if<FrontendPartialProgram>(&result);
  expect(partial != nullptr, "the both-unknown callee-entry variant still reaches a represented partial prefix");
  if (partial == nullptr) return;
  const auto &prefix = partial->accepted_prefix;
  expect(t189_fixture::fact_at(prefix, shared_callee + 0x04U) == nullptr,
         "genuine unknown on every authoritative context (including via the callee-entry seed point) never "
         "fabricates a finite target-EA-set");
  expect(std::any_of(prefix.unproven_indirect_control_ea_sets.begin(),
                     prefix.unproven_indirect_control_ea_sets.end(),
                     [](const M68kUnprovenIndirectControlEaSet &set) {
                       return set.source_instruction.source.address.value == shared_callee + 0x04U;
                     }),
         "the weaker Tier-2-eligible fact is still recorded for the genuinely unresolved site (unchanged)");
}

// SEG-007-T190 / ADR-0031: close late Tier-1 computed-JMP target
// representation (Stage A) and return-edge retention (Stage B) as one bounded
// monotone fixed point. Generic, non-Sonic-specific synthetic fixtures.
namespace t190_late_indirect_closure {
using namespace segarecomp;

GenesisCodeEntryCandidateHint hint(std::uint32_t address) {
  return GenesisCodeEntryCandidateHint{address, "test-fixture", "0", "2026-09-09T00:00:00Z", false};
}

FrontendProgram make_program(const char *name, const std::vector<std::uint8_t> &image, std::uint32_t base,
                             std::uint32_t entry, std::vector<GenesisCodeEntryCandidateHint> candidates) {
  FrontendProgram program{};
  program.profile = M68kFrontendProfile::general_startup;
  program.image = {name, image, image.size()};
  program.mapping_claims = {
      {"rom", {{}, base}, {{}, static_cast<std::uint32_t>(base + image.size())}, {0U}, {image.size()}}};
  program.startup_ingress = M68kStartupIngress{{{}, entry}, 0x00FF0100U};
  program.external_code_entry_candidates = std::move(candidates);
  return program;
}

void put(std::vector<std::uint8_t> &b, std::size_t at, std::initializer_list<std::uint8_t> bytes) {
  if (b.size() < at + bytes.size()) b.resize(at + bytes.size(), 0x71U);
  std::size_t i = at;
  for (const auto byte : bytes) b[i++] = byte;
}
void put_abs(std::vector<std::uint8_t> &b, std::size_t at, std::uint8_t op0, std::uint8_t op1,
             std::uint32_t addr) {
  put(b, at, {op0, op1, static_cast<std::uint8_t>(addr >> 24), static_cast<std::uint8_t>(addr >> 16),
              static_cast<std::uint8_t>(addr >> 8), static_cast<std::uint8_t>(addr)});
}

// The route may fully accept (`FrontendAnalysis`) or stop at a frontier
// (`FrontendPartialProgram`); both carry the same static facts.
const FrontendAnalysis *prefix_of(const FrontendResult &result) {
  if (const auto *a = std::get_if<FrontendAnalysis>(&result)) return a;
  if (const auto *p = std::get_if<FrontendPartialProgram>(&result)) return &p->accepted_prefix;
  return nullptr;
}
const M68kStaticEdge *find_edge(const FrontendAnalysis &prefix, M68kStaticEdgeKind kind,
                                std::uint32_t source_address) {
  for (const auto &edge : prefix.static_edges)
    if (edge.kind == kind && edge.source_instruction.source.address.value == source_address) return &edge;
  return nullptr;
}
std::size_t count_blocks_at(const FrontendAnalysis &prefix, std::uint32_t entry) {
  return static_cast<std::size_t>(std::count_if(
      prefix.static_blocks.begin(), prefix.static_blocks.end(),
      [&](const M68kStaticBlock &block) { return block.id.entry.value == entry; }));
}

// Fixture 1 (purely-additive + Stage B mechanism, direct unit level): every
// existing `m68k_reachable_return_edges` call site that omits the new optional
// parameter is byte-identical to before; supplying an accepted Tier-1 set for
// a computed JMP source address additionally yields the reachable RTS's
// `return_to_continuation` edge under the enclosing frame identity.
void purely_additive_and_stage_b_reachable_return_edge() {
  const std::uint32_t jmp_addr = 0x1000U, rts_addr = 0x1200U, cont_addr = 0x100CU, caller_addr = 0x1006U;
  const std::vector<std::uint8_t> jmp_bytes{0x4EU, 0xD0U};
  const std::vector<std::uint8_t> rts_bytes{0x4EU, 0x75U};
  const auto jmp_v = decode_m68k_instruction(jmp_bytes, source(jmp_addr), M68kDecodeProfile::general_startup);
  const auto rts_v = decode_m68k_instruction(rts_bytes, source(rts_addr), M68kDecodeProfile::general_startup);
  const auto *jmp = std::get_if<M68kDecodedInstruction>(&jmp_v);
  const auto *rts = std::get_if<M68kDecodedInstruction>(&rts_v);
  expect(jmp != nullptr && rts != nullptr && jmp->kind == M68kInstructionKind::jmp &&
             rts->kind == M68kInstructionKind::rts,
         "the micro fixture decodes a JMP (A0) and an RTS");
  if (jmp == nullptr || rts == nullptr) return;
  std::map<std::uint32_t, M68kDecodedInstruction> decoded{{jmp_addr, *jmp}, {rts_addr, *rts}};
  M68kStaticFrame frame{};
  frame.call.caller = jmp->provenance;
  frame.call.caller.source.address.value = caller_addr;
  frame.call.continuation = {TargetAddressSpace::m68k_program, cont_addr};
  frame.call.callee = {TargetAddressSpace::m68k_program, jmp_addr};

  const auto without_param = m68k_reachable_return_edges(decoded, {frame});
  const auto with_empty = m68k_reachable_return_edges(decoded, {frame}, {});
  expect(without_param.empty() && with_empty.empty(),
         "omitting the new parameter (or passing an empty map) leaves an unproven computed JMP with no "
         "reachable-return successor, byte-identical to before this change");

  M68kIndirectTargetEaSet accepted_set{};
  accepted_set.source_instruction = jmp->provenance;
  accepted_set.candidates = {{TargetAddressSpace::m68k_program, rts_addr}};
  const std::map<std::uint32_t, M68kIndirectTargetEaSet> accepted{{jmp_addr, accepted_set}};
  const auto with_tier1 = m68k_reachable_return_edges(decoded, {frame}, accepted);
  expect(with_tier1.size() == 1U && with_tier1.front().kind == M68kStaticEdgeKind::return_to_continuation &&
             with_tier1.front().source_instruction.source.address.value == rts_addr &&
             with_tier1.front().target.value == cont_addr && with_tier1.front().call.has_value() &&
             with_tier1.front().call->callee.value == jmp_addr &&
             with_tier1.front().call->continuation.value == cont_addr,
         "an accepted Tier-1 set for the JMP source yields the reachable RTS's return_to_continuation edge "
         "under the original enclosing (caller, callee, continuation) frame");
  const auto repeat = m68k_reachable_return_edges(decoded, {frame}, accepted);
  expect(repeat.size() == with_tier1.size(), "the Tier-1-aware trace is deterministic across repeated calls");
}

// Fixture 2 (required end-to-end late-representation shape). The computed-JMP
// source is initially represented; its finite An target is NOT an external
// candidate/root; the only static path to the target is the Tier-1-proven
// JMP; the target flows to an RTS of the original enclosing direct-call frame.
std::vector<std::uint8_t> end_to_end_image() {
  std::vector<std::uint8_t> b;
  put_abs(b, 0x00U, 0x41U, 0xF9U, 0x00008200U);  // 0x8000 LEA (0x00008200).L,A0
  put_abs(b, 0x06U, 0x4EU, 0xB9U, 0x00008100U);  // 0x8006 JSR (0x00008100).L   cont=0x800C
  put(b, 0x0CU, {0x4EU, 0x70U});                  // 0x800C continuation: RESET frontier
  put(b, 0x100U, {0x4EU, 0xD0U});                 // 0x8100 callee: JMP (A0)
  put(b, 0x200U, {0x4EU, 0x75U});                 // 0x8200 target: RTS
  put(b, 0x204U, {0x00U, 0x00U});                 // pad
  return b;
}
void end_to_end_late_target_representation_and_return_edge() {
  const std::uint32_t base = 0x8000U;
  const auto image = end_to_end_image();
  const auto program = make_program("synthetic/SEG-007-T190/end-to-end", image, base, base, {hint(0x8100U)});
  const auto result = analyze_m68k_frontend(program);
  const auto *prefix_p = prefix_of(result);
  expect(prefix_p != nullptr, "the end-to-end fixture reaches a represented prefix");
  if (prefix_p == nullptr) return;
  const auto &prefix = *prefix_p;
  const auto &m = prefix.offline_inventory_stitch_metrics;

  const auto fact = std::find_if(prefix.indirect_target_ea_sets.begin(), prefix.indirect_target_ea_sets.end(),
                                 [](const M68kIndirectTargetEaSet &set) {
                                   return set.source_instruction.source.address.value == 0x8100U;
                                 });
  expect(fact != prefix.indirect_target_ea_sets.end() && fact->candidates.size() == 1U &&
             fact->candidates.front().value == 0x8200U,
         "finite-An proof -> Stage A representation -> unweakened acceptance: the late target is accepted");
  expect(find_edge(prefix, M68kStaticEdgeKind::indirect_branch, 0x8100U) != nullptr,
         "the accepted late target owns its ordinary indirect_branch edge");
  const auto *ret = find_edge(prefix, M68kStaticEdgeKind::return_to_continuation, 0x8200U);
  expect(ret != nullptr && ret->target.value == 0x800CU && ret->call.has_value() &&
             ret->call->callee.value == 0x8100U && ret->call->caller.source.address.value == 0x8006U &&
             ret->call->continuation.value == 0x800CU,
         "Stage B synthesizes the target RTS's return_to_continuation edge to the original caller continuation, "
         "under the original enclosing frame identity (no fabricated frame for the Tier-1 target)");
  expect(std::none_of(prefix.static_frames.begin(), prefix.static_frames.end(),
                      [](const M68kStaticFrame &f) { return f.call.callee.value == 0x8200U; }),
         "no call frame is fabricated for the Tier-1 target itself");
  expect(count_blocks_at(prefix, 0x8200U) == 1U, "exactly one emitted block identity per PC for the target");
  expect(m.late_indirect_target_unit_count == 1U && m.late_indirect_closure_converged &&
             m.late_indirect_closure_rounds == 3U,
         "the bounded closure represented one late unit, then committed it on the following graph-stable round, "
         "then revalidated it against the edge-expanded graph and converged (represent / stable-commit / "
         "revalidate-and-converge)");
  const auto *pp = std::get_if<FrontendPartialProgram>(&result);
  expect(pp != nullptr, "the frontier at the RESET continuation yields a partial program");
  if (pp == nullptr) return;
  const auto first = expand_entry_rows(emit_m68k_general_startup_bridge_c(*pp, std::string(64U, 'a')));
  const auto again = expand_entry_rows(emit_m68k_general_startup_bridge_c(*pp, std::string(64U, 'a')));
  expect(first == again && !first.starts_with("/* translation rejected:") &&
             first.find("m68k_indirect_targets_00008100") != std::string::npos,
         "generated dispatch now deterministically contains the previously-missing late-proven target path");
  const auto second_run = analyze_m68k_frontend(program);
  const auto *second = std::get_if<FrontendPartialProgram>(&second_run);
  expect(second != nullptr && expand_entry_rows(emit_m68k_general_startup_bridge_c(*second, std::string(64U, 'a'))) == first,
         "repeated analysis of the identical input emits byte-identical generated C");
}

// Fixture 3 (negative: unproven computed JMP). Same topology, no finite An
// producer -> no Tier-1 proof -> neither Stage A nor Stage B activates.
void negative_unproven_computed_jmp_activates_nothing() {
  const std::uint32_t base = 0x8000U;
  auto image = end_to_end_image();
  put(image, 0x00U, {0x4EU, 0x71U, 0x4EU, 0x71U, 0x4EU, 0x71U});  // replace the LEA with 3x NOP: A0 stays unknown
  const auto program = make_program("synthetic/SEG-007-T190/negative-unproven", image, base, base, {hint(0x8100U)});
  const auto result = analyze_m68k_frontend(program);
  const auto *prefix_p = prefix_of(result);
  expect(prefix_p != nullptr, "the unproven negative fixture still reaches a represented prefix");
  if (prefix_p == nullptr) return;
  const auto &prefix = *prefix_p;
  expect(std::none_of(prefix.indirect_target_ea_sets.begin(), prefix.indirect_target_ea_sets.end(),
                      [](const M68kIndirectTargetEaSet &set) {
                        return set.source_instruction.source.address.value == 0x8100U;
                      }),
         "no Tier-1 target set is accepted for a genuinely unproven computed JMP");
  expect(find_edge(prefix, M68kStaticEdgeKind::indirect_branch, 0x8100U) == nullptr &&
             find_edge(prefix, M68kStaticEdgeKind::return_to_continuation, 0x8200U) == nullptr,
         "neither an indirect_branch nor a return_to_continuation edge is fabricated");
  expect(prefix.offline_inventory_stitch_metrics.late_indirect_target_unit_count == 0U &&
             prefix.offline_inventory_stitch_metrics.late_indirect_closure_converged,
         "the closure represents nothing and converges immediately; fail-closed pruning is unchanged");
  expect(std::any_of(prefix.unproven_indirect_control_ea_sets.begin(),
                     prefix.unproven_indirect_control_ea_sets.end(),
                     [](const M68kUnprovenIndirectControlEaSet &set) {
                       return set.source_instruction.source.address.value == 0x8100U;
                     }),
         "the weaker Tier-2-eligible fact for the unresolved site is unchanged");
}

// Fixture 4 (call-ownership): two distinct callers/frames reach the shared
// callee whose computed JMP resolves to one shared target RTS; each
// synthesized return edge keeps its own exact (caller, callee, continuation).
void call_ownership_two_frames_keep_distinct_return_edges() {
  const std::uint32_t base = 0x8000U;
  std::vector<std::uint8_t> b;
  put(b, 0x00U, {0x66U, 0x0EU});                  // 0x8000 entry: BNE.S -> 0x8010 (caller B); fallthrough = caller A
  put_abs(b, 0x02U, 0x41U, 0xF9U, 0x00008300U);  // 0x8002 caller A: LEA target,A0
  put_abs(b, 0x08U, 0x4EU, 0xB9U, 0x00008200U);  // 0x8008 JSR callee   contA=0x800E
  put(b, 0x0EU, {0x4EU, 0x70U});                  // 0x800E contA: RESET frontier
  put_abs(b, 0x10U, 0x41U, 0xF9U, 0x00008300U);  // 0x8010 caller B: LEA target,A0
  put_abs(b, 0x16U, 0x4EU, 0xB9U, 0x00008200U);  // 0x8016 JSR callee   contB=0x801C
  put(b, 0x1CU, {0x4EU, 0x70U});                  // 0x801C contB: RESET frontier
  put(b, 0x200U, {0x4EU, 0xD0U});                 // 0x8200 callee: JMP (A0)
  put(b, 0x300U, {0x4EU, 0x75U});                 // 0x8300 target: RTS
  put(b, 0x304U, {0x00U, 0x00U});
  const auto program = make_program("synthetic/SEG-007-T190/call-ownership", b, base, base, {hint(0x8200U)});
  const auto result = analyze_m68k_frontend(program);
  const auto *prefix_p = prefix_of(result);
  expect(prefix_p != nullptr, "the call-ownership fixture reaches a represented prefix");
  if (prefix_p == nullptr) return;
  std::vector<std::pair<std::uint32_t, std::uint32_t>> return_frames;  // (caller, continuation)
  for (const auto &edge : prefix_p->static_edges)
    if (edge.kind == M68kStaticEdgeKind::return_to_continuation &&
        edge.source_instruction.source.address.value == 0x8300U && edge.call.has_value())
      return_frames.emplace_back(edge.call->caller.source.address.value, edge.call->continuation.value);
  std::sort(return_frames.begin(), return_frames.end());
  expect(return_frames.size() == 2U &&
             return_frames[0] == std::make_pair<std::uint32_t, std::uint32_t>(0x8008U, 0x800EU) &&
             return_frames[1] == std::make_pair<std::uint32_t, std::uint32_t>(0x8016U, 0x801CU),
         "each caller's frame keeps its own exact (caller, callee, continuation) return edge -- no cross-call "
         "contamination");
  for (const auto &edge : prefix_p->static_edges)
    if (edge.kind == M68kStaticEdgeKind::return_to_continuation && edge.call.has_value())
      expect(edge.call->callee.value == 0x8200U, "both return edges share the one real callee, never the target");
}

// Fixture 5 (nested call): the original callee reaches an ordinary nested JSR
// around the proven computed-jump path; the nested call stays its own frame.
void nested_call_keeps_its_own_distinct_frame() {
  const std::uint32_t base = 0x8000U;
  std::vector<std::uint8_t> b;
  put_abs(b, 0x00U, 0x41U, 0xF9U, 0x00008400U);  // 0x8000 caller: LEA target,A0
  put_abs(b, 0x06U, 0x4EU, 0xB9U, 0x00008200U);  // 0x8006 JSR outer   cont=0x800C
  put(b, 0x0CU, {0x4EU, 0x70U});                  // 0x800C cont: RESET frontier
  put_abs(b, 0x200U, 0x4EU, 0xB9U, 0x00008300U); // 0x8200 outer: JSR inner   cont=0x8206
  put(b, 0x206U, {0x4EU, 0xD0U});                 // 0x8206 outer: JMP (A0)
  put(b, 0x300U, {0x4EU, 0x75U});                 // 0x8300 inner: RTS
  put(b, 0x400U, {0x4EU, 0x75U});                 // 0x8400 target: RTS
  put(b, 0x404U, {0x00U, 0x00U});
  const auto program = make_program("synthetic/SEG-007-T190/nested", b, base, base,
                                    {hint(0x8200U), hint(0x8300U)});
  const auto result = analyze_m68k_frontend(program);
  const auto *prefix_p = prefix_of(result);
  expect(prefix_p != nullptr, "the nested-call fixture reaches a represented prefix");
  if (prefix_p == nullptr) return;
  const auto *inner = find_edge(*prefix_p, M68kStaticEdgeKind::return_to_continuation, 0x8300U);
  expect(inner != nullptr && inner->call.has_value() && inner->call->callee.value == 0x8300U &&
             inner->call->caller.source.address.value == 0x8200U && inner->call->continuation.value == 0x8206U,
         "the ordinary nested JSR/RTS keeps its own distinct (caller, callee, continuation) frame unchanged");
  const auto *outer = find_edge(*prefix_p, M68kStaticEdgeKind::return_to_continuation, 0x8400U);
  expect(outer != nullptr && outer->call.has_value() && outer->call->callee.value == 0x8200U &&
             outer->call->continuation.value == 0x800CU,
         "the Tier-1 target RTS returns under the OUTER enclosing frame, not the nested one");
  expect(std::none_of(prefix_p->static_frames.begin(),
                      prefix_p->static_frames.end(),
                      [](const M68kStaticFrame &f) { return f.call.callee.value == 0x8400U; }),
         "still no fabricated frame for the Tier-1 target");
}

// Chain builder for the fixed-point fixtures: N levels of
// {Pk: LEA L(k+1),A0 ; JMP Jk.L}  ->  {Jk: JMP (A0)}. Every Jk (the computed
// JMP unit) and P1 are external candidates, so each Jk is its own stitched
// unit boundary and no single unit's local ADR-0009 pass ever sees a producer
// and a JMP (An) together. P2..PN and the terminal are reachable ONLY via the
// previous level's Tier-1 resolution, so level k's finite-An proof genuinely
// succeeds only after round k-1 represents P(k) -- forcing a real fixed point.
std::vector<GenesisCodeEntryCandidateHint> chain_candidates(std::uint32_t base, unsigned levels) {
  std::vector<GenesisCodeEntryCandidateHint> c{hint(base)};
  for (unsigned k = 1; k <= levels; ++k) c.push_back(hint(base + (k - 1U) * 0x20U + 0x10U));
  return c;
}
std::vector<std::uint8_t> chain_image(std::uint32_t base, unsigned levels) {
  std::vector<std::uint8_t> b;
  const std::uint32_t terminal = base + levels * 0x20U;
  for (unsigned k = 1; k <= levels; ++k) {
    const std::uint32_t pk = base + (k - 1U) * 0x20U;
    const std::uint32_t jk = pk + 0x10U;
    const std::uint32_t next = (k == levels) ? terminal : (base + k * 0x20U);
    put_abs(b, pk - base, 0x41U, 0xF9U, next);          // Pk: LEA next.L,A0
    put_abs(b, pk - base + 6U, 0x4EU, 0xF9U, jk);       // Pk: JMP Jk.L
    put(b, jk - base, {0x4EU, 0xD0U});                  // Jk: JMP (A0)
  }
  const std::size_t t = terminal - base;
  put(b, t, {0x60U, 0x02U});                            // terminal: BRA.S +2 -> frontier
  put(b, t + 2U, {0x4EU, 0x71U});
  put(b, t + 4U, {0x4EU, 0x70U});                       // RESET frontier
  put(b, t + 6U, {0x00U, 0x00U});
  return b;
}

// Fixture 6 (fixed-point iteration): a two-level chain genuinely needs more
// than one round and converges to include the second-round target.
void fixed_point_iteration_needs_more_than_one_round_and_converges() {
  const std::uint32_t base = 0x9000U;
  const auto image = chain_image(base, 2U);
  const auto program = make_program("synthetic/SEG-007-T190/chain-2", image, base, base, chain_candidates(base, 2U));
  const auto result = analyze_m68k_frontend(program);
  const auto *prefix_p = prefix_of(result);
  expect(prefix_p != nullptr, "the 2-level chain converges to a represented prefix");
  if (prefix_p == nullptr) return;
  const auto &prefix = *prefix_p;
  const auto &m = prefix.offline_inventory_stitch_metrics;
  const auto has_set = [&](std::uint32_t src, std::uint32_t cand) {
    return std::any_of(prefix.indirect_target_ea_sets.begin(), prefix.indirect_target_ea_sets.end(),
                       [&](const M68kIndirectTargetEaSet &set) {
                         return set.source_instruction.source.address.value == src &&
                                set.candidates.size() == 1U && set.candidates.front().value == cand;
                       });
  };
  expect(has_set(base + 0x10U, base + 0x20U) && has_set(base + 0x30U, base + 0x40U),
         "round 1 resolves J1 -> P2; only after P2 is represented does round 2 resolve J2 -> the terminal");
  expect(m.late_indirect_closure_converged && m.late_indirect_closure_rounds == 4U &&
             m.late_indirect_target_unit_count >= 2U,
         "the closure required >1 representing round, committed both levels on the first graph-stable round, then "
         "revalidated and converged within the ceiling (represent P2 / represent terminal / stable-commit / "
         "revalidate-and-converge)");
  const auto again = analyze_m68k_frontend(program);
  const auto *pp1 = std::get_if<FrontendPartialProgram>(&result);
  const auto *pp2 = std::get_if<FrontendPartialProgram>(&again);
  expect(pp1 != nullptr && pp2 != nullptr &&
             expand_entry_rows(emit_m68k_general_startup_bridge_c(*pp2, std::string(64U, 'a'))) ==
                 expand_entry_rows(emit_m68k_general_startup_bridge_c(*pp1, std::string(64U, 'a'))),
         "the multi-round closure is byte-identical across repeated runs");
}

// Fixture 7 (ceiling exhaustion): an 8-level chain needs 9 rounds > the
// ceiling of 8, so the whole build fails closed (bounded diagnostic frontier)
// rather than looping, crashing, or silently dropping a sound candidate.
void ceiling_exhaustion_fails_closed() {
  const std::uint32_t base = 0xA000U;
  const auto image = chain_image(base, 8U);
  const auto program = make_program("synthetic/SEG-007-T190/chain-8", image, base, base, chain_candidates(base, 8U));
  const auto result = analyze_m68k_frontend(program);
  const auto *rejected = std::get_if<FrontendRejected>(&result);
  expect(rejected != nullptr && rejected->category == DirectFlowDiagnostic::discovery_budget_exhausted,
         "a chain that needs more rounds than the ADR-0031 ceiling fails the build closed, never loops/crashes");
  const auto again = analyze_m68k_frontend(program);
  expect(std::holds_alternative<FrontendRejected>(again),
         "the fail-closed ceiling-exhaustion outcome is deterministic");
}

// Fixture A (pre-merge soundness correction: stale proof widens to unknown).
// Round layout:
//   P1  0xB000  LEA T1,A0 ; LEA T2,A1 ; JSR C   (cont K = RESET frontier)
//   C   0xB040  J1: JMP (A0)                    (external candidate)
//   T1  0xB060  J2: JMP (A1)   -- represented only via J1's Tier-1 proof
//   T2  0xB080  MOVEA.L D0,A0 (A0 <- unknown) ; BRA J1
// While T1 is a disconnected root its A1 is unknown, so J2 does not resolve and
// T1's onward flow is empty; round 2 is graph-stable and COMMITS J1 -> {T1}.
// Committing adds the indirect_branch edge J1 -> T1, which makes T1 reachable
// from J1's finite outflow (A1 = T2); round 3 then resolves J2 -> T2 and
// represents T2. Round 4 analyses T2 as a fresh disconnected root: it writes A0
// to unknown and branches back to J1, so the fresh proof over the expanded
// graph no longer proves any finite An for J1. The committed relation is
// revalidated at the top of round 4, found to have disappeared, and the whole
// build fails closed (startup_graph_mismatch) instead of silently retaining the
// stale J1 -> {T1} target set / its indirect_branch edge / any Stage B edge.
std::vector<std::uint8_t> stale_widen_image() {
  std::vector<std::uint8_t> b;
  put_abs(b, 0x000U, 0x41U, 0xF9U, 0x0000B060U);  // 0xB000 P1: LEA T1,A0
  put_abs(b, 0x006U, 0x43U, 0xF9U, 0x0000B080U);  // 0xB006 P1: LEA T2,A1
  put_abs(b, 0x00CU, 0x4EU, 0xB9U, 0x0000B040U);  // 0xB00C JSR C           cont=0xB012
  put(b, 0x012U, {0x4EU, 0x70U});                 // 0xB012 K: RESET frontier
  put(b, 0x040U, {0x4EU, 0xD0U});                 // 0xB040 C/J1: JMP (A0)
  put(b, 0x060U, {0x4EU, 0xD1U});                 // 0xB060 T1/J2: JMP (A1)
  put(b, 0x080U, {0x20U, 0x40U});                 // 0xB080 T2: MOVEA.L D0,A0 (A0 <- unknown)
  put(b, 0x082U, {0x60U, 0x00U, 0xFFU, 0xBCU});   // 0xB082 T2: BRA.W J1 (0xB040)
  put(b, 0x086U, {0x00U, 0x00U});
  return b;
}
void stale_proof_widens_to_unknown_fails_closed() {
  const std::uint32_t base = 0xB000U;
  const auto image = stale_widen_image();
  const auto program = make_program("synthetic/SEG-007-T190/stale-widen", image, base, base, {hint(0xB040U)});
  const auto result = analyze_m68k_frontend(program);
  const auto *rej = std::get_if<FrontendRejected>(&result);
  expect(rej != nullptr && rej->category == DirectFlowDiagnostic::startup_graph_mismatch,
         "a later graph expansion that widens an already-committed Tier-1 finite An proof to unknown fails the "
         "build closed (startup_graph_mismatch), never silently retains the stale target set");
  if (const auto *prefix_p = prefix_of(result); prefix_p != nullptr) {
    expect(std::none_of(prefix_p->indirect_target_ea_sets.begin(), prefix_p->indirect_target_ea_sets.end(),
                        [](const M68kIndirectTargetEaSet &set) {
                          return set.source_instruction.source.address.value == 0xB040U;
                        }),
           "no stale Tier-1 target set for the computed JMP survives the fail-closed outcome");
  }
  const auto again = analyze_m68k_frontend(program);
  const auto *rej2 = std::get_if<FrontendRejected>(&again);
  expect(rej2 != nullptr && rej2->category == DirectFlowDiagnostic::startup_graph_mismatch,
         "the stale-invalidation fail-closed outcome is deterministic across repeated analysis");
}

// Fixture B (pre-merge soundness correction: stale proof changes the finite
// set). Same seam, but the later-represented target contributes an ADDITIONAL
// finite An value rather than widening fully to unknown:
//   P1  0xC000  LEA Ta,A0 ; JSR J1     (cont K = RESET frontier)
//   J1  0xC040  JMP (A0)               (external candidate)
//   Ta  0xC060  LEA Tb,A0 ; BRA J1     -- represented only via J1's Tier-1 proof
//   Tb  0xC080  BRA.S frontier
// Once Ta is a disconnected root its body already contributes A0 = Tb back into
// J1, so the FRESH proof over the graph that also contains Ta proves
// J1 -> {Ta, Tb}. The closure never commits the pre-expansion J1 -> {Ta} set:
// it either commits the complete post-expansion {Ta, Tb} set on a stable round
// or fails closed. It must not emit an indirect_branch edge for the incomplete
// {Ta}-only set.
std::vector<std::uint8_t> stale_grow_image() {
  std::vector<std::uint8_t> b;
  put_abs(b, 0x000U, 0x41U, 0xF9U, 0x0000C060U);  // 0xC000 P1: LEA Ta,A0
  put_abs(b, 0x006U, 0x4EU, 0xB9U, 0x0000C040U);  // 0xC006 JSR J1           cont=0xC00C
  put(b, 0x00CU, {0x4EU, 0x70U});                 // 0xC00C K: RESET frontier
  put(b, 0x040U, {0x4EU, 0xD0U});                 // 0xC040 J1: JMP (A0)
  put_abs(b, 0x060U, 0x41U, 0xF9U, 0x0000C080U);  // 0xC060 Ta: LEA Tb,A0
  put(b, 0x066U, {0x60U, 0x00U, 0xFFU, 0xD8U});   // 0xC066 Ta: BRA.W J1 (0xC040)
  put(b, 0x080U, {0x60U, 0x02U});                 // 0xC080 Tb: BRA.S 0xC084
  put(b, 0x082U, {0x4EU, 0x71U});                 // 0xC082 NOP
  put(b, 0x084U, {0x4EU, 0x70U});                 // 0xC084 RESET frontier
  put(b, 0x086U, {0x00U, 0x00U});
  return b;
}
void stale_proof_changes_finite_set_never_emits_pre_expansion_set() {
  const std::uint32_t base = 0xC000U;
  const auto image = stale_grow_image();
  const auto program = make_program("synthetic/SEG-007-T190/stale-grow", image, base, base, {hint(0xC040U)});
  const auto result = analyze_m68k_frontend(program);
  if (const auto *rej = std::get_if<FrontendRejected>(&result); rej != nullptr) {
    expect(rej->category == DirectFlowDiagnostic::startup_graph_mismatch,
           "if the growing finite set is not committed on a stable graph the closure fails closed, never emits the "
           "pre-expansion set");
    return;
  }
  const auto *prefix_p = prefix_of(result);
  expect(prefix_p != nullptr, "the stale-grow fixture reaches a represented prefix or fails closed");
  if (prefix_p == nullptr) return;
  const auto fact = std::find_if(prefix_p->indirect_target_ea_sets.begin(), prefix_p->indirect_target_ea_sets.end(),
                                 [](const M68kIndirectTargetEaSet &set) {
                                   return set.source_instruction.source.address.value == 0xC040U;
                                 });
  if (fact != prefix_p->indirect_target_ea_sets.end()) {
    std::set<std::uint32_t> candidates;
    for (const auto &candidate : fact->candidates) candidates.insert(candidate.value);
    expect(candidates == std::set<std::uint32_t>{0xC060U, 0xC080U},
           "only the complete post-expansion finite set {Ta, Tb} proven on the stable graph is committed, never the "
           "pre-expansion {Ta}-only set");
    expect(find_edge(*prefix_p, M68kStaticEdgeKind::indirect_branch, 0xC040U) != nullptr,
           "the committed complete set owns its ordinary indirect_branch edges");
    std::set<std::uint32_t> edge_targets;
    for (const auto &edge : prefix_p->static_edges)
      if (edge.kind == M68kStaticEdgeKind::indirect_branch &&
          edge.source_instruction.source.address.value == 0xC040U)
        edge_targets.insert(edge.target.value);
    expect(edge_targets == std::set<std::uint32_t>{0xC060U, 0xC080U},
           "no indirect_branch edge is emitted for the incomplete pre-expansion target set");
  } else {
    expect(find_edge(*prefix_p, M68kStaticEdgeKind::indirect_branch, 0xC040U) == nullptr,
           "with no committed Tier-1 set there is no stale indirect_branch edge for the computed JMP");
  }
  const auto again = analyze_m68k_frontend(program);
  const auto *p1 = prefix_of(result);
  const auto *p2 = prefix_of(again);
  expect(p1 != nullptr && p2 != nullptr,
         "repeated analysis of the identical input is deterministic");
}
}  // namespace t190_late_indirect_closure

// SEG-007-T195 / ADR-0009: the post-stitch indirect-target re-proof
// (`m68k_prove_stitched_an_indirect_targets`), previously restricted to the
// pure `JMP/JSR (An)` shape, also covers the brief PC-relative indexed shape
// `JMP (d8,PC,Dn.W)`. The intra-unit `compute_indirect_target_set` already
// proves this shape, but only over one offline-inventory partition unit's
// local decode cache: when the finite index value-flow crosses a BSR whose
// callee is a SEPARATE partition unit, the per-unit bounded callee-register-
// write footprint proof cannot see the callee's decode and conservatively
// wipes the index register, dropping the site to Tier-2. Over the merged
// post-stitch aggregate the identical fixed point keeps the index finite, so
// the closure now commits Tier-1.
namespace t195_cross_unit_pc_index8_closure {
using namespace segarecomp;
using t190_late_indirect_closure::find_edge;
using t190_late_indirect_closure::hint;
using t190_late_indirect_closure::make_program;
using t190_late_indirect_closure::prefix_of;
using t190_late_indirect_closure::put;

// entry unit (0x9000): ANDI.W #$2,D1 (unknown -> finite {0,2}); BSR.W to the
// callee in its own unit; ADD.W D1,D1 ({0,2} -> {0,4}); JMP (0x10,PC,D1.W)
// -> candidates {0x901C, 0x9020}. Callee unit (0x9100): MOVE.W D0,D2; RTS --
// provably never writes D1. Targets 0x901C / 0x9020 are plain NOP/RTS pads.
std::vector<std::uint8_t> cross_unit_image() {
  std::vector<std::uint8_t> b;
  put(b, 0x00U, {0x02U, 0x41U, 0x00U, 0x02U});  // 0x9000 ANDI.W #$2,D1
  put(b, 0x04U, {0x61U, 0x00U, 0x00U, 0xFAU});  // 0x9004 BSR.W 0x9100  (cont 0x9008)
  put(b, 0x08U, {0xD2U, 0x41U});                // 0x9008 ADD.W D1,D1
  put(b, 0x0AU, {0x4EU, 0xFBU, 0x10U, 0x10U});  // 0x900A JMP (0x10,PC,D1.W)
  put(b, 0x1CU, {0x4EU, 0x71U});                // 0x901C target A: NOP
  put(b, 0x1EU, {0x4EU, 0x71U});                // 0x901E NOP
  put(b, 0x20U, {0x4EU, 0x75U});                // 0x9020 target B: RTS
  put(b, 0x100U, {0x34U, 0x00U, 0x4EU, 0x75U}); // 0x9100 callee: MOVE.W D0,D2 ; RTS
  return b;
}

const M68kIndirectTargetEaSet *tier1_for(const FrontendAnalysis &prefix, std::uint32_t source) {
  for (const auto &set : prefix.indirect_target_ea_sets)
    if (set.source_instruction.source.address.value == source) return &set;
  return nullptr;
}

void cross_unit_pc_index8_jmp_is_reproven_tier1_over_the_merged_graph() {
  const std::uint32_t base = 0x9000U;
  const auto image = cross_unit_image();
  const auto program =
      make_program("synthetic/SEG-007-T195/cross-unit-pc-index8", image, base, base, {hint(0x9100U)});
  const auto result = analyze_m68k_frontend(program);
  const auto *prefix_p = prefix_of(result);
  expect(prefix_p != nullptr, "the cross-unit pc_index8 fixture reaches a represented prefix");
  if (prefix_p == nullptr) return;
  const auto &prefix = *prefix_p;

  const auto *fact = tier1_for(prefix, 0x900AU);
  expect(fact != nullptr && fact->control_ea.mode == M68kEaMode::pc_index8 &&
             fact->control_ea.index_reg == 1U && !fact->control_ea.index_is_address &&
             !fact->control_ea.index_is_long,
         "a Tier-1 pc_index8 target set is committed for the cross-unit-narrowed JMP source");
  if (fact != nullptr) {
    std::vector<std::uint32_t> candidates;
    for (const auto &c : fact->candidates) candidates.push_back(c.value);
    std::sort(candidates.begin(), candidates.end());
    expect(candidates == std::vector<std::uint32_t>{0x901CU, 0x9020U},
           "the committed candidate set is exactly the two PC-relative table entries the finite "
           "index {0,4} selects");
  }
  expect(find_edge(prefix, M68kStaticEdgeKind::indirect_branch, 0x900AU) != nullptr,
         "the resolved site owns its ordinary indirect_branch edge");
  expect(std::none_of(prefix.unproven_indirect_control_ea_sets.begin(),
                      prefix.unproven_indirect_control_ea_sets.end(),
                      [](const M68kUnprovenIndirectControlEaSet &set) {
                        return set.source_instruction.source.address.value == 0x900AU;
                      }),
         "the weaker Tier-2 fact for the now-resolved site is erased on acceptance");

  const auto again = analyze_m68k_frontend(program);
  const auto *again_p = prefix_of(again);
  expect(again_p != nullptr && tier1_for(*again_p, 0x900AU) != nullptr &&
             tier1_for(*again_p, 0x900AU)->candidates.size() == 2U,
         "repeated analysis of the identical input deterministically commits the same Tier-1 set");
}

// Negative: identical topology, but the callee DOES write D1 (MOVE.W D0,D1).
// The merged-graph footprint proof then correctly wipes D1 across the call, so
// no Tier-1 set is committed and the site stays a fail-closed Tier-2 frontier.
void cross_unit_callee_that_clobbers_the_index_stays_tier2() {
  const std::uint32_t base = 0x9000U;
  auto image = cross_unit_image();
  put(image, 0x100U, {0x32U, 0x00U, 0x4EU, 0x75U});  // 0x9100 callee: MOVE.W D0,D1 ; RTS
  const auto program =
      make_program("synthetic/SEG-007-T195/cross-unit-clobbered", image, base, base, {hint(0x9100U)});
  const auto result = analyze_m68k_frontend(program);
  const auto *prefix_p = prefix_of(result);
  expect(prefix_p != nullptr, "the clobbered negative fixture still reaches a represented prefix");
  if (prefix_p == nullptr) return;
  const auto &prefix = *prefix_p;
  expect(tier1_for(prefix, 0x900AU) == nullptr,
         "a callee that provably writes the index register yields no Tier-1 set (fail-closed)");
  expect(std::any_of(prefix.unproven_indirect_control_ea_sets.begin(),
                     prefix.unproven_indirect_control_ea_sets.end(),
                     [](const M68kUnprovenIndirectControlEaSet &set) {
                       return set.source_instruction.source.address.value == 0x900AU;
                     }),
         "the site remains a weaker Tier-2-eligible frontier, exactly as before");
}
}  // namespace t195_cross_unit_pc_index8_closure

// SEG-007-T195 review correction: the `pc_index8` post-stitch re-proof uses the
// complete merged BASE fixed point ONLY -- it must NOT consume ADR-0030's
// `context_states`. Those are chosen by an An-specific mechanism (interesting
// call sites finite for some eligible An; only unresolved `JMP/JSR (An)` sites;
// relevance against the exact An register; budget from unresolved An sites), so
// letting them feed the Dn `pc_index8` loop would make a `pc_index8` Tier-1
// result depend on contexts selected for unrelated `(An)` sites.
//
// This fixture pins that boundary. One graph carries:
//  * unit 1 (0xA000): a base-finite cross-unit `JMP (0x10,PC,D1.W)` the narrowed
//    loop still resolves over the merged graph -> guards against deleting it;
//  * a `JMP (A3)` site (0xA230, its own unit) unresolved in the base fixed point
//    but resolvable through the ADR-0030 An call context of a finite caller;
//  * a `JMP (0x02,PC,D2.W)` site (0xA238, its own unit) whose D2 is UNKNOWN in
//    the merged base fixed point (a finite caller path joins an unknown caller
//    path) but is incidentally FINITE inside that same An-selected context.
// Expected: the `(An)` site resolves Tier-1 via its context (ADR-0030 branch
// unchanged); the `pc_index8` D2 site is NOT given a Tier-1 set from the
// incidental context value and stays a fail-closed Tier-2 frontier.
namespace t195_an_context_dn_pc_index8_isolation {
using namespace segarecomp;
using t190_late_indirect_closure::hint;
using t190_late_indirect_closure::make_program;
using t190_late_indirect_closure::prefix_of;
using t190_late_indirect_closure::put;
using t195_cross_unit_pc_index8_closure::tier1_for;

std::vector<std::uint8_t> image() {
  std::vector<std::uint8_t> b;
  for (std::size_t i = 0; i < 0x264U; ++i) b.push_back((i % 2U == 0U) ? 0x4EU : 0x71U);  // NOP NOP ...

  // Unit 1 (entry 0xA000): base-finite cross-unit pc_index8 (index D1). Same
  // shape as t195_cross_unit_pc_index8_closure -- resolved only by the merged
  // post-stitch fixed point, so deleting the narrowed loop fails this fixture.
  put(b, 0x000U, {0x02U, 0x41U, 0x00U, 0x02U});  // 0xA000 ANDI.W #$2,D1  -> {0,2}
  put(b, 0x004U, {0x61U, 0x00U, 0x00U, 0xFAU});  // 0xA004 BSR.W 0xA100 (cont 0xA008)
  put(b, 0x008U, {0xD2U, 0x41U});                // 0xA008 ADD.W D1,D1   -> {0,4}
  put(b, 0x00AU, {0x4EU, 0xFBU, 0x10U, 0x10U});  // 0xA00A JMP (0x10,PC,D1.W) -> {0xA01C,0xA020}
  put(b, 0x01CU, {0x4EU, 0x71U});                // 0xA01C target A: NOP
  put(b, 0x01EU, {0x4EU, 0x71U});                // 0xA01E NOP
  put(b, 0x020U, {0x4EU, 0x75U});                // 0xA020 target B: RTS
  put(b, 0x100U, {0x34U, 0x00U, 0x4EU, 0x75U});  // 0xA100 callee: MOVE.W D0,D2 ; RTS

  // finite_caller (0xA200): proves A3 = {0xA260} and D2 = {2}, calls a clean
  // callee (never writes A3/D2), then its continuation reaches BOTH the
  // separately-unit'd JMP (A3) (0xA230) and JMP (0x02,PC,D2.W) (0xA238).
  put(b, 0x200U, {0x47U, 0xF9U, 0x00U, 0x00U, 0xA2U, 0x60U});  // 0xA200 LEA (0xA260).L,A3
  put(b, 0x206U, {0x74U, 0x02U});                              // 0xA206 MOVEQ #2,D2
  put(b, 0x208U, {0x61U, 0x00U, 0x00U, 0x36U});                // 0xA208 BSR.W 0xA240 (cont 0xA20C)
  put(b, 0x20CU, {0x66U, 0x22U});                              // 0xA20C BNE.S 0xA230
  put(b, 0x20EU, {0x60U, 0x28U});                              // 0xA20E BRA.S 0xA238
  // unknown_caller (0xA218): reaches the SAME two sites with A3/D2 never
  // written, forcing the merged BASE state at both to unknown.
  put(b, 0x218U, {0x66U, 0x16U});                              // 0xA218 BNE.S 0xA230
  put(b, 0x21AU, {0x60U, 0x1CU});                              // 0xA21A BRA.S 0xA238
  put(b, 0x240U, {0x4EU, 0x75U});                              // 0xA240 clean_callee: RTS
  put(b, 0x230U, {0x4EU, 0xD3U});                              // 0xA230 shared_an: JMP (A3)
  put(b, 0x238U, {0x4EU, 0xFBU, 0x20U, 0x02U});                // 0xA238 JMP (0x02,PC,D2.W) pc_base 0xA23A
  put(b, 0x23EU, {0x4EU, 0x71U, 0x4EU, 0x75U});               // 0xA23E incidental D2-context candidate pad
  put(b, 0x260U, {0x4EU, 0x71U, 0x4EU, 0x75U});               // 0xA260 final_target: NOP ; RTS
  return b;
}

void an_selected_context_does_not_leak_into_pc_index8_dn_proof() {
  const std::uint32_t base = 0xA000U;
  const auto bytes = image();
  const auto program = make_program(
      "synthetic/SEG-007-T195/an-context-dn-isolation", bytes, base, base,
      {hint(0xA100U), hint(0xA200U), hint(0xA218U), hint(0xA230U), hint(0xA238U), hint(0xA240U),
       hint(0xA260U)});
  const auto result = analyze_m68k_frontend(program);
  const auto *prefix_p = prefix_of(result);
  expect(prefix_p != nullptr, "the An-context / Dn-isolation fixture reaches a represented prefix");
  if (prefix_p == nullptr) return;
  const auto &prefix = *prefix_p;

  // (1) base-finite cross-unit pc_index8 stays Tier-1 -- guards the narrowed
  // loop against outright deletion.
  const auto *positive = tier1_for(prefix, 0xA00AU);
  std::vector<std::uint32_t> positive_candidates;
  if (positive != nullptr)
    for (const auto &c : positive->candidates) positive_candidates.push_back(c.value);
  std::sort(positive_candidates.begin(), positive_candidates.end());
  expect(positive != nullptr && positive->control_ea.mode == M68kEaMode::pc_index8 &&
             positive_candidates == std::vector<std::uint32_t>{0xA01CU, 0xA020U},
         "the base-finite cross-unit pc_index8 site is still reproven Tier-1 over the merged graph");

  // (2) the unresolved JMP (A3) site is resolved by ADR-0030's An-specific
  // bounded call context -- behavior unchanged by the review correction.
  const auto *an_site = tier1_for(prefix, 0xA230U);
  expect(an_site != nullptr && an_site->candidates.size() == 1U &&
             an_site->candidates.front().value == 0xA260U,
         "the (An) post-stitch proof still consumes ADR-0030 context_states (unchanged)");

  // (3) the pc_index8 D2 site is finite ONLY inside that An-selected context;
  // the merged BASE fixed point leaves D2 unknown. No Tier-1 set may be
  // fabricated from the incidental context value.
  expect(tier1_for(prefix, 0xA238U) == nullptr,
         "an An-selected call context never leaks a finite Dn into the pc_index8 post-stitch proof");
  expect(std::any_of(prefix.unproven_indirect_control_ea_sets.begin(),
                     prefix.unproven_indirect_control_ea_sets.end(),
                     [](const M68kUnprovenIndirectControlEaSet &set) {
                       return set.source_instruction.source.address.value == 0xA238U;
                     }),
         "the context-only-finite pc_index8 site stays a fail-closed Tier-2 frontier");
}
}  // namespace t195_an_context_dn_pc_index8_isolation

void t186_post_stitch_finite_an_jmp_becomes_a_proven_retained_relation_deterministically() {
  using namespace segarecomp;
  using namespace t186_fixture;
  // Deliberately reverse semantic flow vs numeric candidate order: `producer`
  // is numerically after `indirect_site`. Root selection must follow the SCC
  // DAG, not whichever candidate address sorts first.
  const auto first_result = analyze_m68k_frontend(
      make_program({candidate(indirect_site), candidate(target), candidate(producer)}));
  const auto second_result = analyze_m68k_frontend(
      make_program({candidate(producer), candidate(indirect_site), candidate(target)}));
  const auto third_result = analyze_m68k_frontend(
      make_program({candidate(target), candidate(producer), candidate(indirect_site)}));
  const auto *first = std::get_if<FrontendPartialProgram>(&first_result);
  const auto *second = std::get_if<FrontendPartialProgram>(&second_result);
  const auto *third = std::get_if<FrontendPartialProgram>(&third_result);
  expect(first != nullptr && second != nullptr && third != nullptr,
         "post-stitch finite An proof retains the synthetic computed-JMP prefix for every candidate permutation");
  if (first == nullptr || second == nullptr || third == nullptr) return;
  const auto &prefix = first->accepted_prefix;
  const auto fact = std::find_if(prefix.indirect_target_ea_sets.begin(), prefix.indirect_target_ea_sets.end(),
                                 [](const M68kIndirectTargetEaSet &set) {
                                   return set.source_instruction.source.address.value == indirect_site;
                                 });
  expect(fact != prefix.indirect_target_ea_sets.end() && fact->candidates.size() == 1U &&
             fact->candidates.front().value == target,
         "post-stitch analysis carries the finite LEA value across the validated unit boundary");
  expect(std::any_of(prefix.static_edges.begin(), prefix.static_edges.end(), [](const M68kStaticEdge &edge) {
           return edge.kind == M68kStaticEdgeKind::indirect_branch &&
                  edge.source_instruction.source.address.value == indirect_site && edge.target.value == target;
         }),
         "the proven computed JMP owns one ordinary validated indirect-branch relationship");

  const auto fact_signature = [](const FrontendPartialProgram &partial) {
    std::vector<std::tuple<std::uint32_t, int, std::uint8_t, std::vector<std::uint32_t>>> signature;
    for (const auto &set : partial.accepted_prefix.indirect_target_ea_sets) {
      std::vector<std::uint32_t> candidates;
      for (const auto candidate : set.candidates) candidates.push_back(candidate.value);
      signature.emplace_back(set.source_instruction.source.address.value,
                             static_cast<int>(set.control_ea.mode), set.control_ea.reg,
                             std::move(candidates));
    }
    std::sort(signature.begin(), signature.end());
    return signature;
  };
  const auto edge_signature = [](const FrontendPartialProgram &partial) {
    std::vector<std::tuple<std::uint32_t, int, std::uint32_t, bool, std::uint32_t, std::uint32_t>> signature;
    for (const auto &edge : partial.accepted_prefix.static_edges)
      signature.emplace_back(edge.source_instruction.source.address.value, static_cast<int>(edge.kind),
                             edge.target.value, edge.call.has_value(),
                             edge.call ? edge.call->callee.value : 0U,
                             edge.call ? edge.call->continuation.value : 0U);
    std::sort(signature.begin(), signature.end());
    return signature;
  };
  expect(fact_signature(*first) == fact_signature(*second) &&
             fact_signature(*first) == fact_signature(*third),
         "candidate input order cannot change any retained indirect-target fact");
  expect(edge_signature(*first) == edge_signature(*second) &&
             edge_signature(*first) == edge_signature(*third),
         "candidate input order cannot change any retained static edge");
  const auto emitted_first = expand_entry_rows(emit_m68k_general_startup_bridge_c(*first, std::string(64U, 'a')));
  const auto emitted_second = expand_entry_rows(emit_m68k_general_startup_bridge_c(*second, std::string(64U, 'a')));
  const auto emitted_third = expand_entry_rows(emit_m68k_general_startup_bridge_c(*third, std::string(64U, 'a')));
  expect(!emitted_first.starts_with("/* translation rejected:") && emitted_first == emitted_second &&
             emitted_first == emitted_third &&
             emitted_first.find("m68k_indirect_targets_00005010") != std::string::npos,
         "the post-stitch relation emits byte-identically across repeated candidate permutations");
}

// SEG-007-T190 / ADR-0031 supersedes the pre-T190 outcome of this fixture.
// Before ADR-0031 a late computed-JMP target whose ONLY static path was the
// exact JMP the post-stitch finite-An proof resolves was silently rejected at
// the `merged_decoded`/`block_entries` acceptance gate (the pre-T190 assertion
// here was "stays fail-closed"). The gate is UNCHANGED and unweakened; ADR-0031
// instead makes it satisfiable BY REPRESENTATION -- the sound proven candidate
// is fed back through the existing discover_m68k_static_graph admission probe +
// merge (Stage A) exactly like an ordinary admitted unit, then the same gate
// accepts it. `target` (0x00005020) decodes cleanly (BRA.S to the shared
// frontier) so Stage A admits it; the proof genuinely proved A0 = target via a
// real `LEA`, so this representation is sound, not fabricated.
void t190_post_stitch_an_jmp_with_a_late_only_target_is_represented_and_accepted() {
  using namespace segarecomp;
  using namespace t186_fixture;
  const auto result = analyze_m68k_frontend(make_program({candidate(indirect_site), candidate(producer)}));
  const auto *partial = std::get_if<FrontendPartialProgram>(&result);
  expect(partial != nullptr, "the late-only-target fixture reaches a represented partial prefix");
  if (partial == nullptr) return;
  const auto &prefix = partial->accepted_prefix;
  const auto fact = std::find_if(prefix.indirect_target_ea_sets.begin(), prefix.indirect_target_ea_sets.end(),
                                 [](const M68kIndirectTargetEaSet &set) {
                                   return set.source_instruction.source.address.value == indirect_site;
                                 });
  expect(fact != prefix.indirect_target_ea_sets.end() && fact->candidates.size() == 1U &&
             fact->candidates.front().value == target,
         "ADR-0031 Stage A represents the sound late-only target so the unweakened acceptance gate now accepts it");
  expect(std::any_of(prefix.static_edges.begin(), prefix.static_edges.end(), [](const M68kStaticEdge &edge) {
           return edge.kind == M68kStaticEdgeKind::indirect_branch &&
                  edge.source_instruction.source.address.value == indirect_site && edge.target.value == target;
         }),
         "the accepted late target owns one ordinary validated indirect-branch relationship");
  expect(prefix.offline_inventory_stitch_metrics.late_indirect_target_unit_count == 1U &&
             prefix.offline_inventory_stitch_metrics.late_indirect_closure_converged &&
             prefix.offline_inventory_stitch_metrics.late_indirect_closure_rounds == 3U,
         "the bounded closure represented exactly one late unit, committed it on the following graph-stable round, "
         "then revalidated it against the edge-expanded graph and converged");
  const auto emitted = expand_entry_rows(emit_m68k_general_startup_bridge_c(*partial, std::string(64U, 'a')));
  const auto again = expand_entry_rows(emit_m68k_general_startup_bridge_c(*partial, std::string(64U, 'a')));
  expect(emitted == again && !emitted.starts_with("/* translation rejected:") &&
             emitted.find("m68k_indirect_targets_00005010") != std::string::npos,
         "the late-represented computed target now lowers deterministically through the ordinary Tier-1 path");
}

