// Local helper shared by both T243 fixtures: counts non-overlapping
// occurrences of `needle` in `haystack`.
static std::size_t t243_count_occurrences(const std::string &haystack, const std::string &needle) {
  std::size_t count = 0U;
  std::size_t pos = 0U;
  while ((pos = haystack.find(needle, pos)) != std::string::npos) {
    ++count;
    pos += needle.size();
  }
  return count;
}

void t243_represented_lowerable_block_has_matching_body_arm_and_membership() {
  using namespace segarecomp;

  // Part (A): the actual T244-relevant seam, using
  // `t243_root_disconnected_membership_fixture` (T242's own proven W/Y
  // shape combined with an ingress Tier-2 JSR site, so EmittedCodeAddressSet
  // membership is textually verifiable, not merely inferred). Y is
  // independently walked, valid, complete, mapped, aligned, correctly
  // decoded, non-conflicting, lowerable, with no unsafe outgoing edge of its
  // own, and is RETAINED (mirroring
  // `t242_independently_walked_safe_block_survives_missing_graph_ownership`'s
  // own positive case) even though its sole graph predecessor W is erased
  // for its OWN unrelated unsafe edge, leaving Y with no provable static
  // reachability from the ingress, IRQ6, div0, any validated external
  // candidate root, or any Tier-1 candidate target -- exactly the "safe
  // represented code with no CFG ownership" shape T244's future build-time
  // ROM-derived identity source will hand this same pipeline.
  {
    using namespace t243_root_disconnected_membership_fixture;
    const auto result = analyze_m68k_frontend(make_program());
    const auto *partial = std::get_if<FrontendPartialProgram>(&result);
    expect(partial != nullptr, "T243(A) precondition: the fixture reaches a partial program");
    if (partial == nullptr) return;
    expect(!has_block(partial->accepted_prefix, w_address),
           "T243(A) precondition: W is erased for its own genuinely unsafe outgoing edge, unchanged from T242");
    expect(has_block(partial->accepted_prefix, y_address),
           "T243(A) precondition: Y survives retention with no provable static reachability from any known root");
    expect(!has_block(partial->accepted_prefix, w_dropped_tail),
           "T243(A) precondition: W's own dropped fallthrough tail is never itself fabricated as a retained "
           "block either");
    const auto emitted = expand_entry_rows(emit_m68k_general_startup_bridge_c(*partial, std::string(64U, 'a')));
    expect(!emitted.empty() && emitted.rfind("/* translation rejected:", 0) != 0,
           "T243(A): C4 emits the represented prefix instead of rejecting the whole translation");
    std::ostringstream suffix;
    suffix << std::uppercase << std::hex << std::setw(8) << std::setfill('0') << y_address;
    const auto body_signature = "genesis_block_" + suffix.str() + "(GenesisRuntime *runtime) {";
    const auto dispatch_arm =
        "{ UINT32_C(0x" + suffix.str() + "), genesis_block_" + suffix.str() + " }";
    expect(t243_count_occurrences(emitted, body_signature) == 1U,
           "T243(A): the T244-relevant seam -- a root-disconnected, T242-retained safe block still gets "
           "exactly one emitted body definition, no duplication and no omission, even without provable "
           "static reachability from any known root");
    expect(t243_count_occurrences(emitted, dispatch_arm) == 1U,
           "T243(A): the same root-disconnected safe block gets exactly one compiled lookup row");
    // Real, text-visible EmittedCodeAddressSet membership: the ingress's own
    // JSR is a genuine Tier-2 site, so its
    // `genesis_emitted_code_addresses_<jsr_suffix>` array literal lists
    // every member of the final EmittedCodeAddressSet -- this is the actual
    // generation-time authority Tier 2 checks a computed runtime target
    // against (ADR-0024), not inferred merely from body/dispatch text.
    std::ostringstream jsr_suffix;
    jsr_suffix << std::uppercase << std::hex << std::setw(8) << std::setfill('0') << jsr_address;
    const auto array_name = "genesis_emitted_code_addresses_" + jsr_suffix.str();
    const auto array_decl_pos = emitted.find(array_name + "[] = {");
    expect(array_decl_pos != std::string::npos,
           "T243(A) precondition: the ingress's own Tier-2 JSR site has a real EmittedCodeAddressSet array");
    if (array_decl_pos != std::string::npos) {
      const auto array_end = emitted.find("};", array_decl_pos);
      const auto array_text = emitted.substr(array_decl_pos, array_end - array_decl_pos);
      expect(array_text.find("UINT32_C(0x" + suffix.str() + ")") != std::string::npos,
             "T243(A): the same root-disconnected safe block is a genuine EmittedCodeAddressSet member -- "
             "the only authority Tier 2 ever checks a computed runtime target against -- not merely "
             "body/dispatch text with no compiled membership entry");
    }
    // Atomicity: this block's own entry never also becomes a typed
    // frontier/tier1 pre-PC stop -- ordinary compiled membership only.
    expect(emitted.find("genesis_frontier_stop_" + suffix.str()) == std::string::npos &&
               emitted.find("genesis_tier1_indirect_stop_" + suffix.str()) == std::string::npos,
           "T243(A): the root-disconnected safe block's own entry never also acquires a typed "
           "frontier/tier1 stop identity");
  }

  // Part (A2): the root-disconnected RETAINED CYCLE case (reviewer
  // correction, third pass; fixture revised repeatedly during development,
  // see the namespace comment above for the full account, including the
  // HONEST disclosure that this specific synthetic shape is not, by itself,
  // a mechanically isolated falsification of only the new code -- the
  // decisive proof is the real Sonic ROM evidence in this task's backlog
  // record). Unlike the single-block case above, A and B each have an
  // internal retained predecessor (each is the other's), so the
  // zero-retained-predecessor rule alone cannot admit either. Both must
  // still get exactly one body, one dispatch arm, and a real
  // EmittedCodeAddressSet membership entry, proving the overall pipeline
  // correctly represents a root-disconnected mutual cycle end-to-end --
  // never a silent drop -- exactly the shape ADR-0039's invariant
  // describes, even though (per the namespace comment) this particular
  // fixture is not the sole evidence that the NEW graph-component code
  // specifically (as opposed to the pre-existing T185 seed) is what
  // explains it.
  //
  // This fixture registers an external_code_entry_candidate (required for
  // C's own erasure to fire at all -- see the namespace comment), so Tier 2
  // DOES engage here; membership is nonetheless verified through
  // `genesis_dispatch`'s own arm rather than a per-frontier emitted-address
  // array, which is an equally direct proof, not a weaker one:
  // `emitted_code_address_set` (the literal array Tier 2 checks a computed
  // target against) is constructed as a DIRECT COPY of
  // `emitted_block_entries` (`const std::vector<std::uint32_t>
  // emitted_code_address_set(emitted_block_entries.begin(),
  // emitted_block_entries.end());`), and `emitted_block_entries.contains(
  // block.id.entry.value)` is the EXACT SAME predicate that gates whether
  // this per-block loop emits a body/dispatch arm for that block at all
  // (`if (!emitted_block_entries.contains(block.id.entry.value)) continue;`
  // immediately above it). A block cannot acquire a genesis_dispatch arm
  // without also being a member of emitted_block_entries, and therefore of
  // emitted_code_address_set -- these are not two independently-verified
  // facts, they are the same underlying set observed through two
  // mechanically inseparable consequences of it.
  {
    using namespace t243_root_disconnected_cycle_fixture;
    const auto result = analyze_m68k_frontend(make_program());
    const auto *partial = std::get_if<FrontendPartialProgram>(&result);
    expect(partial != nullptr, "T243(A2) precondition: the fixture reaches a partial program");
    if (partial == nullptr) return;
    expect(!has_block(partial->accepted_prefix, c_address),
           "T243(A2) precondition: C is erased for its own genuinely unsafe outgoing edge");
    expect(!has_block(partial->accepted_prefix, c_dropped_tail),
           "T243(A2) precondition: C's own dropped fallthrough tail is never itself fabricated as a "
           "retained block either");
    expect(has_block(partial->accepted_prefix, a_address) && has_block(partial->accepted_prefix, b_address),
           "T243(A2) precondition: both A and B survive retention with no provable static reachability "
           "from any known root -- their only possible path (through C) vanished with C -- even though "
           "each still has a retained predecessor (the other block in the cycle)");
    expect(partial->accepted_prefix.indirect_target_ea_sets.empty() &&
               partial->accepted_prefix.unproven_indirect_control_ea_sets.empty(),
           "T243(A2) precondition: no Tier-1/Tier-2 fact exists anywhere in this program -- A and B are "
           "connected via ordinary direct branches only, never routed through Tier-1's own separate "
           "candidate-preservation seeding loop");
    const auto emitted = expand_entry_rows(emit_m68k_general_startup_bridge_c(*partial, std::string(64U, 'a')));
    expect(!emitted.empty() && emitted.rfind("/* translation rejected:", 0) != 0,
           "T243(A2): C4 emits the represented prefix instead of rejecting the whole translation");
    for (const auto member : {a_address, b_address}) {
      std::ostringstream suffix;
      suffix << std::uppercase << std::hex << std::setw(8) << std::setfill('0') << member;
      const auto body_signature = "genesis_block_" + suffix.str() + "(GenesisRuntime *runtime) {";
      const auto dispatch_arm =
          "{ UINT32_C(0x" + suffix.str() + "), genesis_block_" + suffix.str() + " }";
      expect(t243_count_occurrences(emitted, body_signature) == 1U,
             "T243(A2): each cycle member gets exactly one emitted body definition, no duplication and "
             "no omission, even though its only retained predecessor is the OTHER cycle member");
      expect(t243_count_occurrences(emitted, dispatch_arm) == 1U,
             "T243(A2): each cycle member gets exactly one compiled lookup row -- and therefore, by the "
             "shared-construction argument above, exactly one EmittedCodeAddressSet membership entry");
      expect(emitted.find("genesis_frontier_stop_" + suffix.str()) == std::string::npos &&
                 emitted.find("genesis_tier1_indirect_stop_" + suffix.str()) == std::string::npos,
             "T243(A2): a cycle member's own entry never also acquires a typed frontier/tier1 stop "
             "identity");
    }
  }

  // Part (A3): the FALSIFYING NEGATIVE case (reviewer correction, fourth
  // pass) -- see t243_cut_downstream_component_fixture's own namespace
  // comment for the full account. C (root-reachable) terminates at a
  // genuine, intentional Tier-1 cut (one of its own proven candidates is an
  // orphaned RTS); A and B form their own live, mutual two-block cycle, but
  // their ONLY external retained ingress is C's own cut -- not a vanished
  // predecessor like (A2)'s own C. A and B must NOT receive an ordinary
  // emitted body, a genesis_dispatch arm, or an EmittedCodeAddressSet
  // membership entry: the cut's own intentional non-continuation must not
  // be "laundered" into unconditional executable authority merely because
  // A and B happen to form a live component with each other. This
  // subcase, using the raw/single-unit route (no external candidates and
  // the relation's own `tier1_pre_pc_stops` membership excludes it from
  // the separate Tier-1-candidate-preservation loop), is the mechanically
  // isolated falsification (2) requires: it fails against the third pass's
  // "seed every multi-member component" rule and passes only with the
  // corrected external-cut-predecessor check.
  {
    using namespace t243_cut_downstream_component_fixture;
    const auto result = analyze_m68k_frontend(make_program());
    const auto *partial = std::get_if<FrontendPartialProgram>(&result);
    expect(partial != nullptr, "T243(A3) precondition: the fixture reaches a partial program");
    if (partial == nullptr) return;
    expect(!has_block(partial->accepted_prefix, b_dropped_tail),
           "T243(A3) precondition: B's own dropped fallthrough tail (RESET, the program's sole frontier "
           "obligation) is never itself fabricated as a retained block");
    expect(partial->accepted_prefix.indirect_target_ea_sets.size() == 1U &&
               partial->accepted_prefix.indirect_target_ea_sets.front().candidates.size() == 2U,
           "T243(A3) precondition: C's own JMP is a genuine two-candidate proven Tier-1 relation");
    expect(!has_block(partial->accepted_prefix, orphan_rts_address),
           "T243(A3) precondition: the orphaned RTS candidate is pruned, exactly like the preserved "
           "general_startup_jmp_dispatch_with_one_orphan_rts_candidate_stays_unresolved sibling test");
    // A and B may legitimately remain retained static blocks -- that is the
    // existing, unaffected analysis representation (T242's own scope,
    // untouched by this task's emission-time fix) -- but neither may
    // acquire EMISSION-time executable identity. Both are independently
    // walked, valid, complete, safe, with no unsafe outgoing edge of their
    // own, so this task's Evidence records (informationally, not as a
    // requirement this test enforces) that they do in fact stay retained
    // here; the acceptance requirement below is solely about EMISSION.
    const bool a_retained = has_block(partial->accepted_prefix, a_address);
    const bool b_retained = has_block(partial->accepted_prefix, b_address);
    expect(a_retained && b_retained,
           "T243(A3) informational: A and B remain retained static blocks in this program's actual "
           "analysis representation (not itself the acceptance requirement -- see below)");
    const auto emitted = expand_entry_rows(emit_m68k_general_startup_bridge_c(*partial, std::string(64U, 'a')));
    expect(!emitted.empty() && emitted.rfind("/* translation rejected:", 0) != 0,
           "T243(A3): C4 still emits the represented prefix -- the cut is a safe typed stop, not a whole "
           "translation rejection");
    std::ostringstream jmp_suffix;
    jmp_suffix << std::uppercase << std::hex << std::setw(8) << std::setfill('0') << jmp_address;
    expect(emitted.find("genesis_tier1_indirect_stop_" + jmp_suffix.str()) != std::string::npos,
           "T243(A3) precondition: C's own relation still gets its typed pre-PC fail-closed stop, exactly "
           "as the preserved orphan-RTS sibling test proves");
    for (const auto member : {a_address, b_address}) {
      std::ostringstream suffix;
      suffix << std::uppercase << std::hex << std::setw(8) << std::setfill('0') << member;
      const auto body_signature = "genesis_block_" + suffix.str() + "(GenesisRuntime *runtime) {";
      const auto dispatch_arm =
          "{ UINT32_C(0x" + suffix.str() + "), genesis_block_" + suffix.str() + " }";
      expect(t243_count_occurrences(emitted, body_signature) == 0U,
             "T243(A3): a component whose only external retained ingress is an intentional cut must NEVER "
             "receive an ordinary emitted body -- graph topology/internal connectivity alone is not "
             "independent executable identity");
      expect(t243_count_occurrences(emitted, dispatch_arm) == 0U,
              "T243(A3): a cut-downstream component must never receive a compiled lookup row either");
    }
    // Negative membership proof: since `emitted_code_address_set` is a
    // direct copy of `emitted_block_entries` and neither member acquired a
    // dispatch arm (the same predicate that would have added it to that
    // set), neither member is an EmittedCodeAddressSet member -- the
    // absence of a dispatch arm above is already the direct, mechanical
    // proof of membership exclusion (see (A2)'s own shared-construction
    // argument for why this equivalence holds in both directions).
  }

  // Part (A) subcase: the no-Tier1/no-Tier2-fact residual computed-control
  // case from T243's first pass. This is NOT compiled-membership routing --
  // it is the OTHER legal monotonic outcome (a typed pre-PC stop) for a
  // retained block whose terminal genuinely has no proof of any kind.
  // Labeled explicitly here so it is never confused with fixture (B) below,
  // which proves the real compiled-membership mechanism.
  {
    using namespace t243_reachable_unresolved_computed_control_fixture;
    const auto result = analyze_m68k_frontend(make_program());
    const auto *partial = std::get_if<FrontendPartialProgram>(&result);
    expect(partial != nullptr, "T243(A) subcase precondition: the fixture reaches a partial program");
    if (partial == nullptr) return;
    const bool candidate_block_retained =
        std::any_of(partial->accepted_prefix.static_blocks.begin(), partial->accepted_prefix.static_blocks.end(),
                    [](const M68kStaticBlock &block) { return block.id.entry.value == candidate_address; });
    expect(candidate_block_retained,
           "T243(A) subcase: a reachable computed-control block with no proven Tier-1 target set and no "
           "Tier-2 fact is retained, not silently pruned, now that it is genuinely reached by a live "
           "retained predecessor");
    const auto emitted = expand_entry_rows(emit_m68k_general_startup_bridge_c(*partial, std::string(64U, 'a')));
    expect(!emitted.empty() && emitted.rfind("/* translation rejected:", 0) != 0,
           "T243(A) subcase: C4 emits the represented prefix instead of rejecting the whole translation");
    std::ostringstream suffix;
    suffix << std::uppercase << std::hex << std::setw(8) << std::setfill('0') << candidate_address;
    const auto typed_stop_name = "genesis_tier1_indirect_stop_" + suffix.str();
    expect(emitted.find(typed_stop_name) != std::string::npos,
           "T243(A) subcase: the retained no-proof computed-control terminal gets its own typed pre-PC "
           "fail-closed stop (GENESIS_STOP_UNRESOLVED_INDIRECT_TARGET) -- a DIFFERENT, weaker mechanism "
           "than fixture (B)'s compiled-membership routing, never interchangeable with it");
    expect(emitted.find("genesis_frontier_stop_" + suffix.str()) == std::string::npos &&
               emitted.find("m68k_emitted_code_address_member") == std::string::npos,
           "T243(A) subcase: this no-proof residual case never routes through Tier 2's compiled-membership "
           "mechanism -- it must never be mislabeled as \"compiled membership\" routing");
  }
}

void t243_represented_computed_control_uses_compiled_membership_before_mutation() {
  using namespace segarecomp;
  using namespace t243_jmp_compiled_membership_fixture;

  std::ostringstream jmp_suffix;
  jmp_suffix << std::uppercase << std::hex << std::setw(8) << std::setfill('0') << jmp_address;
  const auto array_name = "genesis_emitted_code_addresses_" + jmp_suffix.str();
  const auto frontier_stop_name = "genesis_frontier_stop_" + jmp_suffix.str();
  const auto tier1_stop_name = "genesis_tier1_indirect_stop_" + jmp_suffix.str();

  // IN-SET: the candidate is itself the only validated external root
  // (mirrors `tier2_computed_target_inside_emitted_set_dispatches_
  // successfully`'s own shape, for JMP instead of JSR).
  {
    const auto result = analyze_m68k_frontend(make_program({make_candidate(candidate_address)}));
    const auto *partial = std::get_if<FrontendPartialProgram>(&result);
    expect(partial != nullptr, "T243(B) in-set: the fixture with a matching candidate reaches a partial program");
    if (partial == nullptr) return;
    const bool has_tier2_fact =
        std::any_of(partial->accepted_prefix.unproven_indirect_control_ea_sets.begin(),
                    partial->accepted_prefix.unproven_indirect_control_ea_sets.end(),
                    [](const M68kUnprovenIndirectControlEaSet &set) {
          return set.source_instruction.source.address.value == jmp_address;
        });
    expect(has_tier2_fact, "T243(B) precondition: the runtime-computed JMP is a genuine Tier-2 unproven-EA site");
    const auto emitted = expand_entry_rows(emit_m68k_general_startup_bridge_c(*partial, std::string(64U, 'a')));
    expect(emitted.find(array_name + "[] = {UINT32_C(0x00006000), UINT32_C(0x0000600A)};") != std::string::npos,
           "T243(B) in-set: the emitted code address set is the sorted, deduplicated union of the reset entry "
           "and the validated candidate block");
    expect(emitted.find("m68k_emitted_code_address_member(" + array_name) != std::string::npos,
           "T243(B) in-set: destination membership is consulted through T239's shared compiled-address "
           "existence check (emit_m68k_compiled_address_existence_check), the SAME code JSR uses "
           "(t239_jmp_and_jsr_to_shared_destination_use_byte_identical_existence_check)");
    expect(emitted.find("transfer.kind = GENESIS_CONTINUE_AT_PC;") != std::string::npos &&
               emitted.find("transfer.next_pc = m68k_indirect_ea;") != std::string::npos,
           "T243(B) in-set: an in-set computed destination dispatches through the ordinary "
           "GENESIS_CONTINUE_AT_PC transfer, never a second dispatch mechanism");
    // This is genuine compiled-membership routing (Tier 2's own typed
    // frontier), never the no-proof residual tier1 pre-PC stop mechanism
    // fixture (A)'s subcase exercises -- the two are never interchangeable.
    expect(emitted.find(frontier_stop_name) != std::string::npos,
           "T243(B) in-set: this is genuinely routed through build_genesis_frontier_stop_function's own "
           "typed frontier mechanism");
    expect(emitted.find(tier1_stop_name) == std::string::npos,
           "T243(B) in-set: this must never be mislabeled as the no-proof residual tier1 pre-PC stop -- "
           "it is real compiled-membership routing, a different mechanism entirely");
    expect(emitted.find("m68k_decode") == std::string::npos && emitted.find("m68k_fetch") == std::string::npos,
           "T243(B): no runtime opcode fetch/decode exists anywhere in this path");
  }

  // OUT-OF-SET: an unrelated external candidate keeps Tier 2 engaged but
  // never admits the JMP's own faithful destination (0x0000600A) as a
  // member, so it must fail closed strictly before any architectural
  // mutation.
  {
    const auto result = analyze_m68k_frontend(make_program({make_candidate(base)}));
    const auto *partial = std::get_if<FrontendPartialProgram>(&result);
    expect(partial != nullptr, "T243(B) out-of-set: the fixture with an unrelated candidate reaches a partial "
                               "program");
    if (partial == nullptr) return;
    const auto emitted = expand_entry_rows(emit_m68k_general_startup_bridge_c(*partial, std::string(64U, 'a')));
    expect(emitted.find(array_name + "[] = {UINT32_C(0x00006000)};") != std::string::npos,
           "T243(B) out-of-set: the emitted code address set never contains the unreachable candidate address "
           "0x0000600A here");
    expect(emitted.find("GENESIS_DIAG_TIER2_COMPUTED_TARGET_NOT_EMITTED") != std::string::npos,
           "T243(B) out-of-set: a non-member computed destination fails closed with the precise Tier-2 "
           "diagnostic, not a fabricated candidate and not a silent drop");
    // "Before any architectural mutation": the fail-closed return happens
    // strictly before any `runtime->a[7]` mutation in the same function
    // body.
    const auto function_start = emitted.find(frontier_stop_name + "(GenesisRuntime *runtime) {");
    const auto diagnostic_pos = emitted.find("GENESIS_DIAG_TIER2_COMPUTED_TARGET_NOT_EMITTED", function_start);
    const auto a7_mutation_pos = emitted.find("runtime->a[7] = m68k_new_a7;", function_start);
    expect(function_start != std::string::npos && diagnostic_pos != std::string::npos &&
               (a7_mutation_pos == std::string::npos || diagnostic_pos < a7_mutation_pos),
           "T243(B) out-of-set: the fail-closed stop is textually reached before any architectural mutation, "
           "so a non-member computed destination leaves PC/A7 unchanged, exactly as T239 requires");
    expect(emitted.find(tier1_stop_name) == std::string::npos,
           "T243(B) out-of-set: this compiled-membership fail-closed stop must never be mislabeled as, or "
           "conflated with, the different no-proof residual tier1 pre-PC stop mechanism");
  }
}

void t194_orphan_an_indexed_pc_index8_jmp_pruning_is_deterministic_across_runs() {
  using namespace segarecomp;
  using namespace t194_orphan_indexed_indirect_fixture;
  const auto first = analyze_m68k_frontend(make_program({make_candidate(candidate_address)}));
  const auto second = analyze_m68k_frontend(make_program({make_candidate(candidate_address)}));
  const auto *pa = std::get_if<FrontendPartialProgram>(&first);
  const auto *pb = std::get_if<FrontendPartialProgram>(&second);
  expect(pa != nullptr && pb != nullptr, "both runs reach a partial program");
  if (pa == nullptr || pb == nullptr) return;
  expect(pa->accepted_prefix.static_blocks.size() == pb->accepted_prefix.static_blocks.size(),
         "the pruning outcome is deterministic across repeated runs");
  expect(expand_entry_rows(emit_m68k_general_startup_bridge_c(*pa, std::string(64U, 'a'))) ==
             expand_entry_rows(emit_m68k_general_startup_bridge_c(*pb, std::string(64U, 'a'))),
         "the emitted C is byte-identical across repeated runs");
}

// SEG-007-T194 defensive regression: T194's new orphan-pruning class must
// prune ONLY a genuinely unreachable/speculative computed-control terminal
// (the offline-hinted-candidate-only shape the two fixtures above exercise),
// never an AUTHORITATIVE, reset-reachable one. This namespace reuses the
// exact same architecturally-excluded An-indexed pc_index8 control EA shape,
// but places it as the startup ingress's OWN entry instruction -- reached by
// the reset root's own primary walk, not merely proposed by an untrusted
// offline candidate -- with no external code-entry candidate involved at
// all. An authoritative root's own `reached_unresolved_direct_edge` issue is
// never dropped by the non-authoritative-root issue-preservation pass (that
// pass only demotes/filters a NON-primary candidate root's own issue), so
// this exact shape must still surface as an explicit, fail-closed
// `unresolved_indirect_target` frontier obligation -- never silently pruned
// into an apparently-complete, frontier-less build.
namespace t194_authoritative_indexed_indirect_fixture {
using namespace segarecomp;
constexpr std::uint32_t base = 0x00005100U;
// The reset ingress's OWN entry IS the computed-control JMP; no offline
// candidate is involved, so this site is reachable only through the
// authoritative reset root's own primary walk.
constexpr std::uint32_t ingress_address = base;

std::vector<std::uint8_t> make_image() {
  std::vector<std::uint8_t> b;
  // 0x00: JMP (0x00,PC,A1) -- the same An-indexed brief-format pc_index8
  // control EA the offline-candidate-only fixture above uses, so this
  // regression isolates exactly one variable: reachability authority, not
  // control-EA shape.
  b.insert(b.end(), {0x4EU, 0xFBU, 0x90U, 0x00U});
  return b;
}

FrontendProgram make_program() {
  FrontendProgram program{};
  program.profile = M68kFrontendProfile::general_startup;
  static const std::vector<std::uint8_t> image = make_image();
  program.image = {"synthetic/SEG-007-T194/authoritative-an-indexed-pc-index8", image, image.size()};
  program.mapping_claims = {
      {"rom", {{}, base}, {{}, static_cast<std::uint32_t>(base + image.size())}, {0U}, {image.size()}}};
  // No external_code_entry_candidates: this site is reached ONLY via the
  // reset ingress's own primary walk.
  program.startup_ingress = M68kStartupIngress{{{}, ingress_address}, 0x00FF0100U};
  return program;
}
}  // namespace t194_authoritative_indexed_indirect_fixture

void t194_authoritative_an_indexed_pc_index8_jmp_remains_a_fail_closed_frontier() {
  using namespace segarecomp;
  using namespace t194_authoritative_indexed_indirect_fixture;
  const auto result = analyze_m68k_frontend(make_program());
  const auto *partial = std::get_if<FrontendPartialProgram>(&result);
  const auto *rejected = std::get_if<FrontendRejected>(&result);
  const auto *completed = std::get_if<FrontendAnalysis>(&result);
  expect(completed == nullptr,
         "an authoritative reset-reachable unresolved computed-control JMP must never silently "
         "complete the whole translation");
  expect(partial != nullptr || rejected != nullptr,
         "the authoritative unresolved site reaches either a partial program with an explicit "
         "frontier or an outright rejection, never a silent success");
  if (partial != nullptr) {
    expect(!partial->frontiers.empty(),
           "T194's orphan-pruning class must not silently discard the authoritative site without "
           "recording it as an explicit frontier obligation");
    const bool has_matching_frontier =
        std::any_of(partial->frontiers.begin(), partial->frontiers.end(), [](const UnresolvedFrontier &frontier) {
          return frontier.class_ == GenesisFrontierClass::unresolved_indirect_target &&
                 frontier.diagnostic.source_address && frontier.diagnostic.source_address->value == ingress_address;
        });
    expect(has_matching_frontier,
           "the authoritative site's own frontier is classified unresolved_indirect_target at its "
           "exact source address, not fabricated, relabeled, or dropped");
    const bool candidate_block_retained_as_successful =
        std::any_of(partial->accepted_prefix.static_blocks.begin(), partial->accepted_prefix.static_blocks.end(),
                    [](const M68kStaticBlock &block) { return block.id.entry.value == ingress_address; });
    expect(!candidate_block_retained_as_successful,
           "the unresolved authoritative terminal is never retained as a successfully-emitted "
           "block -- it is represented only as a frontier obligation");
    const bool fabricated_tier1_fact =
        std::any_of(partial->accepted_prefix.indirect_target_ea_sets.begin(),
                    partial->accepted_prefix.indirect_target_ea_sets.end(), [](const M68kIndirectTargetEaSet &set) {
                      return set.source_instruction.source.address.value == ingress_address;
                    });
    expect(!fabricated_tier1_fact,
           "no Tier-1 indirect-target fact is fabricated for the authoritative site merely to let "
           "it pass");
  }
}

void negate_word_data_register_direct_is_bounded_and_has_subtraction_flags() {
  using namespace segarecomp;
  // The old exact NEG.W Dn subset remains byte-for-byte equivalent while the
  // general decoder also accepts every legal size and data-alterable EA.
  for (const auto& [opcode, size] : std::array<std::pair<std::uint16_t, M68kMemoryAccessWidth>, 3>{{
           {UINT16_C(0x4400), M68kMemoryAccessWidth::byte}, {UINT16_C(0x4440), M68kMemoryAccessWidth::word},
           {UINT16_C(0x4480), M68kMemoryAccessWidth::long_word}}}) {
    const auto decoded = decode_m68k_instruction(
        std::array<std::uint8_t, 2>{static_cast<std::uint8_t>(opcode >> 8U), static_cast<std::uint8_t>(opcode)},
        source(), M68kDecodeProfile::general_startup);
    const auto *instruction = std::get_if<M68kDecodedInstruction>(&decoded);
    expect(instruction != nullptr && instruction->kind == M68kInstructionKind::negate_word && instruction->size == size &&
                instruction->destination_ea.mode == M68kEaMode::data_register && instruction->destination_ea.reg == 0U &&
                instruction->provenance.length.value == 2U,
           "NEG.B/W/L Dn decode through the general NEG shape with two-byte provenance");
    if (instruction != nullptr) {
      const auto operation = lift_m68k_instruction(*instruction);
      const auto effect = m68k_operation_effect(operation);
      expect(operation.kind == M68kIrKind::negate_word && effect.affects_condition_codes &&
                  effect.extend_flag_policy == M68kExtendFlagPolicy::from_carry && effect.resolved_source_ea &&
                  effect.resolved_destination_ea && effect.resolved_source_ea->reg == 0U &&
                  effect.pc == M68kPcEffectKind::advance && effect.pc_delta == 2U,
              "NEG.B/W/L retain their typed Dn operand through IR and declare subtraction effects");
    }
  }
  for (std::uint8_t reg = 0U; reg < 8U; ++reg) {
    const auto decoded = decode_m68k_instruction(
        std::array<std::uint8_t, 2>{UINT8_C(0x44), static_cast<std::uint8_t>(UINT8_C(0x40) | reg)}, source(),
        M68kDecodeProfile::general_startup);
    const auto *instruction = std::get_if<M68kDecodedInstruction>(&decoded);
    expect(instruction != nullptr && instruction->destination_ea.mode == M68kEaMode::data_register &&
                instruction->destination_ea.reg == reg && instruction->size == M68kMemoryAccessWidth::word,
           "the old NEG.W Dn encodings retain exactly their previous decoded semantics");
  }
  for (const auto& [opcode, size] : std::array<std::pair<std::uint16_t, M68kMemoryAccessWidth>, 3>{{
           {UINT16_C(0x4410), M68kMemoryAccessWidth::byte}, {UINT16_C(0x4450), M68kMemoryAccessWidth::word},
           {UINT16_C(0x4490), M68kMemoryAccessWidth::long_word}}}) {
    const auto decoded = decode_m68k_instruction(
        std::array<std::uint8_t, 2>{static_cast<std::uint8_t>(opcode >> 8U), static_cast<std::uint8_t>(opcode)},
        source(), M68kDecodeProfile::general_startup);
    const auto *instruction = std::get_if<M68kDecodedInstruction>(&decoded);
    expect(instruction != nullptr && instruction->kind == M68kInstructionKind::negate_word && instruction->size == size &&
                instruction->destination_ea.mode == M68kEaMode::address_indirect &&
                lift_m68k_instruction(*instruction).kind == M68kIrKind::negate_word,
           "NEG.B/W/L (An) decode and lift through the shared data-alterable destination path");
  }
  struct NegEaCase { std::vector<std::uint8_t> bytes; M68kEaMode mode; std::uint32_t length; };
  for (const auto &test : std::array<NegEaCase, 6>{{
           {{{0x44U, 0x10U}}, M68kEaMode::address_indirect, 2U},
           {{{0x44U, 0x58U}}, M68kEaMode::address_postinc, 2U},
           {{{0x44U, 0xA0U}}, M68kEaMode::address_predec, 2U},
           {{{0x44U, 0x69U, 0xFFU, 0xFEU}}, M68kEaMode::address_disp16, 4U},
           {{{0x44U, 0x78U, 0x00U, 0x10U}}, M68kEaMode::absolute_word, 4U},
           {{{0x44U, 0xB9U, 0x00U, 0x00U, 0x00U, 0x10U}}, M68kEaMode::absolute_long, 6U}}}) {
    const auto decoded = decode_m68k_instruction(test.bytes, source(), M68kDecodeProfile::general_startup);
    const auto *instruction = std::get_if<M68kDecodedInstruction>(&decoded);
    expect(instruction != nullptr && instruction->kind == M68kInstructionKind::negate_word &&
                instruction->destination_ea.mode == test.mode && instruction->provenance.length.value == test.length &&
                lift_m68k_instruction(*instruction).kind == M68kIrKind::negate_word,
           "general NEG accepts each supported representative data-alterable destination and preserves lift provenance");
  }
  expect(m68k_subtraction_ccr(UINT16_C(0xA510), 0U, 0U, M68kMemoryAccessWidth::word,
                              M68kExtendFlagPolicy::from_carry) == UINT16_C(0xA504) &&
             m68k_subtraction_ccr(UINT16_C(0xA510), 1U, 0U, M68kMemoryAccessWidth::word,
                                  M68kExtendFlagPolicy::from_carry) == UINT16_C(0xA519) &&
             m68k_subtraction_ccr(UINT16_C(0xA510), UINT32_C(0x8000), 0U, M68kMemoryAccessWidth::word,
                                  M68kExtendFlagPolicy::from_carry) == UINT16_C(0xA51B),
         "NEG.W sets N/Z/V/C and copies borrow to X for zero, ordinary-negative, and signed-overflow results");

  const GenesisM68kEmissionContext memory{"ram", "a", "fi", "fc", "fd", 0U, std::nullopt, 0U, {}, {}};
  const auto decoded = std::get<M68kDecodedInstruction>(decode_m68k_instruction(
      std::array<std::uint8_t, 2>{UINT8_C(0x44), UINT8_C(0x47)}, source(), M68kDecodeProfile::general_startup));
  const auto emitted = emit_m68k_operation_c(lift_m68k_instruction(decoded), "d", "sr", "", &memory);
  expect(emitted.find("neg_result = UINT32_C(0) - neg_destination") != std::string::npos &&
             emitted.find("d[7] = (d[7] & UINT32_C(0xFFFF0000))") != std::string::npos &&
             emitted.find("compare_source") != std::string::npos && emitted.find("pc += UINT32_C(2)") != std::string::npos,
         "NEG.W generated C preserves Dn's upper word, derives flags through subtraction, and advances PC");

  for (const auto &bytes : std::array<std::array<std::uint8_t, 2>, 1>{{{{UINT8_C(0x44), UINT8_C(0x48)}}}}) {
    // SEG-021-T019: NEG An is architecturally illegal -- the vector-4 instruction-word exception with its primary provenance.
    const auto rejected = decode_m68k_instruction(bytes, source(), M68kDecodeProfile::general_startup);
    const auto *exception = std::get_if<M68kDecodedInstruction>(&rejected);
    expect(is_instruction_exception(rejected, 4U) && exception != nullptr && exception->provenance.bytes == bytes,
            "NEG An is the vector-4 instruction-word exception with primary provenance");
  }
  const auto reserved = decode_m68k_instruction(std::array<std::uint8_t, 2>{UINT8_C(0x44), UINT8_C(0xC0)},
                                                source(), M68kDecodeProfile::general_startup);
  const auto *reserved_instruction = std::get_if<M68kDecodedInstruction>(&reserved);
  expect(reserved_instruction == nullptr || reserved_instruction->kind != M68kInstructionKind::negate_word,
         "NEG's reserved size field never decodes as NEG (the overlapping MOVE-to-CCR encoding retains ownership)");
  const auto truncated = decode_m68k_instruction(std::array<std::uint8_t, 2>{UINT8_C(0x44), UINT8_C(0x69)},
                                                 source(), M68kDecodeProfile::general_startup);
  const auto *truncated_failure = std::get_if<RejectedM68kDecode>(&truncated);
  expect(truncated_failure != nullptr && truncated_failure->outcome == DecodeOutcome::truncated_instruction &&
              truncated_failure->requested_length == 4U && truncated_failure->has_provenance,
         "NEG d16(An) extension truncation is bounds-safe and retains primary provenance");
}

void negate_word_auto_update_uses_one_deferred_address_commit() {
  using namespace segarecomp;
  for (const auto& [opcode, mode] : std::array<std::pair<std::uint8_t, M68kEaMode>, 2>{{
           {UINT8_C(0x58), M68kEaMode::address_postinc}, {UINT8_C(0x60), M68kEaMode::address_predec}}}) {
    const auto decoded = std::get<M68kDecodedInstruction>(decode_m68k_instruction(
        std::array<std::uint8_t, 2>{UINT8_C(0x44), opcode}, source(), M68kDecodeProfile::general_startup));
    const auto operation = lift_m68k_instruction(decoded);
    expect(decoded.destination_ea.mode == mode && m68k_operation_is_immutable_rom_aot_safe(operation, false),
           "SEG-021-T014: NEG auto-update form is decoder-admitted and admitted to immutable-ROM AOT");
    GenesisM68kEmissionContext memory{"ram", "a", "fi", "fc", "fd", 0U, std::nullopt, 0U, {}, {}};
    memory.runtime_routing = true;
    memory.runtime_object = "runtime";
    memory.program_counter = "runtime->pc";
    const auto emitted = emit_m68k_operation_c(operation, "runtime->d", "runtime->sr", "", &memory);
    const auto read = emitted.find("GENESIS_ACCESS_READ");
    const auto write = emitted.find("GENESIS_ACCESS_WRITE");
    const auto read_failure_return = emitted.find("return transfer;", read);
    const auto write_failure_return = emitted.find("return transfer;", write);
    const auto commit = emitted.find("a[0] = m68k_neg_auto_ea");
    const auto pc = emitted.find("runtime->pc +=");
    expect(emitted.find("uint32_t m68k_neg_auto_ea = a[0]") != std::string::npos &&
               read != std::string::npos && write != std::string::npos &&
               read_failure_return != std::string::npos && write_failure_return != std::string::npos &&
               read < read_failure_return &&
               read_failure_return < write && write < write_failure_return && write_failure_return < commit && commit < pc,
           "NEG auto-update routed failures return before the next access or An/PC commit");
    expect(emitted.find("m68k_routed_addr_0 = (m68k_neg_auto_ea)") != std::string::npos &&
               emitted.find("m68k_routed_addr_3 = (m68k_neg_auto_ea)") != std::string::npos,
           "NEG read and write provenance bind the same deferred auto-update address");
  }
}

// SEG-021-T014: ADDX/SUBX/NEGX/NEG/CMPM. Legality is asserted from the Motorola encodings, independently of
// the T001 dataset (production never reads it).
// SEG-021-T014: immutable-ROM AOT fixture for the extended-arithmetic family. Same filler prefix as the NEG/PEA
// fixtures, then seven independent AOT roots (the strict-C11 generated-native proof executes them as a chain).
namespace extended_arithmetic_aot_fixture {
using namespace segarecomp;
constexpr std::uint32_t base = 0x00000F00U;
const std::vector<std::uint8_t> image{
    0x30U, 0x51U, 0x4EU, 0x90U, 0x4EU, 0x71U, 0x60U, 0xF8U,
    0xD1U, 0x49U,  // F08 ADDX.W -(A1),-(A0)
    0xB1U, 0x49U,  // F0A CMPM.W (A1)+,(A0)+
    0x40U, 0x98U,  // F0C NEGX.L (A0)+
    0x40U, 0x03U,  // F0E NEGX.B D3
    0x91U, 0x01U,  // F10 SUBX.B D1,D0
    0xDFU, 0x0FU,  // F12 ADDX.B -(A7),-(A7)
    0xB5U, 0x4AU,  // F14 CMPM.W (A2)+,(A2)+
};
constexpr std::uint32_t first_root = base + 0x08U;
FrontendProgram program_with() {
  FrontendProgram program{};
  program.profile = M68kFrontendProfile::general_startup;
  program.image = {"synthetic/SEG-021-T014/extended-arithmetic-aot-fixture", image, image.size()};
  program.mapping_claims = {{"raw_cartridge_rom", {{}, base}, {{}, static_cast<std::uint32_t>(base + image.size())},
                             {0U}, {image.size()}}};
  program.startup_ingress = M68kStartupIngress{{{}, base}, 0x00FF0100U};
  return program;
}
}  // namespace extended_arithmetic_aot_fixture

int emit_extended_arithmetic_aot_source() {
  using namespace segarecomp;
  using namespace extended_arithmetic_aot_fixture;
  auto program = program_with();
  if (!apply_genesis_immutable_rom_aot(program)) return 4;
  const auto result = analyze_m68k_frontend(program);
  const auto *partial = std::get_if<FrontendPartialProgram>(&result);
  if (partial == nullptr) return 5;
  const auto emitted = expand_entry_rows(emit_m68k_general_startup_runtime_c(*partial));
  if (emitted.starts_with("/* translation rejected:")) return 6;
  std::cout << emitted;
  return 0;
}

void extended_arithmetic_forms_decode_lift_declare_effects_and_timing() {
  using namespace segarecomp;
  const auto decode_bytes = [](std::vector<std::uint8_t> bytes) {
    return decode_m68k_instruction(bytes, source(), M68kDecodeProfile::general_startup);
  };
  const auto width_of = [](unsigned field) {
    return field == 0U ? M68kMemoryAccessWidth::byte : field == 1U ? M68kMemoryAccessWidth::word
                                                                    : M68kMemoryAccessWidth::long_word;
  };
  for (const auto &[base, kind, ir] : std::array<std::tuple<unsigned, M68kInstructionKind, M68kIrKind>, 2>{{
           {0xD100U, M68kInstructionKind::add_extended, M68kIrKind::add_extended},
           {0x9100U, M68kInstructionKind::subtract_extended, M68kIrKind::subtract_extended}}}) {
    for (unsigned field = 0U; field < 3U; ++field)
      for (unsigned memory = 0U; memory < 2U; ++memory)
        for (unsigned rx = 0U; rx < 8U; ++rx)
          for (unsigned ry = 0U; ry < 8U; ++ry) {
            const unsigned word = base | (rx << 9U) | (field << 6U) | (memory << 3U) | ry;
            const auto decoded = decode_bytes({static_cast<std::uint8_t>(word >> 8U), static_cast<std::uint8_t>(word)});
            const auto *instruction = std::get_if<M68kDecodedInstruction>(&decoded);
            const auto mode = memory != 0U ? M68kEaMode::address_predec : M68kEaMode::data_register;
            const bool shape = instruction != nullptr && instruction->kind == kind &&
                               instruction->size == width_of(field) && instruction->source_ea.mode == mode &&
                               instruction->destination_ea.mode == mode && instruction->source_ea.reg == ry &&
                               instruction->destination_ea.reg == rx && instruction->provenance.length.value == 2U;
            expect(shape, "ADDX/SUBX decode Dy,Dx and -(Ay),-(Ax) for every size and register pair");
            if (!shape) continue;
            const auto operation = lift_m68k_instruction(*instruction);
            const auto effect = m68k_operation_effect(operation);
            const auto cycles = m68k_instruction_cycles(operation);
            const unsigned expected_cycles = memory != 0U ? (field == 2U ? 30U : 18U) : (field == 2U ? 8U : 4U);
            const auto a_mask = memory != 0U ? static_cast<std::uint8_t>((1U << ry) | (1U << rx)) : std::uint8_t{0};
            const auto d_mask = memory == 0U ? static_cast<std::uint8_t>(1U << rx) : std::uint8_t{0};
            expect(operation.kind == ir && effect.affects_condition_codes &&
                       effect.extend_flag_policy == M68kExtendFlagPolicy::from_carry &&
                       effect.register_write_footprint_complete && effect.address_register_write_mask == a_mask &&
                       effect.data_register_write_mask == d_mask && effect.pc == M68kPcEffectKind::advance &&
                       effect.pc_delta == 2U && cycles && *cycles == expected_cycles,
                   "ADDX/SUBX lift, declare complete CCR/register-write effects and publish Table 8-4 timing");
            expect(m68k_operation_is_immutable_rom_aot_safe(operation, false) &&
                       m68k_operation_has_complete_c_emission(operation),
                   "ADDX/SUBX are admitted to immutable-ROM AOT and have complete C emission");
          }
  }
  for (unsigned field = 0U; field < 3U; ++field)
    for (unsigned rx = 0U; rx < 8U; ++rx)
      for (unsigned ry = 0U; ry < 8U; ++ry) {
        const unsigned word = 0xB108U | (rx << 9U) | (field << 6U) | ry;
        const auto decoded = decode_bytes({static_cast<std::uint8_t>(word >> 8U), static_cast<std::uint8_t>(word)});
        const auto *instruction = std::get_if<M68kDecodedInstruction>(&decoded);
        expect(instruction != nullptr && instruction->kind == M68kInstructionKind::compare_memory &&
                   instruction->size == width_of(field) && instruction->source_ea.mode == M68kEaMode::address_postinc &&
                   instruction->destination_ea.mode == M68kEaMode::address_postinc &&
                   instruction->source_ea.reg == ry && instruction->destination_ea.reg == rx,
               "CMPM decodes (Ay)+,(Ax)+ for every size and register pair");
        if (instruction == nullptr) continue;
        const auto operation = lift_m68k_instruction(*instruction);
        const auto effect = m68k_operation_effect(operation);
        const auto cycles = m68k_instruction_cycles(operation);
        expect(operation.kind == M68kIrKind::compare_memory && effect.affects_condition_codes &&
                   effect.extend_flag_policy == M68kExtendFlagPolicy::preserve && effect.data_register_write_mask == 0U &&
                   effect.address_register_write_mask == static_cast<std::uint8_t>((1U << ry) | (1U << rx)) &&
                   cycles && *cycles == (field == 2U ? 20U : 12U) &&
                   m68k_operation_is_immutable_rom_aot_safe(operation, false) &&
                   m68k_operation_has_complete_c_emission(operation),
               "CMPM preserves X, declares both postincrement updates, publishes timing and is AOT-admitted");
      }
  // NEG (0x4400) and NEGX (0x4000) accept every size and every data-alterable EA including (d8,An,Xn).
  struct UnaryEa { std::vector<std::uint8_t> ext; unsigned mode_reg; M68kEaMode mode; };
  const std::vector<UnaryEa> eas{{{}, 0x00U, M68kEaMode::data_register},          {{}, 0x10U, M68kEaMode::address_indirect},
                                 {{}, 0x18U, M68kEaMode::address_postinc},        {{}, 0x20U, M68kEaMode::address_predec},
                                 {{0x00U, 0x10U}, 0x28U, M68kEaMode::address_disp16},
                                 {{0x10U, 0x04U}, 0x30U, M68kEaMode::address_index8},
                                 {{0x40U, 0x00U}, 0x38U, M68kEaMode::absolute_word},
                                 {{0x00U, 0xFFU, 0x00U, 0x80U}, 0x39U, M68kEaMode::absolute_long}};
  for (const auto &[base, kind, ir] : std::array<std::tuple<unsigned, M68kInstructionKind, M68kIrKind>, 2>{{
           {0x4400U, M68kInstructionKind::negate_word, M68kIrKind::negate_word},
           {0x4000U, M68kInstructionKind::negate_extended, M68kIrKind::negate_extended}}}) {
    for (unsigned field = 0U; field < 3U; ++field)
      for (const auto &ea : eas) {
        const unsigned word = base | (field << 6U) | ea.mode_reg;
        std::vector<std::uint8_t> bytes{static_cast<std::uint8_t>(word >> 8U), static_cast<std::uint8_t>(word)};
        bytes.insert(bytes.end(), ea.ext.begin(), ea.ext.end());
        const auto decoded = decode_bytes(bytes);
        const auto *instruction = std::get_if<M68kDecodedInstruction>(&decoded);
        expect(instruction != nullptr && instruction->kind == kind && instruction->size == width_of(field) &&
                   instruction->destination_ea.mode == ea.mode && instruction->provenance.length.value == bytes.size(),
               "NEG/NEGX decode every size and every data-alterable EA with exact provenance length");
        if (instruction == nullptr) continue;
        const auto operation = lift_m68k_instruction(*instruction);
        const auto effect = m68k_operation_effect(operation);
        expect(operation.kind == ir && effect.affects_condition_codes &&
                   effect.extend_flag_policy == M68kExtendFlagPolicy::from_carry &&
                   effect.register_write_footprint_complete && m68k_instruction_cycles(operation).has_value() &&
                   m68k_operation_is_immutable_rom_aot_safe(operation, false) &&
                   m68k_operation_has_complete_c_emission(operation),
               "NEG/NEGX declare subtraction effects, timing, AOT admission and complete C emission");
      }
    // An is never a legal operand; the immediate/PC-relative modes are not data alterable either.
    for (const unsigned illegal : {0x08U, 0x3AU, 0x3BU, 0x3CU}) {
      const auto rejected = decode_bytes({static_cast<std::uint8_t>((base | 0x40U | illegal) >> 8U),
                                          static_cast<std::uint8_t>(base | 0x40U | illegal), 0x00U, 0x00U});
      const auto *instruction = std::get_if<M68kDecodedInstruction>(&rejected);
      expect(instruction == nullptr || instruction->kind != kind,
             "NEG/NEGX reject An, PC-relative and immediate operands");
    }
    // Truncated extension: bounds-safe rejection.
    const auto truncated = decode_bytes({static_cast<std::uint8_t>((base | 0x69U) >> 8U), static_cast<std::uint8_t>(base | 0x69U)});
    const auto *failure = std::get_if<RejectedM68kDecode>(&truncated);
    expect(failure != nullptr && failure->outcome == DecodeOutcome::truncated_instruction,
           "NEG/NEGX d16(An) with a truncated extension word is a bounds-safe truncation");
  }
  // Neighbouring encodings keep their owners: size field 11 is ADDA/SUBA/CMPA/MOVE-from-SR, and
  // the non-pair bit patterns are ordinary ADD/EOR.
  const auto expect_kind = [&](std::vector<std::uint8_t> bytes, M68kInstructionKind kind, const char *message) {
    const auto decoded = decode_bytes(std::move(bytes));
    const auto *instruction = std::get_if<M68kDecodedInstruction>(&decoded);
    expect(instruction != nullptr && instruction->kind == kind, message);
  };
  expect_kind({0xD1U, 0xC8U}, M68kInstructionKind::adda, "0xD1C8 remains ADDA.L A0,A0");
  expect_kind({0x91U, 0xC8U}, M68kInstructionKind::suba, "0x91C8 remains SUBA.L A0,A0");
  expect_kind({0xB1U, 0xC8U}, M68kInstructionKind::cmpa, "0xB1C8 remains CMPA.L A0,A0");
  expect_kind({0xD1U, 0x20U}, M68kInstructionKind::add, "0xD120 remains ADD.B D0,-(A0)");
  expect_kind({0xB1U, 0x00U}, M68kInstructionKind::eor, "0xB100 remains EOR.B D0,D0");
  expect_kind({0x40U, 0xC0U}, M68kInstructionKind::move_from_sr, "0x40C0 remains MOVE from SR");
}

void extended_arithmetic_host_semantics_have_sticky_zero_and_carry_chains() {
  using namespace segarecomp;
  using K = M68kExtendedArithmeticKind;
  const auto b = M68kMemoryAccessWidth::byte;
  const auto w = M68kMemoryAccessWidth::word;
  const auto l = M68kMemoryAccessWidth::long_word;
  // Z is cleared by a non-zero result and otherwise left unchanged.
  expect(m68k_extended_arithmetic_ccr(0x2704U, K::add, 0U, 0U, b) == 0x2704U, "ADDX zero result keeps a set Z");
  expect(m68k_extended_arithmetic_ccr(0x2700U, K::add, 0U, 0U, b) == 0x2700U, "ADDX zero result keeps a clear Z");
  expect(m68k_extended_arithmetic_ccr(0x2704U, K::add, 1U, 1U, b) == 0x2700U, "ADDX non-zero result clears Z");
  // X is an input: 0xFF + 0x00 + X carries out to X and C and leaves Z untouched.
  expect(m68k_extended_arithmetic_ccr(0x2710U, K::add, 0U, 0xFFU, b) == 0x2711U, "ADDX.B 0xFF+0+X carries, Z clear");
  expect(m68k_extended_arithmetic_ccr(0x2714U, K::add, 0U, 0xFFU, b) == 0x2715U, "ADDX.B 0xFF+0+X carries, Z kept");
  expect(m68k_extended_arithmetic_ccr(0x2700U, K::add, 0U, 0xFFU, b) == 0x2708U, "ADDX.B 0xFF+0 (no X) is negative, no carry");
  // Signed overflow: 0x7F + 0 + X = 0x80.
  expect(m68k_extended_arithmetic_ccr(0x2710U, K::add, 0U, 0x7FU, b) == 0x270AU, "ADDX.B 0x7F+0+X overflows into N and V");
  // SUBX: dest - src - X.
  expect(m68k_extended_arithmetic_ccr(0x2710U, K::subtract, 0U, 0U, b) == 0x2719U, "SUBX.B 0-0-X borrows (X,N,C)");
  expect(m68k_extended_arithmetic_ccr(0x2710U, K::subtract, 0U, 0x80U, b) == 0x2702U, "SUBX.B 0x80-0-X overflows to V");
  expect(m68k_extended_arithmetic_ccr(0x2714U, K::subtract, 0U, 1U, b) == 0x2704U &&
             m68k_evaluate_extended_arithmetic(K::subtract, 0U, 1U, true, b).result == 0U,
         "SUBX.B 1-0-X is zero: Z kept, no borrow so X clears");
  // NEGX is SUBX with destination 0 and source = operand.
  expect(m68k_extended_arithmetic_ccr(0x2710U, K::subtract, 0U, 0U, w) == 0x2719U, "NEGX.W 0 with X gives 0xFFFF, X/N/C");
  expect(m68k_extended_arithmetic_ccr(0x2700U, K::subtract, 0x80000000U, 0U, l) == 0x271BU, "NEGX.L 0x80000000 sets X,N,V,C");
  // Upper bits of the operands beyond the operation width never matter.
  expect(m68k_extended_arithmetic_ccr(0x2710U, K::add, 0xABCD1200U, 0x00FFU, b) == 0x2711U, "ADDX.B ignores operand bits above bit 7");
  // 64-bit chain: (0xFFFFFFFF_FFFFFFFF) + 1 = 0 carry out; Z survives the ADDX because both halves are zero.
  std::uint16_t sr = 0x2704U;
  sr = m68k_addition_ccr(sr, 1U, 0xFFFFFFFFU, l);
  expect((sr & 0x10U) != 0U, "ADD.L low half carries into X");
  const auto high = m68k_evaluate_extended_arithmetic(K::add, 0U, 0xFFFFFFFFU, (sr & 0x10U) != 0U, l);
  sr = m68k_extended_arithmetic_ccr(sr, K::add, 0U, 0xFFFFFFFFU, l);
  expect(high.result == 0U && high.carry && (sr & 0x15U) == 0x15U, "ADDX.L high half completes the 64-bit carry chain with sticky Z");
  // A non-zero high half clears Z even when the low half was zero.
  sr = m68k_addition_ccr(0x2704U, 1U, 0xFFFFFFFFU, l);
  sr = m68k_extended_arithmetic_ccr(sr, K::add, 0U, 0xFFFFFFFEU, l);
  expect((sr & 0x04U) == 0U && (sr & 0x10U) == 0U, "a non-zero high half clears the chained Z and X");
  // 64-bit negate of 1: NEG.L low gives FFFFFFFF with borrow, NEGX.L high gives FFFFFFFF.
  sr = m68k_subtraction_ccr(0x2704U, 1U, 0U, l, M68kExtendFlagPolicy::from_carry);
  const auto negx_high = m68k_evaluate_extended_arithmetic(K::subtract, 0U, 0U, (sr & 0x10U) != 0U, l);
  expect((sr & 0x11U) == 0x11U && negx_high.result == 0xFFFFFFFFU, "NEG.L/NEGX.L propagate the borrow through X");
}

void extended_arithmetic_generated_c_defers_address_commit_and_handles_alias() {
  using namespace segarecomp;
  const auto lift = [](std::vector<std::uint8_t> bytes) {
    const auto decoded = std::get<M68kDecodedInstruction>(decode_m68k_instruction(bytes, source(), M68kDecodeProfile::general_startup));
    return lift_m68k_instruction(decoded);
  };
  // ADDX.B -(A7),-(A7): both operands step by two (A7 byte exception) and the aliased destination
  // starts from the already-updated source snapshot.
  {
    const GenesisM68kEmissionContext memory{"ram", "a", "fi", "fc", "fd", 0U, std::nullopt, 0U, {}, {}};
    const auto emitted = emit_m68k_operation_c(lift({0xDFU, 0x0FU}), "d", "sr", "", &memory);
    expect(emitted.find("m68k_xa_src_ea -= UINT32_C(2)") != std::string::npos &&
               emitted.find("uint32_t m68k_xa_dst_ea = m68k_xa_src_ea;") != std::string::npos &&
               emitted.find("m68k_xa_dst_ea -= UINT32_C(2)") != std::string::npos &&
               emitted.find("a[7] = m68k_xa_src_ea;") < emitted.find("a[7] = m68k_xa_dst_ea;"),
           "ADDX.B -(A7),-(A7) steps A7 by two per operand, aliases the destination snapshot and commits once per operand");
  }
  // Distinct registers do not alias, and word size steps by two, long by four.
  {
    const GenesisM68kEmissionContext memory{"ram", "a", "fi", "fc", "fd", 0U, std::nullopt, 0U, {}, {}};
    const auto emitted = emit_m68k_operation_c(lift({0x91U, 0x89U}), "d", "sr", "", &memory);  // SUBX.L -(A1),-(A0)
    expect(emitted.find("uint32_t m68k_xa_dst_ea = a[0];") != std::string::npos &&
               emitted.find("m68k_xa_src_ea -= UINT32_C(4)") != std::string::npos,
           "SUBX.L -(A1),-(A0) uses independent snapshots stepping by the operand width");
    const auto cmpm = emit_m68k_operation_c(lift({0xB1U, 0x09U}), "d", "sr", "", &memory);  // CMPM.B (A1)+,(A0)+
    expect(cmpm.find("m68k_xa_src_ea += UINT32_C(1)") != std::string::npos &&
               cmpm.find("m68k_xa_dst_ea += UINT32_C(1)") != std::string::npos &&
               cmpm.find("m68k_xa_result") == std::string::npos && cmpm.find("xa_result") == std::string::npos,
           "CMPM.B postincrements both snapshots and never computes or writes a result");
  }
  // Routed context: every routed failure return precedes the live An commits, which precede the PC advance.
  {
    GenesisM68kEmissionContext memory{"ram", "a", "fi", "fc", "fd", 0U, std::nullopt, 0U, {}, {}};
    memory.runtime_routing = true;
    memory.runtime_object = "runtime";
    memory.program_counter = "runtime->pc";
    const auto emitted = emit_m68k_operation_c(lift({0xD5U, 0x89U}), "runtime->d", "runtime->sr", "", &memory);  // ADDX.L -(A1),-(A2)
    const auto src_read = emitted.find("m68k_routed_addr_0 = (m68k_xa_src_ea)");
    const auto dst_read = emitted.find("m68k_routed_addr_3 = (m68k_xa_dst_ea)");
    const auto dst_write = emitted.find("m68k_routed_addr_6 = (m68k_xa_dst_ea)");
    const auto commit_src = emitted.find("a[1] = m68k_xa_src_ea;");
    const auto commit_dst = emitted.find("a[2] = m68k_xa_dst_ea;");
    const auto pc = emitted.find("runtime->pc +=");
    const auto npos = std::string::npos;
    expect(src_read != npos && dst_read != npos && dst_write != npos && commit_src != npos && commit_dst != npos &&
               pc != npos && src_read < emitted.find("return transfer;", src_read) &&
               emitted.find("return transfer;", src_read) < dst_read &&
               dst_read < emitted.find("return transfer;", dst_read) &&
               emitted.find("return transfer;", dst_read) < dst_write &&
               dst_write < emitted.find("return transfer;", dst_write) &&
               emitted.find("return transfer;", dst_write) < commit_src && commit_src < commit_dst && commit_dst < pc,
           "routed ADDX returns from each failed access before the next access, the An commits and the PC advance");
  }
}

void extended_arithmetic_aot_dispatch_is_admitted_end_to_end() {
  using namespace segarecomp;
  using namespace extended_arithmetic_aot_fixture;
  auto program = program_with();
  expect(apply_genesis_immutable_rom_aot_range(program, first_root, base + static_cast<std::uint32_t>(image.size())),
         "extended-arithmetic fixture range enumerates cleanly");
  const auto result = analyze_m68k_frontend(program);
  const auto *partial = std::get_if<FrontendPartialProgram>(&result);
  expect(partial != nullptr, "extended-arithmetic fixture remains a genuine partial program");
  if (partial == nullptr) return;
  const auto &roots = partial->accepted_prefix.immutable_rom_aot_entries;
  const auto emitted = expand_entry_rows(emit_m68k_general_startup_runtime_c(*partial));
  for (std::uint32_t address = first_root; address < base + image.size(); address += 2U) {
    expect(std::any_of(roots.begin(), roots.end(),
                       [&](const auto &root) { return root.decoded.provenance.source.address.value == address; }),
           "each extended-arithmetic form becomes a validated independent AOT root");
    std::ostringstream hex_address;
    hex_address << std::uppercase << std::hex << std::setw(8) << std::setfill('0') << address;
    const auto body = aot_function_effective_body(emitted, hex_address.str());
    expect(!body.empty() && body.find("translation rejected") == std::string::npos &&
               (body.find("genesis_route_access(runtime,") != std::string::npos) ==
                   (address != base + 0x0EU && address != base + 0x10U),  // NEGX.B Dn and SUBX.B Dy,Dx are register-only
           "each extended-arithmetic AOT body is emitted and routes exactly its memory operands");
  }
}

int c4_extended_arithmetic_admission() {
  using namespace segarecomp;
  // Every legal ADDX/SUBX/CMPM/NEGX/NEG shape (including the absolute and indexed NEG/NEGX operands, which need a
  // retained fact, and A7 byte steps) must pass the real C4 preflight with ZERO gap rows and emit a routed body.
  struct Case { const char *name; std::vector<std::uint8_t> code; const char *commit; bool routed; };
  const std::vector<Case> cases{
      {"ADDX.B D1,D2", {0xD5U, 0x01U}, nullptr, false},
      {"SUBX.W D1,D2", {0x95U, 0x41U}, nullptr, false},
      {"ADDX.L D1,D1", {0xD3U, 0x81U}, nullptr, false},
      {"ADDX.L -(A1),-(A2)", {0xD5U, 0x89U}, "runtime->a[2] = m68k_xa_dst_ea;", true},
      {"SUBX.B -(A7),-(A0)", {0x91U, 0x0FU}, "runtime->a[7] = m68k_xa_src_ea;", true},
      {"ADDX.B -(A7),-(A7)", {0xDFU, 0x0FU}, "runtime->a[7] = m68k_xa_dst_ea;", true},
      {"CMPM.W (A1)+,(A2)+", {0xB5U, 0x49U}, "runtime->a[2] = m68k_xa_dst_ea;", true},
      {"CMPM.B (A7)+,(A7)+", {0xBFU, 0x0FU}, "runtime->a[7] = m68k_xa_dst_ea;", true},
      {"NEGX.W D3", {0x40U, 0x43U}, nullptr, false},
      {"NEGX.B (A0)+", {0x40U, 0x18U}, "runtime->a[0] = m68k_neg_auto_ea;", true},
      {"NEGX.L -(A7)", {0x40U, 0xA7U}, "runtime->a[7] = m68k_neg_auto_ea;", true},
      {"NEGX.W (A0)", {0x40U, 0x50U}, nullptr, true},
      {"NEGX.W (16,A0)", {0x40U, 0x68U, 0x00U, 0x10U}, nullptr, true},
      {"NEGX.L (4,A0,D1.W)", {0x40U, 0xB0U, 0x10U, 0x04U}, nullptr, true},
      {"NEGX.W (0xFF0080).L", {0x40U, 0x79U, 0x00U, 0xFFU, 0x00U, 0x80U}, nullptr, true},
      {"NEGX.B (0xFF80).W", {0x40U, 0x38U, 0xFFU, 0x80U}, nullptr, true},
      {"NEG.B D3", {0x44U, 0x03U}, nullptr, false},
      {"NEG.L (0xFF0080).L", {0x44U, 0xB9U, 0x00U, 0xFFU, 0x00U, 0x80U}, nullptr, true},
      {"NEG.W (0xFF80).W", {0x44U, 0x78U, 0xFFU, 0x80U}, nullptr, true},
      {"NEG.L (4,A0,D1.W)", {0x44U, 0xB0U, 0x10U, 0x04U}, nullptr, true},
      {"NEG.W (A0)", {0x44U, 0x50U}, nullptr, true},
      {"NEG.W -(A0)", {0x44U, 0x60U}, "runtime->a[0] = m68k_neg_auto_ea;", true},
  };
  int failures = 0;
  for (const auto &test_case : cases) {
    FrontendProgram program{};
    program.profile = M68kFrontendProfile::general_startup;
    auto image = test_case.code;
    image.push_back(0x4EU);
    image.push_back(0x70U);  // RESET
    program.image = {"synthetic-c4-extended-arith", image, 0U};
    program.image.byte_length = program.image.bytes.size();
    program.mapping_claims = {{"synthetic-c4-extended-arith", {{}, 0xB00U},
                                {{}, static_cast<std::uint32_t>(0xB00U + program.image.bytes.size())},
                                {0U}, {program.image.bytes.size()}}};
    program.startup_ingress = M68kStartupIngress{{{}, 0xB00U}, 0x00FF0100U};
    const auto result = analyze_m68k_frontend(program);
    const auto *partial = std::get_if<FrontendPartialProgram>(&result);
    bool ok = partial != nullptr;
    std::string emitted;
    if (ok) {
      const auto preflight = preflight_m68k_general_startup_c4(*partial);
      ok = preflight.valid && preflight.rows.empty();
      emitted = expand_entry_rows(emit_m68k_general_startup_runtime_c(*partial));
      ok = ok && emitted.find("translation rejected") == std::string::npos &&
           emitted.find("GENESIS_C4_LOWERING_DIMENSIONS_") == std::string::npos &&
           emitted.find("genesis_c4_lowering_stop_") == std::string::npos &&
           (emitted.find("genesis_route_access") != std::string::npos) == test_case.routed &&
           (test_case.commit == nullptr || emitted.find(test_case.commit) != std::string::npos) &&
           emitted.find("runtime->runtime") == std::string::npos;
    }
    if (!ok) {
      std::cerr << "C4 extended-arithmetic admission failed: " << test_case.name << "\n";
      if (partial != nullptr) {
        const auto pf = preflight_m68k_general_startup_c4(*partial);
        std::cerr << " preflight valid=" << pf.valid << " rows=" << pf.rows.size() << "\n" << emitted.substr(0, 1800) << "\n";
      }
      ++failures;
    }
  }
  return failures == 0 ? 0 : 1;
}

// SEG-021-T015: ABCD/SBCD/NBCD. Legality is asserted from the Motorola encodings (ABCD `1100 Rx 1 0000 R Ry`, SBCD
// `1000 Rx 1 0000 R Ry`, NBCD `0100 1000 00 ea` data-alterable), independently of the T001 dataset.
namespace bcd_aot_fixture {
using namespace segarecomp;
constexpr std::uint32_t base = 0x00000F00U;
const std::vector<std::uint8_t> image{
    0x30U, 0x51U, 0x4EU, 0x90U, 0x4EU, 0x71U, 0x60U, 0xF8U,
    0xC1U, 0x09U,  // F08 ABCD.B -(A1),-(A0)
    0x81U, 0x09U,  // F0A SBCD.B -(A1),-(A0)
    0x48U, 0x18U,  // F0C NBCD.B (A0)+
    0x48U, 0x03U,  // F0E NBCD.B D3
    0xC1U, 0x01U,  // F10 ABCD.B D1,D0
    0x8FU, 0x0FU,  // F12 SBCD.B -(A7),-(A7)
    0x48U, 0x22U,  // F14 NBCD.B -(A2)
};
constexpr std::uint32_t first_root = base + 0x08U;
FrontendProgram program_with() {
  FrontendProgram program{};
  program.profile = M68kFrontendProfile::general_startup;
  program.image = {"synthetic/SEG-021-T015/bcd-aot-fixture", image, image.size()};
  program.mapping_claims = {{"raw_cartridge_rom", {{}, base}, {{}, static_cast<std::uint32_t>(base + image.size())},
                             {0U}, {image.size()}}};
  program.startup_ingress = M68kStartupIngress{{{}, base}, 0x00FF0100U};
  return program;
}
}  // namespace bcd_aot_fixture

int emit_bcd_aot_source() {
  using namespace segarecomp;
  using namespace bcd_aot_fixture;
  auto program = program_with();
  if (!apply_genesis_immutable_rom_aot(program)) return 4;
  const auto result = analyze_m68k_frontend(program);
  const auto *partial = std::get_if<FrontendPartialProgram>(&result);
  if (partial == nullptr) return 5;
  const auto emitted = expand_entry_rows(emit_m68k_general_startup_runtime_c(*partial));
  if (emitted.starts_with("/* translation rejected:")) return 6;
  std::cout << emitted;
  return 0;
}

void bcd_forms_decode_lift_declare_effects_and_timing() {
  using namespace segarecomp;
  const auto decode_bytes = [](std::vector<std::uint8_t> bytes) {
    return decode_m68k_instruction(bytes, source(), M68kDecodeProfile::general_startup);
  };
  for (const auto &[base, kind, ir] : std::array<std::tuple<unsigned, M68kInstructionKind, M68kIrKind>, 2>{{
           {0xC100U, M68kInstructionKind::add_decimal, M68kIrKind::add_decimal},
           {0x8100U, M68kInstructionKind::subtract_decimal, M68kIrKind::subtract_decimal}}}) {
    for (unsigned memory = 0U; memory < 2U; ++memory)
      for (unsigned rx = 0U; rx < 8U; ++rx)
        for (unsigned ry = 0U; ry < 8U; ++ry) {
          const unsigned word = base | (rx << 9U) | (memory << 3U) | ry;
          const auto decoded = decode_bytes({static_cast<std::uint8_t>(word >> 8U), static_cast<std::uint8_t>(word)});
          const auto *instruction = std::get_if<M68kDecodedInstruction>(&decoded);
          const auto mode = memory != 0U ? M68kEaMode::address_predec : M68kEaMode::data_register;
          const bool shape = instruction != nullptr && instruction->kind == kind &&
                             instruction->size == M68kMemoryAccessWidth::byte && instruction->source_ea.mode == mode &&
                             instruction->destination_ea.mode == mode && instruction->source_ea.reg == ry &&
                             instruction->destination_ea.reg == rx && instruction->provenance.length.value == 2U;
          expect(shape, "ABCD/SBCD decode Dy,Dx and -(Ay),-(Ax) for every register pair (byte only)");
          if (!shape) continue;
          const auto operation = lift_m68k_instruction(*instruction);
          const auto effect = m68k_operation_effect(operation);
          const auto cycles = m68k_instruction_cycles(operation);
          const auto a_mask = memory != 0U ? static_cast<std::uint8_t>((1U << ry) | (1U << rx)) : std::uint8_t{0};
          const auto d_mask = memory == 0U ? static_cast<std::uint8_t>(1U << rx) : std::uint8_t{0};
          expect(operation.kind == ir && effect.affects_condition_codes &&
                     effect.extend_flag_policy == M68kExtendFlagPolicy::from_carry &&
                     effect.register_write_footprint_complete && effect.address_register_write_mask == a_mask &&
                     effect.data_register_write_mask == d_mask && effect.pc == M68kPcEffectKind::advance &&
                     effect.pc_delta == 2U && cycles && *cycles == (memory != 0U ? 18U : 6U),
                 "ABCD/SBCD lift, declare complete CCR/register-write effects and publish Table 8-4 timing");
          expect(m68k_operation_is_immutable_rom_aot_safe(operation, false) &&
                     m68k_operation_has_complete_c_emission(operation),
                 "ABCD/SBCD are admitted to immutable-ROM AOT and have complete C emission");
        }
    // Word/long size encodings of these opcode groups are other instructions (MULU/EXG/ADD...), never ABCD/SBCD.
    for (const unsigned other : {0x0040U, 0x0080U}) {
      const auto decoded = decode_bytes({static_cast<std::uint8_t>((base | other) >> 8U), static_cast<std::uint8_t>(base | other)});
      const auto *instruction = std::get_if<M68kDecodedInstruction>(&decoded);
      expect(instruction == nullptr || (instruction->kind != M68kInstructionKind::add_decimal &&
                                        instruction->kind != M68kInstructionKind::subtract_decimal),
             "non-byte opmodes are never ABCD/SBCD");
    }
  }
  struct UnaryEa { std::vector<std::uint8_t> ext; unsigned mode_reg; M68kEaMode mode; unsigned cycles; };
  const std::vector<UnaryEa> eas{{{}, 0x00U, M68kEaMode::data_register, 6U},   {{}, 0x10U, M68kEaMode::address_indirect, 12U},
                                 {{}, 0x18U, M68kEaMode::address_postinc, 12U}, {{}, 0x20U, M68kEaMode::address_predec, 14U},
                                 {{0x00U, 0x10U}, 0x28U, M68kEaMode::address_disp16, 16U},
                                 {{0x10U, 0x04U}, 0x30U, M68kEaMode::address_index8, 18U},
                                 {{0x40U, 0x00U}, 0x38U, M68kEaMode::absolute_word, 16U},
                                 {{0x00U, 0xFFU, 0x00U, 0x80U}, 0x39U, M68kEaMode::absolute_long, 20U}};
  for (const auto &ea : eas) {
    const unsigned word = 0x4800U | ea.mode_reg;
    std::vector<std::uint8_t> bytes{static_cast<std::uint8_t>(word >> 8U), static_cast<std::uint8_t>(word)};
    bytes.insert(bytes.end(), ea.ext.begin(), ea.ext.end());
    const auto decoded = decode_bytes(bytes);
    const auto *instruction = std::get_if<M68kDecodedInstruction>(&decoded);
    expect(instruction != nullptr && instruction->kind == M68kInstructionKind::negate_decimal &&
               instruction->size == M68kMemoryAccessWidth::byte && instruction->destination_ea.mode == ea.mode &&
               instruction->provenance.length.value == bytes.size(),
           "NBCD decodes every data-alterable EA with exact provenance length");
    if (instruction == nullptr) continue;
    const auto operation = lift_m68k_instruction(*instruction);
    const auto effect = m68k_operation_effect(operation);
    const auto cycles = m68k_instruction_cycles(operation);
    expect(operation.kind == M68kIrKind::negate_decimal && effect.affects_condition_codes &&
               effect.extend_flag_policy == M68kExtendFlagPolicy::from_carry && effect.register_write_footprint_complete &&
               cycles && *cycles == ea.cycles && m68k_operation_is_immutable_rom_aot_safe(operation, false) &&
               m68k_operation_has_complete_c_emission(operation),
           "NBCD declares effects, Table 8-6 timing (Dn 6, memory 8+EA), AOT admission and complete C emission");
  }
  for (const unsigned illegal : {0x08U, 0x3AU, 0x3BU, 0x3CU}) {
    const auto rejected = decode_bytes({0x48U, static_cast<std::uint8_t>(0x00U | illegal), 0x00U, 0x00U});
    const auto *instruction = std::get_if<M68kDecodedInstruction>(&rejected);
    expect(instruction == nullptr || instruction->kind != M68kInstructionKind::negate_decimal,
           "NBCD rejects An, PC-relative and immediate operands");
  }
  const auto truncated = decode_bytes({0x48U, 0x28U});
  const auto *failure = std::get_if<RejectedM68kDecode>(&truncated);
  expect(failure != nullptr && failure->outcome == DecodeOutcome::truncated_instruction,
         "NBCD d16(An) with a truncated extension word is a bounds-safe truncation");
  // Neighbouring encodings keep their owners.
  const auto expect_kind = [&](std::vector<std::uint8_t> bytes, M68kInstructionKind kind, const char *message) {
    const auto decoded = decode_bytes(std::move(bytes));
    const auto *instruction = std::get_if<M68kDecodedInstruction>(&decoded);
    expect(instruction != nullptr && instruction->kind == kind, message);
  };
  expect_kind({0x48U, 0x40U}, M68kInstructionKind::swap, "0x4840 remains SWAP D0");
  expect_kind({0x48U, 0x50U}, M68kInstructionKind::pea, "0x4850 remains PEA (A0)");
  expect_kind({0xC1U, 0xC0U}, M68kInstructionKind::multiply_signed_word, "0xC1C0 remains MULS.W D0,D0");
  expect_kind({0xC1U, 0x10U}, M68kInstructionKind::logical_and, "0xC110 remains AND.B D0,(A0)");
  expect_kind({0x81U, 0x10U}, M68kInstructionKind::logical_or, "0x8110 remains OR.B D0,(A0)");
}

void bcd_host_semantics_have_documented_results_sticky_zero_and_matched_undefined_flags() {
  using namespace segarecomp;
  using K = M68kDecimalArithmeticKind;
  const auto eval = [](K kind, std::uint32_t src, std::uint32_t dst, bool x) {
    return m68k_evaluate_decimal_arithmetic(kind, src, dst, x);
  };
  // Documented results (X, C, byte result, Z rule).
  auto r = eval(K::add, 0x01U, 0x99U, false);
  expect(r.result == 0x00U && r.carry && !r.clears_zero, "ABCD 99+01 = 00 with decimal carry, Z not cleared");
  r = eval(K::add, 0x09U, 0x00U, true);
  expect(r.result == 0x10U && !r.carry && r.clears_zero, "ABCD 00+09+X = 10 (nibble carry), no decimal carry");
  r = eval(K::add, 0x09U, 0x19U, false);
  expect(r.result == 0x28U && !r.carry, "ABCD 19+09 = 28");
  r = eval(K::add, 0x05U, 0x95U, true);
  expect(r.result == 0x01U && r.carry, "ABCD 95+05+X = 01 with carry");
  r = eval(K::subtract, 0x01U, 0x00U, false);
  expect(r.result == 0x99U && r.carry && r.clears_zero, "SBCD 00-01 = 99 with decimal borrow");
  r = eval(K::subtract, 0x01U, 0x10U, false);
  expect(r.result == 0x09U && !r.carry, "SBCD 10-01 = 09");
  r = eval(K::subtract, 0x55U, 0x45U, false);
  expect(r.result == 0x90U && r.carry, "SBCD 45-55 = 90 with borrow");
  r = eval(K::subtract, 0x05U, 0x03U, true);
  expect(r.result == 0x97U && r.carry, "SBCD 03-05-X = 97 with borrow");
  r = eval(K::negate, 0U, 0x01U, false);
  expect(r.result == 0x99U && r.carry && r.clears_zero, "NBCD 01 = 99 with borrow");
  r = eval(K::negate, 0U, 0x90U, false);
  expect(r.result == 0x10U && r.carry, "NBCD 90 = 10 (low-nibble 0xA correction)");
  r = eval(K::negate, 0U, 0x99U, true);
  expect(r.result == 0x00U && r.carry && !r.clears_zero, "NBCD 99 with X = 00, X/C set, Z not cleared");
  r = eval(K::negate, 0U, 0x00U, true);
  expect(r.result == 0x99U && r.carry, "NBCD 00 with X = 99 with borrow");
  // NBCD of zero without X: nothing to negate; byte unchanged, X/C clear (the documented, defined part).
  r = eval(K::negate, 0U, 0x00U, false);
  expect(r.result == 0x00U && !r.carry && !r.clears_zero, "NBCD 00 without X leaves 00, X/C clear, Z unchanged");
  // Upper bits beyond the byte never matter.
  r = eval(K::add, 0xABCD1201U, 0x77665599U, false);
  expect(r.result == 0x00U && r.carry, "ABCD ignores operand bits above bit 7");
  // Sticky Z and X/C via the whole CCR update (X/C/Z documented; N/V matched-to-Musashi policy, undefined on 68000).
  expect(m68k_decimal_arithmetic_ccr(0x2704U, K::add, 0U, 0U) == 0x2704U, "ABCD zero result keeps a set Z");
  expect(m68k_decimal_arithmetic_ccr(0x2700U, K::add, 0U, 0U) == 0x2700U, "ABCD zero result keeps a clear Z");
  expect(m68k_decimal_arithmetic_ccr(0x2704U, K::add, 0x01U, 0x01U) == 0x2700U, "ABCD non-zero result clears Z");
  expect(m68k_decimal_arithmetic_ccr(0x2714U, K::add, 0x01U, 0x98U) == 0x2715U, "ABCD 98+01+X = 00 carries into X/C, Z kept");
  expect(m68k_decimal_arithmetic_ccr(0x2700U, K::subtract, 0x01U, 0x00U) == 0x2719U, "SBCD 00-01 sets X, N(policy), C");
  expect(m68k_decimal_arithmetic_ccr(0x2704U, K::negate, 0U, 0x00U) == 0x270CU,
         "NBCD 00 without X: X/C clear, Z kept, N set (matched-to-Musashi undefined-flag policy)");
  expect(m68k_decimal_arithmetic_ccr(0x2714U, K::negate, 0U, 0x99U) == 0x2715U, "NBCD 99 with X = 00: X/C set, Z kept");
  // Garbage seeds: 00+00+X(1)=01 clears the seed Z/N/V/C, re-derives them and sets X/C only when carrying (no carry: X clear).
  expect(m68k_decimal_arithmetic_ccr(0x271FU, K::add, 0U, 0U) == 0x2700U,
         "ABCD 00+00+X=01: X/C cleared, Z cleared, garbage N/V/C seeds replaced");
}

void bcd_generated_c_defers_address_commit_and_handles_alias() {
  using namespace segarecomp;
  const auto lift = [](std::vector<std::uint8_t> bytes) {
    const auto decoded = std::get<M68kDecodedInstruction>(decode_m68k_instruction(bytes, source(), M68kDecodeProfile::general_startup));
    return lift_m68k_instruction(decoded);
  };
  {
    const GenesisM68kEmissionContext memory{"ram", "a", "fi", "fc", "fd", 0U, std::nullopt, 0U, {}, {}};
    const auto emitted = emit_m68k_operation_c(lift({0x8FU, 0x0FU}), "d", "sr", "", &memory);  // SBCD.B -(A7),-(A7)
    expect(emitted.find("m68k_xa_src_ea -= UINT32_C(2)") != std::string::npos &&
               emitted.find("uint32_t m68k_xa_dst_ea = m68k_xa_src_ea;") != std::string::npos &&
               emitted.find("m68k_xa_dst_ea -= UINT32_C(2)") != std::string::npos &&
               emitted.find("a[7] = m68k_xa_src_ea;") < emitted.find("a[7] = m68k_xa_dst_ea;") &&
               emitted.find("bcd_result") != std::string::npos,
           "SBCD.B -(A7),-(A7) steps A7 by two per operand, aliases the destination snapshot and commits once per operand");
    const auto nbcd = emit_m68k_operation_c(lift({0x48U, 0x27U}), "d", "sr", "", &memory);  // NBCD.B -(A7)
    expect(nbcd.find("bcd_result") != std::string::npos && nbcd.find("m68k_neg_auto_ea -= UINT32_C(2)") != std::string::npos,
           "NBCD.B -(A7) uses the shared one-address RMW lowering with the A7 byte step of two");
  }
  {
    GenesisM68kEmissionContext memory{"ram", "a", "fi", "fc", "fd", 0U, std::nullopt, 0U, {}, {}};
    memory.runtime_routing = true;
    memory.runtime_object = "runtime";
    memory.program_counter = "runtime->pc";
    const auto emitted = emit_m68k_operation_c(lift({0xC5U, 0x09U}), "runtime->d", "runtime->sr", "", &memory);  // ABCD -(A1),-(A2)
    const auto src_read = emitted.find("m68k_routed_addr_0 = (m68k_xa_src_ea)");
    const auto dst_read = emitted.find("m68k_routed_addr_3 = (m68k_xa_dst_ea)");
    const auto dst_write = emitted.find("m68k_routed_addr_6 = (m68k_xa_dst_ea)");
    const auto commit_src = emitted.find("a[1] = m68k_xa_src_ea;");
    const auto commit_dst = emitted.find("a[2] = m68k_xa_dst_ea;");
    const auto pc = emitted.find("runtime->pc +=");
    const auto npos = std::string::npos;
    expect(src_read != npos && dst_read != npos && dst_write != npos && commit_src != npos && commit_dst != npos &&
               pc != npos && src_read < emitted.find("return transfer;", src_read) &&
               emitted.find("return transfer;", src_read) < dst_read &&
               dst_read < emitted.find("return transfer;", dst_read) &&
               emitted.find("return transfer;", dst_read) < dst_write &&
               dst_write < emitted.find("return transfer;", dst_write) &&
               emitted.find("return transfer;", dst_write) < commit_src && commit_src < commit_dst && commit_dst < pc,
           "routed ABCD returns from each failed access before the next access, the An commits and the PC advance");
  }
}

void bcd_aot_dispatch_is_admitted_end_to_end() {
  using namespace segarecomp;
  using namespace bcd_aot_fixture;
  auto program = program_with();
  expect(apply_genesis_immutable_rom_aot_range(program, first_root, base + static_cast<std::uint32_t>(image.size())),
         "BCD fixture range enumerates cleanly");
  const auto result = analyze_m68k_frontend(program);
  const auto *partial = std::get_if<FrontendPartialProgram>(&result);
  expect(partial != nullptr, "BCD fixture remains a genuine partial program");
  if (partial == nullptr) return;
  const auto &roots = partial->accepted_prefix.immutable_rom_aot_entries;
  const auto emitted = expand_entry_rows(emit_m68k_general_startup_runtime_c(*partial));
  for (std::uint32_t address = first_root; address < base + image.size(); address += 2U) {
    expect(std::any_of(roots.begin(), roots.end(),
                       [&](const auto &root) { return root.decoded.provenance.source.address.value == address; }),
           "each BCD form becomes a validated independent AOT root");
    std::ostringstream hex_address;
    hex_address << std::uppercase << std::hex << std::setw(8) << std::setfill('0') << address;
    const auto body = aot_function_effective_body(emitted, hex_address.str());
    expect(!body.empty() && body.find("translation rejected") == std::string::npos &&
               (body.find("genesis_route_access(runtime,") != std::string::npos) ==
                   (address != base + 0x0EU && address != base + 0x10U),  // NBCD Dn and ABCD Dy,Dx are register-only
           "each BCD AOT body is emitted and routes exactly its memory operands");
  }
}

int c4_bcd_admission() {
  using namespace segarecomp;
  // Every legal ABCD/SBCD/NBCD shape (including the absolute and indexed NBCD operands, which need a retained fact, and
  // A7 byte steps) must pass the real C4 preflight with ZERO gap rows and emit a routed body.
  struct Case { const char *name; std::vector<std::uint8_t> code; const char *commit; bool routed; };
  const std::vector<Case> cases{
      {"ABCD.B D1,D2", {0xC5U, 0x01U}, nullptr, false},
      {"SBCD.B D1,D1", {0x83U, 0x01U}, nullptr, false},
      {"ABCD.B -(A1),-(A2)", {0xC5U, 0x09U}, "runtime->a[2] = m68k_xa_dst_ea;", true},
      {"SBCD.B -(A7),-(A0)", {0x81U, 0x0FU}, "runtime->a[7] = m68k_xa_src_ea;", true},
      {"SBCD.B -(A7),-(A7)", {0x8FU, 0x0FU}, "runtime->a[7] = m68k_xa_dst_ea;", true},
      {"ABCD.B -(A7),-(A7)", {0xCFU, 0x0FU}, "runtime->a[7] = m68k_xa_dst_ea;", true},
      {"NBCD.B D3", {0x48U, 0x03U}, nullptr, false},
      {"NBCD.B (A0)+", {0x48U, 0x18U}, "runtime->a[0] = m68k_neg_auto_ea;", true},
      {"NBCD.B -(A7)", {0x48U, 0x27U}, "runtime->a[7] = m68k_neg_auto_ea;", true},
      {"NBCD.B (A0)", {0x48U, 0x10U}, nullptr, true},
      {"NBCD.B (16,A0)", {0x48U, 0x28U, 0x00U, 0x10U}, nullptr, true},
      {"NBCD.B (4,A0,D1.W)", {0x48U, 0x30U, 0x10U, 0x04U}, nullptr, true},
      {"NBCD.B (0xFF0080).L", {0x48U, 0x39U, 0x00U, 0xFFU, 0x00U, 0x80U}, nullptr, true},
      {"NBCD.B (0xFF80).W", {0x48U, 0x38U, 0xFFU, 0x80U}, nullptr, true},
  };
  int failures = 0;
  for (const auto &test_case : cases) {
    FrontendProgram program{};
    program.profile = M68kFrontendProfile::general_startup;
    auto image = test_case.code;
    image.push_back(0x4EU);
    image.push_back(0x70U);  // RESET
    program.image = {"synthetic-c4-bcd", image, 0U};
    program.image.byte_length = program.image.bytes.size();
    program.mapping_claims = {{"synthetic-c4-bcd", {{}, 0xB00U},
                                {{}, static_cast<std::uint32_t>(0xB00U + program.image.bytes.size())},
                                {0U}, {program.image.bytes.size()}}};
    program.startup_ingress = M68kStartupIngress{{{}, 0xB00U}, 0x00FF0100U};
    const auto result = analyze_m68k_frontend(program);
    const auto *partial = std::get_if<FrontendPartialProgram>(&result);
    bool ok = partial != nullptr;
    std::string emitted;
    if (ok) {
      const auto preflight = preflight_m68k_general_startup_c4(*partial);
      ok = preflight.valid && preflight.rows.empty();
      emitted = expand_entry_rows(emit_m68k_general_startup_runtime_c(*partial));
      ok = ok && emitted.find("translation rejected") == std::string::npos &&
           emitted.find("GENESIS_C4_LOWERING_DIMENSIONS_") == std::string::npos &&
           emitted.find("genesis_c4_lowering_stop_") == std::string::npos &&
           (emitted.find("genesis_route_access") != std::string::npos) == test_case.routed &&
           (test_case.commit == nullptr || emitted.find(test_case.commit) != std::string::npos) &&
           emitted.find("runtime->runtime") == std::string::npos;
    }
    if (!ok) {
      std::cerr << "C4 BCD admission failed: " << test_case.name << "\n";
      ++failures;
    }
  }
  return failures == 0 ? 0 : 1;
}

