void unreachable_component_is_peeled_while_rooted_component_survives() {
  constexpr std::uint32_t base = 0x0000F600U;
  auto image = chain_image();
  const auto second_offset = static_cast<std::uint32_t>(image.size());
  const auto second = chain_image();
  image.insert(image.end(), second.begin(), second.end());
  auto program = make_program(base, image, "synthetic/SEG-007-T234/forced-unreachable-component",
                              {make_candidate(base + 0x4U), make_candidate(base + second_offset + 0x4U)});
  const auto rooted_a = base + 0x4U;
  const auto rooted_a_leaf = base + 0xAU;
  const auto unreachable_b = base + second_offset + 0x4U;
  const auto unreachable_b_leaf = base + second_offset + 0xAU;
  program.adr0038_synthetic_test_control.emplace();
  program.adr0038_synthetic_test_control->additionally_unreachable_retained_entries.push_back(unreachable_b);
  const auto result = analyze_m68k_frontend(program);
  const auto *partial = std::get_if<FrontendPartialProgram>(&result);
  expect(partial != nullptr, "SEG-007-T234 (component peel): fixture reaches a partial program");
  if (partial == nullptr) return;
  const auto &m = partial->accepted_prefix.offline_inventory_stitch_metrics;
  expect(has_block(partial->accepted_prefix, rooted_a) &&
             known_but_unemitted_frontier_count(*partial, rooted_a_leaf) == 1U,
         "SEG-007-T234 (component peel): rooted A and its proposal survive unchanged");
  expect(!has_block(partial->accepted_prefix, unreachable_b) &&
             !has_any_frontier_for(*partial, unreachable_b_leaf),
         "SEG-007-T234 (component peel): whole unreachable B and its B-only dependency are removed");
  std::uint32_t component_size_total = 0U;
  for (const auto size : m.adr0038_peeled_component_sizes) component_size_total += size;
  expect(m.adr0038_peeled_component_count == m.adr0038_peeled_component_sizes.size() &&
             m.adr0038_peeled_component_count >= 1U &&
             component_size_total == m.adr0038_peeled_node_count && m.adr0038_peeled_node_count >= 1U,
          "SEG-007-T234 (component peel): metrics record every deterministic component size and total");
}

